window.JASTROW_CHUNKS[35]={"14000":{"h":"טְרִיפוֹן","r":"I00813","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>T’rifon</i>. <span class=\"citation\">Y. Bicc. II, beg. 64ᶜ</span></div>","alt":[]},"14001":{"h":"*טְרִיפְתָּא","r":"I00814","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טַרְפָא I\">טְרַף</a>) <i>vagrancy, irregular life</i>. Pesik. B’shall., p. 93ᵃ <span dir=\"rtl\">כל הדא ט׳ להן לך</span> whither will all this irregular life lead thee?</div>","alt":[]},"14002":{"h":"טְרֵיפְתָּא","r":"I00815","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <span class=\"citation\">Ḥull. 94ᵇ</span>.—Pl. <a href=\"#\" data-headword=\"טְרֵיפָא\">טְרֵיפָן</a>, <a href=\"#\" data-headword=\"טְרֵיפְתָּא\">טְרֵיפָתָא</a>. <span class=\"citation\">Targ. Y. Lev. XI, 1</span>; <span class=\"citation\">Targ. Y. Num. XIX, 3</span> (some ed. <a href=\"#\" data-headword=\"טְרִיפָה\">טְרִיפָן</a>, v. <span class=\"citation\">Ḥull. 42ᵃ</span> <span dir=\"rtl\">י&quot;ח טרפות</span>).</div>","alt":["טְרִיפָא"]},"14003":{"h":"טְרִיקָא","r":"I00816","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (טְרַק II) <i>enclosure, prison</i>. <span class=\"citation\">Targ. Lam. III, 7</span>.</div>","alt":[]},"14004":{"h":"טְרִיקְטָא","r":"I00817","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (tracta) <i>a long piece of dough pulled out in making pastry</i> (<i>tracta</i> or <i>tractum</i>). <span class=\"citation\">Y. Ḥall. I, 57ᵈ</span> ר׳ יוחנן אמר טריק׳ חייבת וכ׳ R. J. says, <i>tracta</i> is subject to <i>Ḥallah;</i> <span class=\"citation\">Ber. 37ᵇ</span> כי אתא … אמר ר׳ יוחנן טרקנין חייבת וכ׳ Ms. M. (corr. acc.; v. Rabb. D. S. a. l. note 6; ed. <span dir=\"rtl\">טרוקנין פטורין</span>) when R. … came to Babylonia from Palestine, he related in behalf of R. J. &amp;c. <span class=\"citation\">Y. Pes. III, 30ᵃ</span> <span dir=\"rtl\">טרקטה הורי וכ׳</span> as to <i>tracta</i></div>","alt":["טְרַקְטָהִ"]},"14005":{"h":"טריקטי","r":"I00818","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טְרוֹקְטִי\">טְרוֹקְטִי</a></div>","alt":[]},"14006":{"h":"טְרִיקַיָּיא","r":"I00819","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (טְרַק I <i>to sting</i>) a sort of <i>wasps</i>. <span class=\"citation\">Targ. Y. Deut. VII, 20</span> (a gloss to <span dir=\"rtl\">אורעייתא</span>, h text <a href=\"#\" data-headword=\"צִרְעָה\">צרעה</a>).</div>","alt":[]},"14007":{"h":"טריקלונא","r":"I00820","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טְרִיקְלִינָא\">טְרִיקְלינָא</a></div>","alt":[]},"14008":{"h":"טְרִיקְלִילִין","r":"I00821","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טְרַקְלִילָא\">טְרַקְלִילָא</a></div>","alt":[]},"14009":{"h":"טְרִיקְלִין","r":"I00822","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (τρικλίνιον, triclinium) l) <i>dining couch</i>. <span class=\"citation\">Y. Ḥag. II, 77ᵃ</span> bot. <span dir=\"rtl\">הט׳ מוצע לכם</span> the banqueting couch is spread for you (your reward in the hereafter is prepared).—2) <i>dining room, reception room</i>. <span class=\"citation\">Y. R. Hash. IV, 59ᵇ</span> bot. <span dir=\"rtl\">אפ׳ מט׳ לקיטון</span> even if they adjourned from the tricl. to the sleeping room. <span class=\"citation\">Y. Keth. IV, 28ᵈ</span>; <span class=\"citation\">Y. Snh. XI, end, 30ᶜ</span> [read:] <span dir=\"rtl\">בעיא הדא אומנתא ט׳ וקיטין חופה וקיטון וכ׳</span> the following construction is required (in order to make the reception of the bride in the triclinium a legal consummation of marriage) a tricl. and a marriage chamber, and that chamber communicating with the tricl.—<span class=\"citation\">Ab. IV, 16</span>, v. <a href=\"#\" data-headword=\"פְּרוֹזְדּוֹר\">פְּרוֹזְדּוֹר</a>.—<span class=\"citation\">Tosef. Sabb. XVI</span> (<span class=\"citation\">XVII), 18</span> <span dir=\"rtl\">ט׳ שהסיקה … בה</span> in a banqueting room (triclinium hibernum) which has been heated a day before …, you may entertain company on the Sabbath. <span class=\"citation\">Tosef. Bets. II, 10</span> <span dir=\"rtl\">ט׳ שהסיקוהו וכ׳</span>; a. e.—3) (τρίκλινος = ὅρριον, S.) <i>granary</i>. <span class=\"citation\">Y. Sot. V, 20ᵇ</span> bot. <span dir=\"rtl\">איטלק עלוי חד ט׳ וכ׳</span></div>","alt":["טְרַקְלִין"]},"14010":{"h":"טְרִיקְלִינָא","r":"I00823","html":"<div class=\"sense\"> Targ. II Esth. VII, 8 <span dir=\"rtl\">טרקלו׳</span> (corr. acc.)—<span class=\"citation\">Lev. R. s. 16</span> <span dir=\"rtl\">בטְרִיקְלִינֵיה</span> (some ed. <span dir=\"rtl\">בתורק׳</span>, corr. acc.) in his reception room.—Pl. <a href=\"#\" data-headword=\"טְרִיקְלִילִין\">טְרִיקְלִינִין</a>, <a href=\"#\" data-headword=\"טְרִיקְלִינָא\">טְרַקְ׳</a>. <span class=\"citation\">Targ. Y. I Num. XXXI, 50</span>.</div>","alt":["טְרַקְ׳"]},"14011":{"h":"טריקסימון","r":"I00824","html":"<div class=\"sense\">, v. <span dir=\"rtl\">טְרוֹקְ׳</span></div>","alt":[]},"14012":{"h":"טְרִיקְסִין","r":"I00825","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טְרַקְסִין\">טְרַקְסִין</a></div>","alt":[]},"14013":{"h":"טָרִית","r":"I00826","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">נטר</span>, cmp. <a href=\"#\" data-headword=\"אִטְּרִי\">אִטְּרִי</a>) <i>preserve, pickle</i>, esp. <i>salted</i> or <i>pickled fish</i>. <span class=\"citation\">Meg. 6ᵃ</span> טמוני זו ט׳ ‘stored things’ (<span class=\"citation\">Deut. XXXIII, 19</span>) refers to <i>tarith</i> (as a valuable article of commerce); <span class=\"citation\">Sifré Deut. 354</span>; <span class=\"citation\">Num. R. s. 13</span>.—<span class=\"citation\">Ab. Zar. II, 6</span> <span dir=\"rtl\">ט׳ טרופה</span> brine containing hashed <i>tarith</i> (when you cannot recognize the clean and unclean fish). Ib. <span dir=\"rtl\">ט׳ שאינה טרופה</span> in which the fish can be recognized. <span class=\"citation\">Ned. VI, 4</span> he who vows abstinence from ‘fish’ <span dir=\"rtl\">מותר בט׳ טרופה</span> is permitted to partake of hashed <i>t</i>. <span class=\"citation\">Ber. 44ᵃ</span></div>","alt":[]},"14014":{"h":"טָרִיתָא","r":"I00827","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"טָרִית\">same</a>. <span class=\"citation\">Y. Ned. VI, 39ᵈ</span> top <span dir=\"rtl\">זבין לי טרי וכ׳</span> (not <span dir=\"rtl\">ליטרי</span>) sell me <i>tari</i>, and he sells him <i>tsaḥăna</i> (v. <a href=\"#\" data-headword=\"צַחֲנָא\">צַחֲנָא</a>). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">תמן … לט׳ וכ׳</span> (not <span dir=\"rtl\">ליט׳</span>) there they call <i>taritha tsaḥăna</i></div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"אִטְּרִי\">אִטְּרִי</a>) <i>a sort of pastry, fritters</i> &amp;c. <span class=\"citation\">Ber. 37ᵇ</span>, v. <a href=\"#\" data-headword=\"הִנְדְּקָא\">הִנְדְּקָא</a> a. <a href=\"#\" data-headword=\"גְּבִיל\"><a href=\"#\" data-headword=\"גְּבִיל\">גְּבִיל</a>.</a></div>","alt":["טָרִי"]},"14015":{"h":"טֶרֶךְ","r":"I00828","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">טרך</span>, cmp. <a href=\"#\" data-headword=\"טְרַק II\"><span dir=\"rtl\">טְרַק</span> II</a>), pl. <span dir=\"rtl\">טְרָכִים</span>, constr. <span dir=\"rtl\">טַרְכֵי</span> <i>binders, preservers</i> (cmp. Syr. <a href=\"#\" data-headword=\"טָרַק\">טרק</a> a. derivatives P. Sm. 1528). <span class=\"citation\">Tosef. Sot. XV, 9</span>, v. <a href=\"#\" data-headword=\"טְרַכְסִיד\">טְרַכְסִיד</a>.</div>","alt":[]},"14016":{"h":"טָרֵךְ","r":"I00829","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טָרֵיךְ\">טָרֵיךְ</a></div>","alt":[]},"14017":{"h":"טְרָכוֹנָא","r":"I00830","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Trachona, Trachonitis</i>, town and district east of the Jordan. <span class=\"citation\">Targ. O. Deut. III, 4</span>; <span class=\"citation\">13</span>; <span class=\"citation\">14</span> (Y. <a href=\"#\" data-headword=\"טַרְגּוֹנָא\">טַרְגּוֹנָא</a>; h. text <span dir=\"rtl\">ארגב</span>). <span class=\"citation\">Targ. Y. II, Num. XXXIV, 15</span> <span dir=\"rtl\">טְרֵכוֹן זמרא</span>; <span class=\"citation\">Sifré Deut. 51</span> <span dir=\"rtl\">טרכונא דנימרא</span>; <span class=\"citation\">Yalk. ib. 874</span> <span dir=\"rtl\">ט׳ דזימר׳</span> (not <span dir=\"rtl\">טרנינא</span>); <span class=\"citation\">Tosef. Shebi. IV, 11</span> <span dir=\"rtl\">ט׳ דבתחום בצרה</span> ed. Zuck. (Var. <span dir=\"rtl\">טרכתא</span>, incorr.); Y. Shebi. VI, 36ᶜ <span dir=\"rtl\">ט׳ דמתחם לבוצרה</span> (v. Hildesh. Beitr. p. 55, sq.).</div>","alt":[]},"14018":{"h":"טַרְכּוּנְתָּא","r":"I00831","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טַרְכָנוּתָא\">טַרְכָנוּתָא</a></div>","alt":[]},"14019":{"h":"טרכוס","r":"I00832","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טַרְכֵּשׁ\">טַרְכֵּשׁ</a></div>","alt":[]},"14020":{"h":"טרכינוס","r":"I00833","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טְרָיָינוֹס\">טְרָיָינוֹס</a></div>","alt":["טרכיני"]},"14021":{"h":"טַרְכָן","r":"I00834","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טָרֵיךְ\">טָרֵיךְ</a></div>","alt":[]},"14022":{"h":"טַרְכָנוּתָא","r":"I00835","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"טַרְכָן\">preced.</a>) <i>trouble, anger</i>. <span class=\"citation\">Targ. Prov. XXVI, 28</span> Ar. a. Lev. (Var. <a href=\"#\" data-headword=\"טַרְכּוּנְתָּא\">טַרְכּוּנְתָּא</a>; ed. <a href=\"#\" data-headword=\"תַּרְכּוּנְתָּא\">תַּרְכִּוּנְתָּא</a>; Ms. <a href=\"#\" data-headword=\"סרכונא\">סרכונא</a>).</div>","alt":[]},"14023":{"h":"טְרַכְסִיד","r":"I00836","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (a comp. of <a href=\"#\" data-headword=\"טֶרֶךְ\">טֶרֶךְ</a> a. <a href=\"#\" data-headword=\"סִיד I\">סִיד</a>) <i>binding cement</i>. <span class=\"citation\">Tosef. Sot. XV, 9</span> if one put sand in the lime, <span dir=\"rtl\">הרי זה ט׳ ואסור</span> ed. (ed. Zuck. <span dir=\"rtl\">טרכיו סיד הוא</span>, Var. <span dir=\"rtl\">טַרְכֵי סיד</span>) it is cement and therefore forbidden; <span class=\"citation\">B. Bath. 60ᵇ</span> <span dir=\"rtl\">הרי זה ט׳</span> (Ms. O. <span dir=\"rtl\">טַרְכְּסָאוֹ</span> the binding of it (the lime), cmp. <a href=\"#\" data-headword=\"טְרַקְסִין\">טְרַקְסִין</a>); <span class=\"citation\">Sabb. 80ᵇ</span> (Ms. M. <span dir=\"rtl\">תר׳</span>). [<span class=\"citation\">Treat. S’maḥ. VIII</span> <span dir=\"rtl\">טרכסי׳</span>, in a corrupt passage, prob. to be read: <span dir=\"rtl\">כרכים</span>.]</div>","alt":[]},"14024":{"h":"טְרַכְסִימוֹן","r":"I00837","html":"<div class=\"sense\">, v. <span dir=\"rtl\">טְרוֹקְסִ׳</span></div>","alt":[]},"14025":{"h":"טַרְכֵּשׁ","r":"I00838","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (enlargement of <span dir=\"rtl\">טרך</span> or <a href=\"#\" data-headword=\"טָרַק\">טרק</a>, v. <a href=\"#\" data-headword=\"טָרֵיךְ\">טָרֵיךְ</a>, a. <a href=\"#\" data-headword=\"טְרַק I\"><span dir=\"rtl\">טְרַק</span> I</a>) [<i>a wine-stirrer</i>,] <i>a board on which drinks for the table are mixed, side-board</i> (abacus, mensa delphica), <i>a plain board attached to the wall with hinges, to be put up and down</i> (cmp. <a href=\"#\" data-headword=\"דְּלִפְקִי\">דְּלִפְקִי</a>, <span class=\"citation\">Kel. XXV, 1</span>). <span class=\"citation\">Tosef. Kel. B. Bath. III, 3</span> <span dir=\"rtl\">ט׳ חלק</span> (R. S. to <span class=\"citation\">Kel. XXV, 1</span> <span dir=\"rtl\">טרכוס וחלק</span>) a plain tray (without rims). Ib. I, 12 <span dir=\"rtl\">ט׳ שעשה וכ׳</span> a side-board under which they placed a piece of wood, formed like a spear (as an improvised support) for eating at it. <span class=\"citation\">Tosef. Sabb. XIV</span> (<span class=\"citation\">XV), 2</span> <a href=\"#\" data-headword=\"תַּרְקוֹשׁ\">תרקוש</a> ed. Zuck. (Var. <a href=\"#\" data-headword=\"ט׳\">ט׳</a>, by cler. error <a href=\"#\" data-headword=\"מרקוש\">מרקוש</a>).</div>","alt":["טַרְקוֹשׁ"]},"14026":{"h":"טַרְלוֹסָה","r":"I00839","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Tarlosa, Talluza</i>, near Samaria. <span class=\"citation\">Y. Taan. IV, 68ᵈ</span> top <span dir=\"rtl\">מעברתא דט׳</span> the ford of T.</div>","alt":[]},"14027":{"h":"טרמוסיא","r":"I00840","html":"<div class=\"sense\">, <span class=\"citation\">Midr. Till. to Ps. XIII, 5</span> <span dir=\"rtl\">באיזה ט׳ וכ׳</span>; ed. Bub. <a href=\"#\" data-headword=\"תלמוסא\">תלמוסא</a>, Ms. Vien. <a href=\"#\" data-headword=\"טִלְטוּלַיָּא\">טל׳</a>; <span class=\"citation\">Yalk. Ps. 660</span> <a href=\"#\" data-headword=\"תלמידא\">תלמידא</a>, prob. to be read: <span dir=\"rtl\">באיזו טוֹלְמִירְיָא וכ׳</span> (τοληρία) with what <i>hardihood</i> do you speak such words (of bad omen)?</div>","alt":[]},"14028":{"h":"טרמיות","r":"I00841","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טוּרְמִי\">טוּרְמִי</a></div>","alt":[]},"14029":{"h":"טַרְמִיטָא","r":"I00842","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*טְרוֹמִיטָא\">טְרוֹמִיטָא</a></div>","alt":["טַרְמִיטָן"]},"14030":{"h":"טרמנטן","r":"I00843","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טוּרְמִנְטִין\">טוּרְמִנְטִין</a></div>","alt":["טרמנסנה"]},"14031":{"h":"טרמסין","r":"I00844","html":"<div class=\"sense\">, <span class=\"citation\">Snh. 14ᵃ</span> Ms. M., v. <a href=\"#\" data-headword=\"טוּרְמִיסִין\">טוּרְמִיסִין</a></div>","alt":[]},"14032":{"h":"*טְרַס","r":"I00845","html":"<div class=\"sense\"><i>to search</i>. <span class=\"citation\">Lev. R. s. 37</span> טַרְסִין וכ׳ Ar. (Var. a. ed. <span dir=\"rtl\">פשפשין</span>) they searched every ship &amp;c.—[<span class=\"citation\">B. Kam. 98ᵃ</span>, v. <a href=\"#\" data-headword=\"טְרַשׁ I\"><span dir=\"rtl\">טְרַשׁ</span> I</a>.]</div>","alt":[]},"14033":{"h":"טֶרֶס","r":"I00846","html":"<div class=\"sense\"> m., pl. <span dir=\"rtl\">טְרָסִין</span>, v. <a href=\"#\" data-headword=\"טֶרֶשׁ\">טֶרֶשׁ</a></div>","alt":[]},"14034":{"h":"טַרְסָאָה","r":"I00847","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> nom. gent. <i>of Tarsus</i>.—Pl. <span dir=\"rtl\">טַרְסָאֵי</span>. <span class=\"citation\">Targ. Esth. II, 21</span> (ed. Lag. <a href=\"#\" data-headword=\"טִרְדָּא\">טִירְ׳</a>), v. <a href=\"#\" data-headword=\"טַרְסִי II\"><span dir=\"rtl\">טַרְסִי</span> II</a>.</div>","alt":[]},"14035":{"h":"טַרְסוֹס","r":"I00848","html":"<div class=\"sense\"> pr. n. pl., v. <a href=\"#\" data-headword=\"טַרְסִיס\">טַרְסִיס</a></div>","alt":[]},"14036":{"h":"טַרְסִי I","r":"I00849","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"טַרְסִי II\">next w.</a>) [<i>a Tarsian</i>,] </div><div class=\"sense\"><b>1)</b> <i>weaver of metallic thread, artistic weaver</i>, differ. fr. <a href=\"#\" data-headword=\"גַּרְדִּי\">גַּרְדִּי</a>.—Pl. <span dir=\"rtl\">טַרְסִיִּים</span>. <span class=\"citation\">Ab. Zar. 17ᵇ</span> Ar. a. Ms. Pes. (ed. <a href=\"#\" data-headword=\"תְּרֵיסִיּוֹת\">תרס׳</a>, v. Rabb. D. S. a. l. note 40). <span class=\"citation\">Succ. 51ᵇ</span> <span dir=\"rtl\">וט׳ בפ&quot;ע וכ׳</span> (v. Rabb. D. S. a. l. note 400) artistic weavers apart and common weavers apart; <span class=\"citation\">Tosef. ib. IV, 6</span>.—<span class=\"citation\">Sabb. 47ᵃ</span> <span dir=\"rtl\">מטה של ט׳</span> the weavers’ horizontal loom or frame for embroidery (differ. in Rashi).</div><div class=\"sense\"><b>—2)</b> <i>worker in copper, bronze</i> &amp;c. <span class=\"citation\">Ḥull. 57ᵇ</span> <span dir=\"rtl\">מטלית של ט׳</span> the bronzers’ apron.</div>","alt":[]},"14037":{"h":"טַרְסִי II","r":"I00850","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> nom. gent. of <i>Tarsus, Tarsian</i>.—Pl. <span dir=\"rtl\">טַרְסִיִּים</span>, <a href=\"#\" data-headword=\"טְרָיָיא\">טוּרְ׳</a>. <span class=\"citation\">Meg. 7ᵃ</span> בגתן … שני ט׳ היו והיו מספרים בלשון טרסי Ms. M. (only <span dir=\"rtl\">בגתן … שני טרשיים היו</span>) Bigthan and Teresh were two Tarsians and conversed in the Tarsian language; <span class=\"citation\">ib. 13ᵇ</span> <span dir=\"rtl\">שני ט׳ … טורסי</span> (Ms. M. … <span dir=\"rtl\">תרסיים תרסי</span>). <span class=\"citation\">Ib. 26ᵃ</span> בה&quot;כ של ט׳ Ms. M. (ed. <span dir=\"rtl\">טור׳</span>; <span class=\"citation\">Tosef. ib. III</span> (<span class=\"citation\">II), 6</span> <span dir=\"rtl\">אלכסנדרים</span>) the synagogue of the Tarsians in Jerusalem (Rashi: of the bronze-workers, v. <a href=\"#\" data-headword=\"טַרְסִי I\">preced.</a>). <span class=\"citation\">Y. Shek. II, 47ᵃ</span> <span dir=\"rtl\">בה&quot;כ של ט׳</span> (<span class=\"citation\">Yeb. 96ᵇ</span> <a href=\"#\" data-headword=\"טְבַרְיָא\">טבריא</a>).</div>","alt":["טוּרְסִי"]},"14038":{"h":"טרסיאות","r":"I00851","html":"<div class=\"sense\">, read: <span dir=\"rtl\">סְרַטְיָאוֹת</span>.</div>","alt":[]},"14039":{"h":"טַרְסַיי","r":"I00852","html":"<div class=\"sense\"> <span class=\"citation\">Y. Gitt. VII, beg. 48ᶜ</span>; <span class=\"citation\">Y. Ter. I, 40ᵇ</span> (perh. proper noun).—Pl. <a href=\"#\" data-headword=\"טַרְזַיָּא\">טַרְסַיָּא</a>, <span dir=\"rtl\">טַרְסַיָּיה</span>. <span class=\"citation\">Y. Kil. IX, end, 32ᵈ</span>.—<span class=\"citation\">Lev. R. s. 35</span>, end <span dir=\"rtl\">כנישתא דט׳ וכ׳</span> the synagogue of the weavers in Lydda (or bronze-workers, or Tarsians), v. <a href=\"#\" data-headword=\"טַרְסִי II\"><span dir=\"rtl\">טַרְסִי</span> II</a>.</div>","alt":[]},"14040":{"h":"טַרְסִיס","r":"I00853","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> = h. <span dir=\"rtl\">תַּרְשִׁישׁ</span> <i>Tarsis</i> (<i>Tarentum</i>). <span class=\"citation\">Targ. Y. I Gen. X, 4</span> <span dir=\"rtl\">טַרְסַס</span> ed. Amst. (oth. eds. <a href=\"#\" data-headword=\"טַרְסִיס\">טרסיס</a>, v. <a href=\"#\" data-headword=\"אַלַּס\">אַלַּס</a>); <span class=\"citation\">Targ. I Chr. I, 7</span> <a href=\"#\" data-headword=\"טַרְסוֹס\">טרסוס</a> ed. Lag.—2) (prob.) <i>Tartessus, in Spain</i>. <span class=\"citation\">Targ. Ps. XLVIII, 8</span>. <span class=\"citation\">Ib. LXXII, 10</span>. [V. <a href=\"#\" data-headword=\"טריסיס\">טריסיס</a>.]</div>","alt":[]},"14041":{"h":"טְרִסְקֵל","r":"I00854","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (τρισκελής, τρισκέλλων, sub. <span dir=\"rtl\">כסא</span>) <i>a chair on three legs</i>, esp. <i>a camp-chair</i>. <span class=\"citation\">Num. R. s. 12</span>; Tanḥ. Naso 19; (Tanḥ. T’rumah 9; <span class=\"citation\">Gen. R. s. 68</span> <a href=\"#\" data-headword=\"תְּרוֹנוֹס\">תְּרוֹנוֹס</a>). <span class=\"citation\">Sabb. 138ᵃ</span> <span dir=\"rtl\">כסא ט׳</span> (Ms. O. <span dir=\"rtl\">כסא וט׳</span>).</div>","alt":[]},"14042":{"h":"טְרַסְקָל","r":"I00855","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (a corrupt. of κάρταλλος, v. <a href=\"#\" data-headword=\"קְרַסְטָל\">קרסטל</a>) <i>basket</i>. <span class=\"citation\">Lev. R. s. 19</span>; (Midr. Sam. ch. V <a href=\"#\" data-headword=\"קְרַסְטָל\">קרסטל</a>). <span class=\"citation\">Sabb. 5ᵃ</span>. <span class=\"citation\">Ib. 53ᵃ</span> <span dir=\"rtl\">תולין ט׳ לבהמה</span> you may hang a basket with fodder around the neck of an animal.—V. <a href=\"#\" data-headword=\"טְרַסְקְלִין\">next w.</a></div>","alt":[]},"14043":{"h":"טְרַסְקְלִין","r":"I00856","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (κάρταλον, v. <a href=\"#\" data-headword=\"טְרַסְקָל\">preced.</a>) <i>a basket</i> (fiscellus) containing fodder, used <i>for muzzling</i>. <span class=\"citation\">Sabb. 53ᵃ</span> bot.; (Tosef. ib. IV (V) 5 <a href=\"#\" data-headword=\"קְרַסְטְלִין\">קרסטלין</a>, Var. <a href=\"#\" data-headword=\"קַרְטַלִּין\">קרטלין</a>). <span class=\"citation\">B. Mets. 90ᵃ</span> (Ms. M. <a href=\"#\" data-headword=\"קרסטילין\">קרסטילין</a>, oth. Mss. <a href=\"#\" data-headword=\"קְרַסְטְלִין\">קרסטלין</a>, <a href=\"#\" data-headword=\"קסרטל\">קסרטל</a>, v. Rabb. D. S. a. l. note).</div>","alt":[]},"14044":{"h":"טרסקמון","r":"I00857","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טְרוֹקְסִימָא\">טְרוֹקְסִימוֹן</a></div>","alt":[]},"14045":{"h":"טְרַעְפִּיקָא","r":"I00858","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טַרְפְּעִיק\">טַרְפְּעִיקָא</a></div>","alt":[]},"14046":{"h":"טָרַף","r":"I00859","html":"<div class=\"sense\"> [<i>to move with vehemence</i>,] </div><div class=\"sense\"><b>1)</b> <i>to tear, prey</i>. <span class=\"citation\">Lev. R. s. 26</span> <span dir=\"rtl\">טוֹרֵף ואוכל</span> tears in order to satisfy his appetite. <span class=\"citation\">Koh. R. to X, 11</span> <span dir=\"rtl\">הארי ט׳</span> the lion goes out for prey. <span class=\"citation\">Sot. 47ᵇ</span> <span dir=\"rtl\">טוֹרְפֵי טֶרֶף</span> those robbing (the poor). <span class=\"citation\">Zeb. 53ᵇ</span> <span dir=\"rtl\">חלקו של טוֹרֵף</span> the territory of the tearer (wolf = Benjamin, <span class=\"citation\">Gen. XLIX, 27</span>). <span class=\"citation\">B. Kam. 116ᵇ</span> <span dir=\"rtl\">לטוֹרְפָהּ</span> to plunder it; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to cast with force, knock, strike against; to throw away, reject, eject</i>. <span class=\"citation\">Ḥull. III, 3</span> <span dir=\"rtl\">טְרָפָהּ בכותל</span> he cast or knocked the bird against the wall. <span class=\"citation\">Pesik. R. s. 11</span>; <span class=\"citation\">Num. R. s. 2</span> מגרשה אני טוֹרְפָהּ אני I will divorce her, I will cast her out (cmp. <a href=\"#\" data-headword=\"טָרַד\">טָרַד</a>).—<span class=\"citation\">Ber. 5ᵇ</span> <span dir=\"rtl\">טוֹרְפִין לו וכ׳</span> his prayer is thrown in his face (refused). <span class=\"citation\">Y. Yeb. XVI, 15ᵈ</span> top <span dir=\"rtl\">טְרָפַנִי</span>, v. <a href=\"#\" data-headword=\"טָרַד\">טָרַד</a>.</div><div class=\"sense\"><b>—3)</b> <i>to seize forcibly.</i> <span class=\"citation\">Yoma IV, 1</span> <span dir=\"rtl\">ט׳ בקלפי</span> he took the ballot out with haste.—Esp. <i>to seize for a debt</i>. <span class=\"citation\">B. Mets. 15ᵃ</span> <span dir=\"rtl\">ובא ב&quot;ח וטְרָפָהּ</span> and a creditor of the previous owner came and seized it, v. <a href=\"#\" data-headword=\"טִירְפָּא\">טִירְפָּא</a>.</div><div class=\"sense\"><b>—4)</b> <i>to chop, hash, to beat, mix</i>. <span class=\"citation\">Sabb. XIX, 2</span> <span dir=\"rtl\">ט׳ יין ושמן</span> beat wine and oil; a. e.—Part. pass. <a href=\"#\" data-headword=\"טָרוּף\">טָרוּף</a>, f. <span dir=\"rtl\">טְרוּפָה</span>. <span class=\"citation\">Ib. 38ᵃ</span> <span dir=\"rtl\">בשר ט׳</span> chopped meat. <span class=\"citation\">Ab. Zar. II, 6</span>, v. <a href=\"#\" data-headword=\"טָרִית\">טָרִית</a>. Y. Nidd. IV, 51ᵃ (of a foetus). <span class=\"citation\">Sabb. VIII, 5</span> (<span class=\"citation\">80ᵇ</span>) <span dir=\"rtl\">ביצה ט׳</span> an egg beaten and mixed with oil; a. fr. V. <a href=\"#\" data-headword=\"טָרוּף\">טָרוּף</a>.</div><div class=\"sense\"><b>—5)</b> <i>to hackle, comb</i> (flax or wool). <span class=\"citation\">Kil. IX, 1</span>. <span class=\"citation\">Y. Orl. III, 63ᵃ</span>; <span class=\"citation\">Y. Keth. VI, end, 31ᵃ</span> <span dir=\"rtl\">צמר בכור שטְרָפוֹ</span> wool of a first-born that has been hackled (and mixed up with, other wool).</div><div class=\"sense\"><b>—6)</b> <i>to scrape, scour, to plane.</i> <span class=\"citation\">Makhsh. II, 4</span> <span dir=\"rtl\">הטוֹרֵף את גגו</span> (Var. <span dir=\"rtl\">המטהר</span>) if one scrubs his roof; <span class=\"citation\">Tosef. ib. I, 8</span>.</div><div class=\"sense\"><b>—7)</b> <i>to make</i> <a href=\"#\" data-headword=\"טְרֵיפָה\">טְרֵפָה</a>, <i>to inflict an organic defect</i>. <span class=\"citation\">Ḥull. 85ᵇ</span>, sq. <span dir=\"rtl\">צא טְרוֹף</span> go and maim the animal (before slaughtering it).</div><div class=\"sense\"><b>Nif. נִטְרַף</b> <div class=\"sense\"><b>1)</b> <i>to become t’refah</i>. Ib. 9ᵃ, a. e. <span dir=\"rtl\">במה נִטְרְפָה</span> from what cause it became <i>t’refah</i></div><div class=\"sense\"><b>—2)</b> <i>to be in disorder</i>, a) (with <a href=\"#\" data-headword=\"דֵּעָה\">דעה</a>, or <a href=\"#\" data-headword=\"לֵב\">לב</a>) <i>to be confused, bewildered, not fully conscious</i>. Y. Sabb. II, 5ᵇ bot. <span dir=\"rtl\">נִטְרְפָה דעתו של אבא</span> my father’s mind is unclear; <span class=\"citation\">Snh. 68ᵃ</span>. <span class=\"citation\">Ib. 43ᵃ</span> <span dir=\"rtl\">כדי שתִּטָּרֵף דעתו</span> (not <span dir=\"rtl\">שתטרוף</span>) that his (the culprit’s) consciousness may be benumbed; <span class=\"citation\">Num. R. s. 10</span>.—<span class=\"citation\">Ib.</span> <span dir=\"rtl\">נ׳ לבו</span> his mind becomes confused (from drinking); a. fr.—b) (with <span dir=\"rtl\">שעה</span>, of political disturbances) <i>to be troubled</i>. <span class=\"citation\">Snh. 11ᵃ</span>; <span class=\"citation\">Sot. 48ᵇ</span>; <span class=\"citation\">Tosef. ib. XIII, 5</span> <span dir=\"rtl\">נטרפה</span> (<a href=\"#\" data-headword=\"ה\">ה</a>)<span dir=\"rtl\">שעה</span> the political condition was too much troubled (persecutions prevailing). Y. Dem. V, 24ᵈ bot.; a. e.</div></div><div class=\"sense\"><b>Pi. טֵרֵף</b> <div class=\"sense\"><b>1)</b> <i>to shake vehemently, constantly</i>. <span class=\"citation\">Succ. III, 9</span> <span dir=\"rtl\">כל העם מטָרְפִין בלולביהן</span> ed. Y. (Mish. ed. Pes. <span dir=\"rtl\">מט׳את לול׳</span>; ed. <span dir=\"rtl\">מנעועין</span>) all the people shook their branches constantly (during the recitation at Hallel, contrad. to <span dir=\"rtl\">נענע</span>).</div><div class=\"sense\"><b>—2)</b> <i>to unbalance</i> (the mind, cmp. <a href=\"#\" data-headword=\"טִלְטֵל\">טִלְטֵל</a>).—Part. pass. <span dir=\"rtl\">מְטוֹרָף</span>. <span class=\"citation\">Num. R. s. 10</span> <span dir=\"rtl\">לבו מ׳ וכ׳</span> his mind is disturbed and he talks improper things, v. supra.</div><div class=\"sense\"><b>—3)</b> <i>to reject one’s petition, to refuse</i>. Part. pass. <span dir=\"rtl\">מְטוֹרָף</span>. <span class=\"citation\">Ber. V, 5</span> <span dir=\"rtl\">שהוא מ׳</span> that he (the patient for whom prayer is said) is rejected (bound to die), opp. <span dir=\"rtl\">מקובל</span> accepted.</div><div class=\"sense\"><b>—4)</b> <i>to disfigure, to make ungainly</i> by spots, incisions &amp;c., v. <a href=\"#\" data-headword=\"טָרוּף\">טָרוּף</a>). Part. pass. as ab. <span class=\"citation\">Koh. R. to X, 11</span> the serpent is asked <span dir=\"rtl\">מפני מה גופך מט׳</span> why has thy body been disfigured (v. <span class=\"citation\">Gen. III, 14</span>)?</div><div class=\"sense\"><b>—5)</b> <i>to cast about</i> (a ship on high sea), v. Hithpa.—Part. pass. as ab.; <i>pl</i>. <span dir=\"rtl\">מְטוֹרָפִים</span>, <span dir=\"rtl\">מְטוֹרָפִין</span>. <span class=\"citation\">Yeb. 47ᵃ</span>, v. <a href=\"#\" data-headword=\"סָחַף\">סָחַף</a>.</div></div><div class=\"sense\"><b>Hif. הִטְרִיף</b> <div class=\"sense\"><b>1)</b> <i>to become t’refah, to be afflicted with a fatal organic disease</i>. <span class=\"citation\">Num. R. s. 12</span>, end; <span class=\"citation\">Cant. R. to VI, 4</span>; Pesik. Vayhi p. 10ᵃ, a. e. <span dir=\"rtl\">לא הִטְרִיפוּ</span> the animals were found to be free from an organic disease.—[</div><div class=\"sense\"><b>2)</b>  (in later liter.) <i>to declare t’refah</i>.]</div><div class=\"sense\"><b>—3)</b>  (denom. of <a href=\"#\" data-headword=\"טֶרֶף\">טֶרֶף</a>) a) <i>to cover with foliage</i>. <span class=\"citation\">Yalk. Gen. 119</span>, v. <a href=\"#\" data-headword=\"רָטַב\">רָטַב</a>.—b) <i>to sprout with moisture, be sappy</i>. <span class=\"citation\">Gen. R. s. 69</span> <span dir=\"rtl\">ה׳ מצות וכ׳</span> (<span class=\"citation\">Yalk. Jud. 38</span> <a href=\"#\" data-headword=\"פָּרַח\">הפריח</a>) sprouted with good deeds &amp;c., v. <a href=\"#\" data-headword=\"רָטַב\">רָטַב</a>.—[</div><div class=\"sense\"><b>4)</b> <i>to distribute food</i>, v. <a href=\"#\" data-headword=\"טָרָף\">טָרָף</a>.]</div></div><div class=\"sense\"><b>Hithpa. הִיטָּרֵף</b> <div class=\"sense\">, <i>Nithpa</i>. <span dir=\"rtl\">נִיטָּרֵף</span> <i>to be tossed about, to be in a storm</i> near the shore. <span class=\"citation\">Taan. III, 7</span> (<span class=\"citation\">19ᵃ</span>) <span dir=\"rtl\">על הספינה המִיטָּרֶפֶת וכ׳</span> for a ship which is seen from the coast to be tossed about; <span class=\"citation\">Taan. 14ᵃ</span> <span dir=\"rtl\">המְטוֹרֶפֶת</span> (v. supra; Ar. ed. Koh. <span dir=\"rtl\">נִטְרֶפֶת</span> <i>Nif</i>.). <span class=\"citation\">Tosef. Sabb. XIII</span> (<span class=\"citation\">XIV), 11</span> <span dir=\"rtl\">נִיטָּרְפָה ספינה וכ׳</span> the ship has been thrown back several times (was prevented from landing by the breakers).</div></div>","alt":[]},"14047":{"h":"טְרַף I","r":"I00860","html":"<div class=\"sense\"><b>1)</b> <i>to take by force, seize</i>. <span class=\"citation\">B. Mets. 14ᵃ</span> <span dir=\"rtl\">אתי … וטַרְפָהּ מיניה</span> (not <span dir=\"rtl\">וטרפא</span>) the creditor came and took it from him (by legal seizure); <span class=\"citation\">ib.</span> <span dir=\"rtl\">וקא טָרֵיף ליה מיניה</span> (Ms. H. <span dir=\"rtl\">וטַרְפָהּ מיניה</span>).—<span dir=\"rtl\">ט׳ לקוחות</span> to seize property sold by the debtor, v. <a href=\"#\" data-headword=\"לְקוּחוֹת\">לְקוּחוֹת</a>. <span class=\"citation\">Ib. 19ᵃ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to throw, strike, knock down</i>. <span class=\"citation\">Y. Snh. X, 29ᵃ</span> <span dir=\"rtl\">וטָרֵיף לון לארעא</span> and let them fall down. <span class=\"citation\">Lam. R. to I, 5</span> <span dir=\"rtl\">ויִטְרוֹף גרמיה</span> and let him throw himself down. <span class=\"citation\">Ib. to IV, 2</span> <span dir=\"rtl\">טְרוֹף קולתיך וכ׳</span> cast down thy pitcher before me; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to knock at, shake, rap</i>. <span class=\"citation\">Ber. 28ᵃ</span> <span dir=\"rtl\">ט׳ אבבא</span> knocked at the door. <span class=\"citation\">Snh. 97ᵃ</span>.—<span class=\"citation\">Ib. 67ᵇ</span> <span dir=\"rtl\">ט׳ ליה בטבלא</span> he struck the <i>tabla</i> before him; a. v. fr.—Trnsf. <i>to carp at, to contest the validity of a decision</i>. <span class=\"citation\">Y. Snh. I, beg. 18ᵃ</span> <span dir=\"rtl\">בעי מִיטְרוֹף</span> wanted to protest (against R. Isaac’s decision because he acted as a single judge).—5) <i>to declare t’refah</i>. <span class=\"citation\">Ḥull. 10ᵇ</span>. <span class=\"citation\">Ib. 48ᵇ</span> סבר … למִיטְרְפָהּ Mar … wanted to declare it <i>t’refah;</i> a. fr.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"טְרַף I\">טָרִיף</a> a) <i>struck down</i> (in the agony of death). <span class=\"citation\">Targ. Jud. III, 25</span>; <span class=\"citation\">IV, 22</span> (h. text <span dir=\"rtl\">נֹפֵל</span>). <span class=\"citation\">Lam. R. to IV, 5</span> <span dir=\"rtl\">טְרִיפִין בקיקלא</span> (not <a href=\"#\" data-headword=\"טְרִיפוֹן\">טריפון</a>) lying on dunghills.—b) <i>thrown away</i>. <span class=\"citation\">Y. Snh. X, 29ᵃ</span> top <span dir=\"rtl\">הא טריפין לך</span> they are thrown down before thee (cmp. <a href=\"#\" data-headword=\"*טְרוּן\">טְרוּן</a>).—c) (denom. of <a href=\"#\" data-headword=\"טרפא\">טרפא</a>, v. <a href=\"#\" data-headword=\"טָרוּף\">טָרוּף</a>) <i>spotted, full of incisions; planed</i>. <span class=\"citation\">Ned. 25ᵃ</span>; <span class=\"citation\">Shebu. 29ᵇ</span>, v. <a href=\"#\" data-headword=\"טָרוּף\">טָרוּף</a>.—[<span class=\"citation\">Y. Shebi. I, end, 33ᶜ</span> <span dir=\"rtl\">א&quot;ר יודן כד טריפן לעוביה</span>, read with R. S. to <span class=\"citation\">Shebi. I, 8</span>: <span dir=\"rtl\">א&quot;ר יודן בר טרפון</span> or <a href=\"#\" data-headword=\"טְרִיפוֹן\">טריפון</a>, <span dir=\"rtl\">לעוביה</span> being a corrupt tautography of <span dir=\"rtl\">ליעז׳ ב&quot;י</span> = <span dir=\"rtl\">ליעזר בן יעקב</span>.]</div><div class=\"sense\"><b>Pa. טָרֵיף</b> <div class=\"sense\"><b>1)</b> <i>to knock, strike, dash</i>. <span class=\"citation\">Targ. II Kings VIII, 12</span> (h. text <a href=\"#\" data-headword=\"רְטַשׁ\">רטש</a>). <span class=\"citation\">Targ. Nah. II, 8</span> (h. text <a href=\"#\" data-headword=\"תְּפַף I\">תפף</a>).</div><div class=\"sense\"><b>—2)</b> <i>to prey, wait for prey</i>. <span class=\"citation\">Targ. Prov. XXIII, 28</span> <span dir=\"rtl\">מְטָרֵף</span>.</div><div class=\"sense\"><b>—3)</b> <i>to drive about</i>. Part. pass. <span dir=\"rtl\">מְטַרַף</span>. <span class=\"citation\">Targ. Y. I Ex. XIV, 3</span> (ed. Amst. <a href=\"#\" data-headword=\"מַטַּטְרוֹן\">מִטַּ׳</a> <i>Ithpa.</i>). <span class=\"citation\">Targ. Y. II, Num. XII, 12</span> <a href=\"#\" data-headword=\"מִטַרְפָא\">מְטַרָפָא</a>.—Trnsf. <i>to agitate, trouble</i>, v. infra.</div></div><div class=\"sense\"><b>Ithpa. אִיטָּרֵיף</b> </div><div class=\"sense\"><b>Ithpe. אִיטְּרִיף</b> <div class=\"sense\"><b>1)</b> <i>to be knocked about, dashed; to be tossed about; to be in spasms</i>. <span class=\"citation\">Targ. Is. XIII, 16</span>. <span class=\"citation\">Ib. LI, 20</span>; a. e.—<span class=\"citation\">Lev. R. s. 12</span> beg. <span dir=\"rtl\">כהד׳ אילפא דמִיטָּרְפָא וכ׳</span> like the ship that is tossed about in the breakers &amp;c. <span class=\"citation\">Snh. 95ᵃ</span> <span dir=\"rtl\">אתו יונה אי׳ קמיה</span> a dove came down and rolled before him in spasms.—Trnsf. <i>to be agitated, troubled</i>. <span class=\"citation\">Targ. Gen. XLI, 8</span> (some ed. <a href=\"#\" data-headword=\"מְטַר\">מְטַר׳</a> Part. pass. <i>Pa.</i>, v. supra). <span class=\"citation\">Targ. Ps. LXXVII, 5</span>; a. fr.—Y. Taan. I, 64ᵇ bot. <span dir=\"rtl\">למה אִיטָּרְפוּן … להכא</span> why did the rabbis (you) take the trouble of coming hither.</div><div class=\"sense\"><b>—2)</b> <i>to be spotted, full, of incisions</i> &amp;c., v. supra a. <a href=\"#\" data-headword=\"טָרוּף\"><a href=\"#\" data-headword=\"טָרוּף\">טָרוּף</a>.</a></div><div class=\"sense\"><b>—3)</b> <i>to become</i>, or <i>be t’refah</i>. <span class=\"citation\">Ḥull. 57ᵇ</span> <span dir=\"rtl\">במידי דמִיטָּרְפָה בה</span> in the same limb through the mutilation of which the animal became <i>t’refah</i>. <span class=\"citation\">Ib. 48ᵃ</span> <span dir=\"rtl\">דלאו מיניה מיטָּרְפָא</span> where the cause of its being <i>t’refah</i> lies not in the mutilated limb itself.</div></div>","alt":["טְרֵיף"]},"14048":{"h":"טְרַף II","r":"I00861","html":"<div class=\"sense\"> m., v. <a href=\"#\" data-headword=\"טַרְפָא I\">טַרְפָא</a></div>","alt":[]},"14049":{"h":"טֶרֶף","r":"I00862","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"טְרַף II\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>prey</i>. <span class=\"citation\">Sot. 47ᵇ</span>, v. <a href=\"#\" data-headword=\"טָרַף\">טָרַף</a>.—<span class=\"citation\">Gen. R. s. 99</span> (ref. to <span dir=\"rtl\">מטרף</span>, <span class=\"citation\">Gen. XLIX, 9</span>) <span dir=\"rtl\">מטַרְפּוֹ של יוסף</span> from making Joseph a prey, i.e. saving Joseph; <span dir=\"rtl\">מטַרְפָּהּ של תמר</span> saving Tamar. <span class=\"citation\">Yalk. Ps. 637</span>; <span class=\"citation\">Midr. Till. to Ps. VII</span>, ed. Bub. <span dir=\"rtl\">יושב על טַרְפּוֹ</span> (oth. ed. <span dir=\"rtl\">טְרֵפָתוֹ</span>) sits over his prey.</div><div class=\"sense\"><b>—2)</b> <i>food</i>. <span class=\"citation\">Snh. 108ᵇ</span>, v. <a href=\"#\" data-headword=\"טָרָף\">next w.</a></div><div class=\"sense\"><b>—3)</b>  (v. <a href=\"#\" data-headword=\"טָרָף\">next w.</a>) <i>foliage, green</i>. Sifra Metsora, beg. <span dir=\"rtl\">ובראשה ט׳</span> with green foliage on its top, v. <a href=\"#\" data-headword=\"טָרָף\">next w.</a>; <span class=\"citation\">Y. Sot. II, 18ᵃ</span> top <span dir=\"rtl\">וראשה ט׳</span> (corr. acc., or read as <span class=\"citation\">Tosef. Neg. VIII, 2</span> <span dir=\"rtl\">טרוף</span>).</div>","alt":[]},"14050":{"h":"טָרָף","r":"I00863","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"טֶרֶף\">preced.</a>) <i>plucked, fresh</i>; (homilet., v. <a href=\"#\" data-headword=\"טֶרֶף\">preced.</a>) <i>nourishment</i>. <span class=\"citation\">Snh. 108ᵇ</span> (ref. to <span class=\"citation\">Gen. VIII, 11</span>) <span dir=\"rtl\">מאי משמע דהאי ט׳ לישנא דמזוני הוא</span> what evidence is there that <i>taraf</i> has the meaning of food? Answ. ref. to <span dir=\"rtl\">הטריפני</span> (<span class=\"citation\">Prov. XXX, 8</span>); <span class=\"citation\">Erub. 18ᵇ</span> (v. Rabb. D. S. a. l. note).</div>","alt":[]},"14051":{"h":"טַרְפָא I","r":"I00864","html":"<div class=\"sense\"><b>1)</b> <i>leaf</i>. <span class=\"citation\">Targ. Gen. VIII, 11</span>. <span class=\"citation\">Targ. Is. XXXIV, 4</span>; a. fr.—<span class=\"citation\">Ḥull. 47ᵇ</span> <span dir=\"rtl\">ט׳ דאסא</span> leaf of a myrtle; a. fr.—<span class=\"citation\">Nidd. 20ᵃ</span> <span dir=\"rtl\">ט׳ מציעתא</span> fem. (Rashi: <a href=\"#\" data-headword=\"מְצִיעַ\">מציעא</a>), v. infra.—Trnsf. <span dir=\"rtl\">ט׳ דנחירי</span> <i>wing of the nose</i>. <span class=\"citation\">Ber. 55ᵇ</span>.—Pl. <a href=\"#\" data-headword=\"טַרְזַיָּא\">טַרְפַיָּא</a>, <span dir=\"rtl\">טַרְפֵי</span>. <span class=\"citation\">Targ. Gen. III, 7</span>; a. fr.—<span class=\"citation\">Succ. 37ᵇ</span> <span dir=\"rtl\">נתרי ט׳</span> leaves may fall off. <span class=\"citation\">Sabb. 129ᵃ</span> חמרא בר הלתא ט׳ Rashi (ed. <a href=\"#\" data-headword=\"בַּת I\">בת</a>) wine of a vine that has changed foliage three times, i.e. wine in its third year. Nidd. l. c. <span dir=\"rtl\">טַרְפָן</span> fem., v. <a href=\"#\" data-headword=\"דָּר ³\"><span dir=\"rtl\">דָּרָא</span> I</a>.</div><div class=\"sense\"><b>—2)</b> <i>a piece torn off, fragment</i>. <span class=\"citation\">Ber. 59ᵃ</span> top, and it looks <span dir=\"rtl\">כט׳ דטריף</span> like an irregular piece that has been torn off (from the star); Rashi: like a battered piece that has been mended by hammering; (Ms. F. <span dir=\"rtl\">ומתחזי דמיטרפא מיטרף</span> you can see that it has been torn off, Vers. in Rashi: <span dir=\"rtl\">כדטרפא מטרף</span>, prob. to be read <span dir=\"rtl\">כטרפא דמְטַרַף</span>).</div>","alt":["טְרַף"]},"14052":{"h":"טַרְפָא II","r":"I00865","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, constr. (<a href=\"#\" data-headword=\"טַרְפָא I\">טְרַף</a>) <span dir=\"rtl\">טַרְפַת</span> <i>rapping</i>. <span class=\"citation\">Targ. Jud. V, 11</span> (in a passage missing in ed. Lag.).</div>","alt":[]},"14053":{"h":"טרפא","r":"I00866","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 10</span> <span dir=\"rtl\">בקעת בי ט׳</span>, v. <a href=\"#\" data-headword=\"נְטוֹפָא\">נְטוֹפָא</a></div>","alt":[]},"14054":{"h":"טִרְפָּא","r":"I00867","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טִרְדָּא\">טִירְ׳</a></div>","alt":[]},"14055":{"h":"טְרִפָא","r":"I00868","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טְרֵיפָא\">טְרֵיפָ׳</a></div>","alt":["טְרֵפָה"]},"14056":{"h":"טַרְפוֹן","r":"I00869","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Tarfon</i>, a Tannai (v. Fr. Darkhé Mish., p. 101 sq.). <span class=\"citation\">Pes. X, 6</span>; a. v. fr.—V. <a href=\"#\" data-headword=\"טְרִיפוֹן\">טְרִיפוֹן</a>.</div>","alt":[]},"14057":{"h":"טרפוניטיס","r":"I00870","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טְרַפִּיזִיטֵיס\">טְרַפִּיזִיטֵיס</a></div>","alt":[]},"14058":{"h":"טרפזין","r":"I00871","html":"<div class=\"sense\">, read: <a href=\"#\" data-headword=\"טְרַפִּיזִין\">טְרַפִּיזִין</a>.</div>","alt":[]},"14059":{"h":"טַרְפַּחַת","r":"I00872","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טָפַח I\">טפח</a>, with <a href=\"#\" data-headword=\"ר\">ר</a> inserted; cmp. <a href=\"#\" data-headword=\"טְפִיחַ I\"><span dir=\"rtl\">טְפִיחַ</span> I</a>) [<i>pitcher</i>, cmp. <a href=\"#\" data-headword=\"*אָכוּז\">אָכוּז</a>,] <i>mouth of the womb</i>. <span class=\"citation\">Ḥull. 55ᵇ</span> = <a href=\"#\" data-headword=\"אֵם\">אֵם</a> = <a href=\"#\" data-headword=\"שַׁלְפּוּחִית\">שַׁלְפּוּחִית</a>. <span class=\"citation\">Ib. 56ᵇ</span></div>","alt":[]},"14060":{"h":"טרפידא","r":"I00873","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. Lev. XI, 19</span>, v. <a href=\"#\" data-headword=\"עַרְפְּדָא\">עַרְפְּדָא</a>.</div>","alt":["(טרפירא)"]},"14061":{"h":"טְרַפִּיזָא","r":"I00874","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (τράπεζα) <i>table, counter</i>.—Pl. <a href=\"#\" data-headword=\"טְרַפִּיזִין\">טְרַפִּיזִין</a>. <span class=\"citation\">Gen. R. s. 64</span>, end (‘Rashi’: <span dir=\"rtl\">טְרַפִּיזוֹת</span>).—V. <a href=\"#\" data-headword=\"טְרַפִּיזִין\">טְרַפִּיזִין</a>.</div>","alt":[]},"14062":{"h":"טְרַפִּיזִיטֵיס","r":"I00875","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (τραπεζίτης) <i>money-changer, banker</i>. <span class=\"citation\">Y. B. Mets. IV, beg. 9ᶜ</span> <a href=\"#\" data-headword=\"טרפוניטיס\">טרפוניטיס</a> (corr. acc.). <span class=\"citation\">Num. R. s. 4</span> <a href=\"#\" data-headword=\"טְרַפְסִיטֵיס\">טְרַפְסִיטֵיס</a> (cmp. τράπεσα for τράπεζα, S.).</div>","alt":[]},"14063":{"h":"טְרַפִּיזִין","r":"I00876","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (τραπέζιον) <i>table, trencher</i>. <span class=\"citation\">Gen. R. s. 11</span> Ar., v. <a href=\"#\" data-headword=\"דִּיסְקוֹס I\"><span dir=\"rtl\">דִּיסְקוֹס</span> I</a>.</div>","alt":[]},"14064":{"h":"טרפירא","r":"I00877","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טרפידא\">טרפידא</a></div>","alt":[]},"14065":{"h":"טַרְפִּישָׁא","r":"I00878","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טַרְפְּשָׁא\">טַרְפְּשָׁא</a></div>","alt":[]},"14066":{"h":"טָרָפִיתָא","r":"I00879","html":"<div class=\"sense\">, f. (<a href=\"#\" data-headword=\"טַרְפָא I\">טְרַף</a>) <i>hawk</i>. <span class=\"citation\">Targ. O. Lev. XI, 14</span>; <span class=\"citation\">Deut. XIV, 13</span> (h. text <a href=\"#\" data-headword=\"אַיָּה\">איה</a>).</div>","alt":[]},"14067":{"h":"טַרְפִיתָא","r":"I00880","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> adj. (<a href=\"#\" data-headword=\"טָרָפִיתָא\">preced.</a>) <i>tearing</i>. <span class=\"citation\">Targ. Y. Lev. XI, 14</span> <span dir=\"rtl\">דַּיְּתָא ט׳</span> (not <span dir=\"rtl\">דחיא</span>); cmp. <a href=\"#\" data-headword=\"דַּיָּה\">דַּיָּה</a>.</div>","alt":[]},"14068":{"h":"טִרְפֵּס","r":"I00881","html":"<div class=\"sense\">, <i>Hithpa</i>. <span dir=\"rtl\">הִטַּרְפֵּס</span> <i>to climb</i>, v. <a href=\"#\" data-headword=\"טָפַס\">טָפַס</a>.</div>","alt":[]},"14069":{"h":"טַרְפֵּס","r":"I00882","html":"<div class=\"sense\">, <i>Ithpa.</i> <span dir=\"rtl\">אִטַּרְפֵּס</span> (v. <a href=\"#\" data-headword=\"טִרְפֵּס\">preced.</a>, cmp. <a href=\"#\" data-headword=\"טְפַז\">טְפַז</a>) <i>to leap, take exercise</i>. <span class=\"citation\">Y. Kidd. II, 62ᶜ</span> bot. <span dir=\"rtl\">בעייא הוינא מִטַּרְפְּסָא אזלה מט׳ וכ׳</span> I expected to have exercise in going to and coming from the bath.</div>","alt":[]},"14070":{"h":"טְרַפְסִיטֵיס","r":"I00883","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טְרַפִּיזִיטֵיס\">טְרפִּיזִיטֵיס</a></div>","alt":[]},"14071":{"h":"טַרְפְּעִיק","r":"I00884","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (corresp. to τροπαϊκος = Victoriatus) <i>Victoriatus</i> = Quinarius, half a denar (v. Zuck. Talm. Münz. p. 30). <span class=\"citation\">Yoma 35ᵇ</span>. <span class=\"citation\">Gitt. 45ᵇ</span>; <span class=\"citation\">Keth. 64ᵃ</span> <span dir=\"rtl\">מאי ט׳</span> (not <span dir=\"rtl\">טרפעיקין</span>) how much is a <i>T.?</i> <span class=\"citation\">Sifré Deut. 294</span>; <span class=\"citation\">Yalk. ib. 938</span>.—Pl. <span dir=\"rtl\">טַרְפְּעִיקִין</span>. <span class=\"citation\">Keth. V, 7</span>; <span class=\"citation\">Tosef. ib. V, 7</span> (missing in ed. Zuck., Var. <a href=\"#\" data-headword=\"טרפקעי\">טרפקעי</a>; oth. ed. <span dir=\"rtl\">טַרְפְּעִיקִים</span>).</div>","alt":["טַרְפְּעִיקָא","(טרעפ׳)"]},"14072":{"h":"טרפקעי","r":"I00885","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טַרְפְּעִיק\">preced.</a></div>","alt":[]},"14073":{"h":"טַרְפְּשָׁא","r":"I00886","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טְרַף I\">טרף</a>, with formative <a href=\"#\" data-headword=\"ש\">ש</a>, as in <a href=\"#\" data-headword=\"טַרְכֵּשׁ\">טַרְכֵּשׁ</a>; v. P. Sm. 1527 s. v. <span dir=\"rtl\">טרפשתא</span>) <i>a rag-like, irregularly shaped organ, membrane</i> &amp;c. <span class=\"citation\">Ḥull. 49ᵇ</span> <span dir=\"rtl\">ט׳ דליבא</span> pericardium with the fat attached to it.—Pl. <span dir=\"rtl\">טַרְפְּשִׁין</span> <i>shreds</i>. <span class=\"citation\">Ib. 46ᵃ</span> (in Hebr. dict.) <span dir=\"rtl\">נדלדלה כבד ומעורה בט׳</span> if the liver is detached and disarranged in shreds.</div>","alt":[]},"14074":{"h":"טָרַק","r":"I00887","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"טָרַד\">טרד</a>, <a href=\"#\" data-headword=\"טְרַף I\">טרף</a>) <i>to shake, stir</i>. <span class=\"citation\">B. Kam. 115ᵇ</span> <span dir=\"rtl\">לא טְרָקוֹ</span> nobody stirred, or mixed it.</div>","alt":[]},"14075":{"h":"טְרַק I","r":"I00888","html":"<div class=\"sense\"><b>1)</b> <i>to stir, mix</i>. <span class=\"citation\">Sabb. 110ᵃ</span> <span dir=\"rtl\">ולטְרוֹקִינְהוּ בהדי הדדי</span> let him mix them together.</div><div class=\"sense\"><b>—2)</b> <i>to stir up</i>. <span class=\"citation\">Taan. 25ᵃ</span>, v. <a href=\"#\" data-headword=\"אִסְקוּטְלָא I\"><span dir=\"rtl\">אִסְקוּטְלָא</span> I</a>.</div><div class=\"sense\"><b>—3)</b>  (prob. only in) <i>Pa</i>. <a href=\"#\" data-headword=\"טָרַק\">טָרֵק</a> <i>to sting, bite</i>. <span class=\"citation\">Sabb. 109ᵇ</span> <span dir=\"rtl\">דטָרְקֵיה חיויא</span> whom a serpent has stung. <span class=\"citation\">Ib. 110ᵃ</span>, v. <a href=\"#\" data-headword=\"חִיוֵי\">חִיוֵי</a>; a. fr.—[<span class=\"citation\">Yoma 77ᵃ</span>, v. <a href=\"#\" data-headword=\"מַטְרְקָא\">מַטְרְקָא</a>.]</div>","alt":[]},"14076":{"h":"טְרַק II","r":"I00889","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"טְרַד II\"><span dir=\"rtl\">טְרַד</span> II</a>) <i>to bolt, tie, gird; to guard</i>. <span class=\"citation\">Targ. Ps. XXXV, 3</span>, v. <a href=\"#\" data-headword=\"*טרוקיתקא\">טרוקיתקא</a>.—<span class=\"citation\">Ber. 28ᵃ</span> <span dir=\"rtl\">טְרוֹקוּ גלי</span>; <span class=\"citation\">Snh. 113ᵃ</span> <span dir=\"rtl\">דטַרְקֵיה</span>, v. <a href=\"#\" data-headword=\"גַּלָּא\">גַּלָּא</a>. <span class=\"citation\">B. Mets. 86ᵃ</span> <span dir=\"rtl\">וטַרְקֵיה לבבא וכ׳</span> and bolted the door before him. <span class=\"citation\">Erub. 102ᵃ</span> <span dir=\"rtl\">דין לא נִטְרוֹק</span> this must not bolt, i.e. with this bolt as it is you dare not bolt or unbolt. <i>Part. pass</i>. <span dir=\"rtl\">טָרִיק</span> <i>locked up</i>. <span class=\"citation\">Targ. Job XXVI, 13</span> (h. text <a href=\"#\" data-headword=\"בָּרִיחַ\">בָּרִחַ</a>).</div>","alt":[]},"14077":{"h":"טַרְקָא","r":"I00890","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טְרַק II\">preced.</a>; cmp. Syr. <a href=\"#\" data-headword=\"טָרַק\">טרק</a>, P. Sm. 1528) <i>a castle, palace</i>. <span class=\"citation\">Targ. Prov. XXV, 24</span> <span dir=\"rtl\">וביתא ט׳</span> though the house be a palace (h. text <span dir=\"rtl\">ובית חבר</span>).</div>","alt":[]},"14078":{"h":"טָרָקָא","r":"I00891","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (טְרַק I) <i>stirring up, disturbance</i>. <span class=\"citation\">Targ. Koh. X, 11</span> <span dir=\"rtl\">לט׳ ולנזקא</span> (ed. Amst. a. oth. <span dir=\"rtl\">לטַרְאָקָא</span>) for disturbance and injury.</div>","alt":[]},"14079":{"h":"טרקארין","r":"I00892","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טָרְקְלָרִין\">טָרְקְלָרִין</a></div>","alt":["טרקאירין"]},"14080":{"h":"טרקווינוס","r":"I00893","html":"<div class=\"sense\">, Esth. R. beg. <span dir=\"rtl\">בימי ט׳</span>, read: <span dir=\"rtl\">בימי היְוָונִים</span>.</div>","alt":[]},"14081":{"h":"טַרְקוֹשׁ","r":"I00894","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טַרְכֵּשׁ\">טַרְכֵּשׁ</a></div>","alt":[]},"14082":{"h":"טְרַקְטָא","r":"I00895","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טְרִיקְטָא\">טְרִיקְטָא</a></div>","alt":["טְרַקְטָה"]},"14083":{"h":"טרקי","r":"I00896","html":"<div class=\"sense\">, <span class=\"citation\">Yoma 10ᵃ</span> Ar., v. <a href=\"#\" data-headword=\"תְּרַיְיקִי\">תרייקי</a></div>","alt":[]},"14084":{"h":"טַרְקְיָא","r":"I00897","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> s. v. <a href=\"#\" data-headword=\"בָּלַס\">בלס</a>: <a href=\"#\" data-headword=\"תַּרְקְיָא\">תַּרְקְיָא</a>; cmp. <i>anthracias</i>, ἀνθράκιον) name of a <i>gem.</i> <span class=\"citation\">Targ. O. Ex. XXVIII, 19</span> (Y. <a href=\"#\" data-headword=\"עַרְקִין\">ערקין</a>, corr. acc.); ib. XXXIX, 12. <span class=\"citation\">Targ. Y. Num. II, 18</span>.</div>","alt":["טַרְקִין"]},"14085":{"h":"טרקילין","r":"I00898","html":"<div class=\"sense\">, read: <a href=\"#\" data-headword=\"טְרִיקְלִין\">טְרִיקְלִין</a>.</div>","alt":[]},"14086":{"h":"טְרַקְלִילָא","r":"I00899","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (comp. of <a href=\"#\" data-headword=\"טְרַק I\">טְרַק</a> II a. <a href=\"#\" data-headword=\"קַלִּיל II\">קלילא</a>) <i>the runner’s strapping, leggin, greave</i>. <span class=\"citation\">Targ. Esth. V, 9</span> <a href=\"#\" data-headword=\"אִסְטַרְקְלִילָא\">אִסְטַרְקְלִילֵיה</a> his leggin.—Pl. <a href=\"#\" data-headword=\"טְרִיקְלִילִין\">טְרַקְלִילִין</a>. <span class=\"citation\">Targ. I Sam. XVIII, 6</span> (ed. Lag. <span dir=\"rtl\">טְרִיקְלִ׳</span>; Kimḥi Vers. <span dir=\"rtl\">טרקלין</span>). [<span dir=\"rtl\">טרקלילין</span>, <span class=\"citation\">Tosef. Sabb. XVI</span> (<span class=\"citation\">XVII), 18</span>; <span class=\"citation\">Tosef. Bets. II, 10</span> Ar., v. <a href=\"#\" data-headword=\"טְרִיקְלִין\">טְרִיקְלִין</a>.]</div>","alt":["אִסְטַרְקְלִילָא"]},"14087":{"h":"טְרַקְלִין","r":"I00900","html":"<div class=\"sense\">, v. <span dir=\"rtl\">טְרִיקְלִ׳</span>. [V. <a href=\"#\" data-headword=\"טְרַקְלִילָא\">preced.</a> w.]</div>","alt":["טְרַקְלִינָא"]},"14088":{"h":"טָרְקְלָרִין","r":"I00901","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (torcularium) <i>store-room for oil and wine</i>. Y’lamd. to Num. XX, 8 (quot. in Ar.) <span dir=\"rtl\">ט׳ אם יהיה ביד אדם</span> if a man possesses a torcularium; Yalk. ib. 763 (our w. omitted); <span class=\"citation\">Ex. R. s. 25</span>, beg. <a href=\"#\" data-headword=\"טרקארין\">טרקארין</a>, <a href=\"#\" data-headword=\"טרקארין\">טרקאירין</a> (read: <a href=\"#\" data-headword=\"טָרְקְלָרִין\">טָרְקְלָארִין</a>).</div>","alt":[]},"14089":{"h":"טרקנין","r":"I00902","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טְרִיקְטָא\">טְרִיְקטָא</a></div>","alt":[]},"14090":{"h":"טְרַקְסָאוֹת","r":"I00903","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (enlargement of <a href=\"#\" data-headword=\"טְרַק II\"><span dir=\"rtl\">טְרַק</span> II</a>, cmp. <a href=\"#\" data-headword=\"טְרַכְסִיד\">טְרַכְסִיד</a>) <i>lath- and plaster-wall, partition in the interior of houses</i>. <span class=\"citation\">Tosef. Ohol. V, 5</span> כלים שבט׳ R. S. to Ohol. IV, 1 (ed. <a href=\"#\" data-headword=\"רסטקאות\">רסטקאות</a>, Var. <span dir=\"rtl\">רטסק׳</span>) vessels lying in niches or closets of partition walls.</div>","alt":[]},"14091":{"h":"טְרַקְסִין","r":"I00904","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"טְרַקְסָאוֹת\">same</a>, esp. <span dir=\"rtl\">אַמָּה ט׳</span> <i>the two cedar-covered partitions</i>, with a vacant space between, which separated the Holy of Holies from the Holy and occupied the space of <i>onecubit</i>, the text (<span class=\"citation\">I Kings VI, 16</span>) leaving it undecided from which of the two sacred areas that cubit’s space was deducted. In the second Temple that partition was replaced by two curtains with a space between. <span class=\"citation\">Midd. IV, 7</span> <span dir=\"rtl\">אמה ט׳</span> one cubit for the partition. <span class=\"citation\">Yoma 51ᵇ</span> <span dir=\"rtl\">אבל … אמה ט׳ וכ׳</span> but in the second Temple, where there was no partition wall, … they made two curtains. <span class=\"citation\">B. Bath. 3ᵃ</span>; a. fr.—<span class=\"citation\">Y. Kil. VIII, 31ᶜ</span> bot. (among doubtful things) <span dir=\"rtl\">ואמה ט׳</span> (add to the above six things) the <i>ammah traksĭn</i>. <span dir=\"rtl\">מהו ואמה &#x27;ט</span> why is it called <i>a. tr.?</i> (Answ., taking our w. for τάραξιν, acc. of τάραξις, confusion) <span dir=\"rtl\">טריכסון מהו מבפנים מבחוץ</span> (ἐτάραξεν, cmp. <a href=\"#\" data-headword=\"*בריכסון\">בריכסון</a>) it created confusion: what is it? inside? outside?; <span class=\"citation\">Y. Yoma V, 42ᵇ</span> bot. <a href=\"#\" data-headword=\"טירקסון\">טירקסון</a>.</div>","alt":["טְרִיקְ׳"]},"14092":{"h":"טרקסמון","r":"I00905","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טְרוֹקְסִימָא\">טְרוֹקְסִימוֹן</a></div>","alt":[]},"14093":{"h":"טְרַשׁ I","r":"I00906","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"טְרַף I\">טרף</a>) <i>to batter</i>. <span class=\"citation\">B. Kam. 98ᵃ</span> <span dir=\"rtl\">מחייה וטַרְשֵׁיה …</span> (Var. <span dir=\"rtl\">טרסיה</span>, v. Rabb. D. S. a. l. note 300) he struck upon the coin with the hammer and battered it (so that the stamp was effaced).</div><div class=\"sense\"><b>Pa. טָרֵישׁ</b> <div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"טֶרֶשׁ\">טֶרֶשׁ</a>) <i>to harden, make brittle.</i> <span class=\"citation\">Ḥull. 46ᵇ</span> <span dir=\"rtl\">בקרירי לא דמְטָרְשֵׁי</span> you must not put the lungs in cold water, because it makes the coat of the lungs brittle (so as to crack when you blow them up; [Ar. ed. Koh. <span dir=\"rtl\">בחמימי לא דמט׳</span> not in hot water because ‘it makes strong’]; v. <a href=\"#\" data-headword=\"כְּוֵץ\">כְּוַץ</a>.</div></div>","alt":[]},"14094":{"h":"טְרַשׁ II","r":"I00907","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"טְרַק II\"><span dir=\"rtl\">טְרַק</span> II</a>) <i>to lock up, obstruct;</i> (neut. v.) <i>to be stopped up</i>, (trnsf.) <i>to be deaf, silent</i>. Tanḥ. Vayishl. 8 <span dir=\"rtl\">מהולתך טַרְשָׁא וכ׳</span>, v. <a href=\"#\" data-headword=\"חֲרַשׁ\">חֲרַשׁ</a>; Y’lamd. to Lev. XXVII, end and to <span class=\"citation\">Num. XXI, 1</span> (quot. in Ar.).—<span class=\"citation\">Lam. R. to I, 17</span> [read:] <span dir=\"rtl\">ט׳ סלקית וט׳ נחתית</span> (not <a href=\"#\" data-headword=\"*טמשא\">טמשא</a>) silent do I go up (to Jerusalem) and silent do I go down.</div>","alt":[]},"14095":{"h":"טֶרֶשׁ","r":"I00908","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <span dir=\"rtl\">טְרָשִׁים</span>, <span dir=\"rtl\">טְרָשִׁין</span> (טרש I) <i>rugged, stony ground; crags, clefts; quarry</i>.  <span class=\"citation\">B. Bath. 103ᵃ</span> <span dir=\"rtl\">ט׳ שאמרו</span> the crags of which they speak (<span dir=\"rtl\">נקעים</span> a. <span dir=\"rtl\">סלעים</span> ib. Mish. <span class=\"citation\">ib. VII, 1</span>). <span class=\"citation\">Y. Kil. I, 27ᵇ</span> bot. <span class=\"citation\">Arakh. 14ᵇ</span>; <span class=\"citation\">Yalk. Lev. 677</span> <span dir=\"rtl\">טְרָסִין</span>. <span class=\"citation\">Gen. R. s. 23</span> <span dir=\"rtl\">נעשו ט׳</span> became craggy (unarable). <span class=\"citation\">Lev. R. s. 36</span> <span dir=\"rtl\">ט׳ גדולים</span> large stony clods, v. <a href=\"#\" data-headword=\"בָּלַשׁ\">בָּלַשׁ</a>. <span class=\"citation\">Sot. 34ᵇ</span>. <span class=\"citation\">Y. B. Bath. IV, 14ᶜ</span> bot. <span dir=\"rtl\">הט׳ המוקצין וכ׳</span> the rocks which are cut from it (the quarry).</div>","alt":[]},"14096":{"h":"טַרְשָׁא","r":"I00909","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (טְרַשׁ II) [<i>deafness</i>,] (sub. <a href=\"#\" data-headword=\"רִבִּית\">רִבִּית</a>) <i>deaf or silent usury, tarsha, a sale on time at a price higher than the seller would take if he sold for cash</i>, e.g. one sells beer in Tishri (when it is cheap), to be paid for in Nisan (when beer is higher) at the Nisan price. <span class=\"citation\">B. Mets. 65ᵃ</span> ט׳ שרי <i>tarsha</i> is permitted (is no usury). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ט׳ דידי</span> my (R. Papa’s) <i>tarsha</i> (sale of date beer on time &amp;c., v. supra). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ט׳ דידי ודאי וכ׳</span> my (R. Ḥama’s) <i>tarsha</i> (selling goods to be carried at his risk to the dearer market, the money to be paid on returning) &amp;c. Y. ib. V, 10ᶜ bot. <span dir=\"rtl\">אין זו רביתא אלא ט׳</span> (not <a href=\"#\" data-headword=\"הֶטְרֵשָׁא\">הטרשא</a>) this is not direct usury, but it is <i>tarsha</i>.—Pl. <a href=\"#\" data-headword=\"טַרְשִׁי\">טַרְשֵׁי</a>. Bab. <span class=\"citation\">ib. 68ᵃ</span> <span dir=\"rtl\">ט׳ פפונאי</span>, expl. <span dir=\"rtl\">כט׳ דרב פפא</span> like the sales of R. Papa, v. supra.</div>","alt":[]},"14097":{"h":"טַרְשִׁי","r":"I00910","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טַרְסִי I\">טַרְסִי</a></div>","alt":[]},"14098":{"h":"טָשּׁ","r":"I00911","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טוּשׁ\">טוּשׁ</a></div>","alt":["טַשׁ"]},"14099":{"h":"טִשְׁטוּשָׁא","r":"I00912","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טִישְׁטוּשָׁא\">טִישְׁ׳</a></div>","alt":[]},"14100":{"h":"*טַשְׁטְקֵי","r":"I00913","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> [or <a href=\"#\" data-headword=\"*טַשְׁטְקֵי\">טַשְׁטְקִי</a> f. sing.] (= <span dir=\"rtl\">תַּשְׁתְּ׳</span>, <a href=\"#\" data-headword=\"שקי\">שקי</a>; cmp. <span dir=\"rtl\">טַצְיְּקָא</span>) <i>troughs</i>, or <i>bucket arrangement</i> for pumping water for the boiler. <span class=\"citation\">Nidd. 68ᵃ</span> אטו … ט׳ חסרת וכ׳ Ar. (ed. omit <a href=\"#\" data-headword=\"אָטוּ\">אטו</a>) doest thou want boilers? dost thou want buckets? dost thou want slaves? [Rashi: <i>bathing chairs;</i> Tosaf. to <span class=\"citation\">Nidd. 66ᵇ</span>, a. v. <span dir=\"rtl\">אם</span>, identifies our w. with <a href=\"#\" data-headword=\"טכטכא\">טכטכא</a>; Saadia: <i>combs</i>.]</div>","alt":[]},"14101":{"h":"טִשְׁטֵשׁ","r":"I00914","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טוּשׁ I\"><span dir=\"rtl\">טוּשׁ</span> I</a></div>","alt":["טַשְׁטֵשׁ"]},"14102":{"h":"טְשֵׁי","r":"I00915","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"טוּשׁ II\"><span dir=\"rtl\">טוּשׁ</span> II</a>) </div><div class=\"sense\"><b>1)</b> <i>to hide, protect; to reserve</i>. <span class=\"citation\">Targ. Ps. XXVII, 5</span>. <span class=\"citation\">Targ. Prov. II, 1</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to be hidden, lie in wait</i>. <span class=\"citation\">Targ. Ps. LVI, 7</span> <span dir=\"rtl\">יִטְשׁוּן בכמנא</span> (ed. Lag. <span dir=\"rtl\">י׳ כמנא</span>; h. text <span dir=\"rtl\">יצפינו</span>, K’ri <span dir=\"rtl\">יצפונו</span>). <span class=\"citation\">Targ. Prov. I, 11</span>; a. e.—<span class=\"citation\">Taan. 24ᵃ</span> <span dir=\"rtl\">טָשׁוּ מיניה</span> (<a href=\"#\" data-headword=\"הֲווֹ\">הוו</a>) they hid themselves before him. <span class=\"citation\">Ib. 29ᵃ</span> <span dir=\"rtl\">טשא מינייהו</span> hid himself before the Romans. <span class=\"citation\">Ab. Zar. 70ᵃ</span> <span dir=\"rtl\">כי היכי דטְשִׁינָא אנא אִיטְּשֵׁי וכ׳</span> as well as I hide myself here, an Israelite may have hidden himself &amp;c.; a. e.</div><div class=\"sense\"><b>Ithpe. אִתְטְשֵׁי  אִיטְּשֵׁי</b> <div class=\"sense\"><i>to hide one’s self, to be hidden</i>. <span class=\"citation\">Targ. Prov. XXVIII, 28</span>. <span class=\"citation\">Ib. XXVII, 5</span> <span dir=\"rtl\">מִטַּשְׁיָא</span> hidden. <span class=\"citation\">Targ. Ps. LXXXIII, 4</span> <span dir=\"rtl\">מִתְטְשִׁין</span> (some ed. <span dir=\"rtl\">מִטַּטְשִׁין</span>).—<span class=\"citation\">Ab. Zar. 70ᵃ</span>, v. supra.</div></div><div class=\"sense\"><b>Af. אַטְשֵׁי</b> <div class=\"sense\"><i>to hide</i>. <span class=\"citation\">Targ. Prov. XXV, 2</span>. <span class=\"citation\">Ib. XXVI, 15</span>.</div></div>","alt":["טְשָׁא"]},"14103":{"h":"טַשְׁיוּתָא","r":"I00916","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טְשֵׁי\">preced.</a>) <i>that which is reserved, future compensation</i>. <span class=\"citation\">Targ. Ps. XVII, 14</span>. <span class=\"citation\">Targ. Job. XX, 26</span>.</div>","alt":[]},"14104":{"h":"י","r":"J00000","html":"<div class=\"sense\"><i>Yod</i>, the tenth letter of the Alphabet. It interchanges with <a href=\"#\" data-headword=\"ו\">ו</a>, e.g. <a href=\"#\" data-headword=\"יָדַע\">יָדַע</a> a. <a href=\"#\" data-headword=\"וַדַּאי\">וַדַּאי</a>; with <a href=\"#\" data-headword=\"א\">א</a> as <a href=\"#\" data-headword=\"יְבַד\">יבד</a> a. <span dir=\"rtl\">אבד</span>; with <a href=\"#\" data-headword=\"ה\">ה</a>, v. letter <a href=\"#\" data-headword=\"ה\">ה</a>.—<a href=\"#\" data-headword=\"י\">י</a> is frequently a <i>mater lectionis</i> for ē, ĕ, and ī, ĭ, e.g. <a href=\"#\" data-headword=\"לֵילוֹךְ\">לֵילֵךְ</a>, <span dir=\"rtl\">לֵישֵׁב</span> (for b. h. <span dir=\"rtl\">לָלֶכֶת</span>, <span dir=\"rtl\">לָשֶׁבֶת</span>); <a href=\"#\" data-headword=\"הֶיסֵּב\">הֶיסֵּב</a> = <a href=\"#\" data-headword=\"סָבַב\">הֶסֵּיב</a>, <a href=\"#\" data-headword=\"דִּיבּוּר\">דִּיבּוּר</a> = <a href=\"#\" data-headword=\"דִּבּוּק\">דִּבּוּר</a>.—<span dir=\"rtl\">יי</span> is frequently used to indicate the consonantal value of <a href=\"#\" data-headword=\"י\">י</a>, as <a href=\"#\" data-headword=\"יָרֵא\">הִתְיָירֵא</a> = <a href=\"#\" data-headword=\"הֶתֵּיר\">הִתְיָרֵא</a>.</div>","alt":[]},"14105":{"h":"י׳","r":"J00001","html":"<div class=\"sense\"> as a numeral, <i>ten</i>, v. <a href=\"#\" data-headword=\"א׳\">א׳</a>.</div>","alt":[]},"14106":{"h":"יֵא","r":"J00002","html":"<div class=\"sense\"> = h. <a href=\"#\" data-headword=\"אַיָּה\">אַיֵּה</a>. <i>where?</i>—<a href=\"#\" data-headword=\"לְיֵא\">לְיֵא</a>, <a href=\"#\" data-headword=\"לְיֵיא\">לְיֵיא</a> <i>whither?</i> <span class=\"citation\">Ber. 58ᵃ</span>, v. <a href=\"#\" data-headword=\"*בָּאגָנָא\">בָּאגָנָא</a>. [V. <a href=\"#\" data-headword=\"לָיָיא\">לָיָיא</a>.]</div>","alt":["יֵיא I"]},"14107":{"h":"יֵא ²","r":"J00003","html":"<div class=\"sense\"> = <span dir=\"rtl\">יְהֵא</span>, v. <a href=\"#\" data-headword=\"הֲוֵי\">הֲוֵי</a></div>","alt":["יֵיא II"]},"14108":{"h":"יָאֶה","r":"J00004","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יָאֵי\">יָאֵי</a></div>","alt":["יָאָה"]},"14109":{"h":"יָאוּ","r":"J00005","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Yau, Yai</i>. <span class=\"citation\">Ḥull. 6ᵃ</span> פונדקא דייאו Ar. (ed. <span dir=\"rtl\">דיאי</span>, prob. to be read: <a href=\"#\" data-headword=\"דִּיל־\">דִּיאִי</a>) the inn of Yau (<i>I</i>, v. <a href=\"#\" data-headword=\"*אִיהִי II\"><span dir=\"rtl\">אִיהִי</span> II</a>).</div>","alt":["יָאִי","יָי׳"]},"14110":{"h":"יַאֲוָון","r":"J00006","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יָאֵי\">יָאֵי</a></div>","alt":["יַאֲוָן"]},"14111":{"h":"יְאוֹר","r":"J00007","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"אֲרִיתָא\">אֲרִיתָא</a>) <i>channel, river</i>, esp. <i>the Nile</i>. <span class=\"citation\">Cant. R. to III, 4</span> (ref. to <span dir=\"rtl\">מיער</span> with suspended <a href=\"#\" data-headword=\"ע\">ע</a>, <span class=\"citation\">Ps. LXXX, 14</span>) <span dir=\"rtl\">אם זכיתם מן הי׳ … מן היער</span> if you will do good, the enemy attacking you will be (powerless like an animal) coming from the river, if not, he will be like a beast of the forest; Midr. Till. to Ps. l. c.; <span class=\"citation\">Yalk. Ps. 830</span>; <span class=\"citation\">Ab. d’R. N. ch. XXXIV</span> <span dir=\"rtl\">כחזיר של י׳</span> like a water swine (pork-fish, silurus). <span class=\"citation\">Ex. R. s. 1</span>. <span class=\"citation\">Ex. R. s. 9</span> <span dir=\"rtl\">המים ששמרוך … לי׳ וכ׳</span> the waters which saved thee (Moses) when thou wast thrown into the Nile, must not be smitten through thee; a. fr.</div>","alt":[]},"14112":{"h":"יְאוֹרָא","r":"J00008","html":"<div class=\"sense\">, <i>channel, dyke</i>.—Pl. <span dir=\"rtl\">יְאוֹרֵי</span>. <span class=\"citation\">B. Mets. 103ᵇ</span> <span dir=\"rtl\">אריסא בי י׳</span> (Ar. <a href=\"#\" data-headword=\"בִּיָּא\">ביה</a>), v. <a href=\"#\" data-headword=\"*אַוְורָא\">אַוְורָא</a>.</div>","alt":[]},"14113":{"h":"יֵאוּשׁ","r":"J00009","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָאַשׁ\">יָאַשׁ</a>) <i>despairing of recovering a lost object, resignation</i>. <span class=\"citation\">B. Kam. 66ᵃ</span> <span dir=\"rtl\">י׳ אינו קונה</span> the owner’s resignation gives the robber no right of possession (and he must restore the object itself, not its equivalent). <span class=\"citation\">Ib.ᵇ</span> <span dir=\"rtl\">ואי ס&quot;ד י׳ קנה וכ׳</span> and if we should assume that resignation gives a right of possession, how could the robber say, Here is thy property before thee (since in the meantime it has become valueless)?—<span class=\"citation\">B. Mets. 21ᵇ</span> top <span dir=\"rtl\">י׳ שלא מדעת</span> unconscious resignation, i.e. a thing which, if missed, is usually given up, but which has as yet not been missed. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">הוי י׳</span> is considered as given up. <span class=\"citation\">Y. B. Kam. IV, end, 4ᶜ</span> <span dir=\"rtl\">י׳ טעות</span> a resignation under a false presumption; a. fr.</div>","alt":["יֵיאוּשׁ"]},"14114":{"h":"יֵאוּשָׁא","r":"J00010","html":"<div class=\"sense\">, <i>despair</i>. <span class=\"citation\">Targ. Job VI, 26</span>.</div>","alt":[]},"14115":{"h":"יָאוּת","r":"J00011","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">יאי</span>) <i>propriety;</i> adv., (cmp. <a href=\"#\" data-headword=\"טָבָאוּת\">טַבָּאוּת</a>) <i>right; properly; it is right</i>. <span class=\"citation\">Targ. Ps. CXXVII, 2</span> <span dir=\"rtl\">על י׳</span> in propriety (honestly). <span class=\"citation\">Targ. Y. Gen. XXII, 10</span> <span dir=\"rtl\">כפוס … י׳</span> tie me well. <span class=\"citation\">Targ. O. Deut. XIII, 15</span> (Y. <a href=\"#\" data-headword=\"טָבָאוּת\">טבאות</a>, h. text <span dir=\"rtl\">היטב</span>); a. fr.—Y. Ḥag. I, 76ᵈ top <span dir=\"rtl\">וי׳ הרי וכ׳</span> and it is right so; for there is the case &amp;c.; <span class=\"citation\">Y. Peah II, 17ᵃ</span> <span dir=\"rtl\">וי׳ היא</span> (corr. acc.). <span class=\"citation\">Y. Dem. I, 21ᶜ</span> bot. <span dir=\"rtl\">י׳ הוא מקשי</span> he asks a proper question; a. fr.</div>","alt":[]},"14116":{"h":"יֵאוּתָא","r":"J00012","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יָאֲיוּתָא\">יָאֲיוּתָא</a></div>","alt":[]},"14117":{"h":"יָאֵי","r":"J00013","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>fitting, right, nice</i>. <span class=\"citation\">Targ. I Chr. XI, 11</span>; <span class=\"citation\">Targ. II Sam. XXIII, 8</span>; a. fr.—<span class=\"citation\">Men. 53ᵃ</span>; <span class=\"citation\">Yalk. Ex. 166</span> <a href=\"#\" data-headword=\"י׳\">י׳</a> it is good; <span dir=\"rtl\">י׳ וי׳</span> (v. Rabb. D. S. to Men. l. c. note 40) so much the better. <span class=\"citation\">Tam. 32ᵃ</span> <span dir=\"rtl\">בימא י׳ למידר וכ׳</span> is it better to dwell on the water or on land?—<span class=\"citation\">Ib.</span> <span dir=\"rtl\">לא י׳ למלכא כזב</span> falsehood would not become a king. <span class=\"citation\">B. Bath. 111ᵃ</span> הוא י׳ וגולתיה יָאיָא Ar. (ed. <span dir=\"rtl\">וג׳ יאי</span>) he looks nobly and so does his cloak; a. e.—Pl. <span dir=\"rtl\">יָאִין</span>, <a href=\"#\" data-headword=\"יַאֲוָון\">יַאֲוָן</a>, <a href=\"#\" data-headword=\"יַאֲוָון\">יַאֲוָון</a>, <span dir=\"rtl\">יָאָן</span>. <span class=\"citation\">Targ. Cant. III, 7</span>. <span class=\"citation\">Ib. IV, 1</span> sq. <span class=\"citation\">Targ. II Sam. XV, 3</span>; a. fr.—<i>Fem</i>. <a href=\"#\" data-headword=\"יָאיָיא\">יָאיָא</a>, <a href=\"#\" data-headword=\"יָאֶה\">יָאיָה</a>; <a href=\"#\" data-headword=\"יָאֶה\">יָאָה</a>, <a href=\"#\" data-headword=\"יָאֲתָא\">יָאֲתָא</a>. <span class=\"citation\">Targ. Y. II, Num. XII, 1</span>. <span class=\"citation\">Targ. Gen. XXIX, 17</span> (ed. Berl. <span dir=\"rtl\">יָאַיָה</span>; Y. II <a href=\"#\" data-headword=\"יָיָא\">יָיָא</a>). <span class=\"citation\">Targ. Jer. VI, 2</span> <a href=\"#\" data-headword=\"יָאֲתָא\">יאתא</a> (ed. Lag. <a href=\"#\" data-headword=\"יָאיָיא\">יָאִיתָא</a>; h. text <span dir=\"rtl\">נוה</span>). <span class=\"citation\">Targ. Prov. XIII, 19</span> (h. text <span dir=\"rtl\">נהיה</span>); a. fr.—<span class=\"citation\">B. Bath. 111ᵃ</span>, v. supra.—Pl. <span dir=\"rtl\">יָאֲיָן</span>, <span dir=\"rtl\">יָאיָין</span>, <a href=\"#\" data-headword=\"יָאֲתָא\">יָאָתָא</a>. <span class=\"citation\">Targ. O. Gen. XXIX, 17</span> (ed. Berl. <span dir=\"rtl\">יָאַיָן</span>). <span class=\"citation\">Targ. Y. Num. XXXI, 50</span>; a. e.—</div>","alt":["יָאֶה"]},"14118":{"h":"יָאֲיוּתָא","r":"J00014","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָאֵי\">preced.</a>) <i>beauty, grace</i>. <span class=\"citation\">Targ. Prov. I, 9</span> ed. Lag. (oth. ed. <a href=\"#\" data-headword=\"יֵאוּתָא\">יֵאוּתָא</a>). <span class=\"citation\">Ib. IV, 9</span>. <span class=\"citation\">Targ. Job VIII, 6</span> <span dir=\"rtl\">יַאיַת</span> constr. ed. Lag. (oth. ed. <span dir=\"rtl\">יָּאֲיַית</span>; h. text <span dir=\"rtl\">נְוַת</span>).—Pesik. Baḥod. p. 109ᵃ (ref. to <span dir=\"rtl\">א̇נ̇כ̇י</span>, <span class=\"citation\">Ex. XX, 2</span>) <span dir=\"rtl\">א̇נא נ̇הורך כ̇לילך יֵ֗אוּתָךְ</span> I am thy light, thy crown, thy grace; <span class=\"citation\">Pesik. R. s. 21</span> <span dir=\"rtl\">יונתי</span> (corr. acc.)</div>","alt":["יָאֲיָיתָא"]},"14119":{"h":"יָאיָיא","r":"J00015","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יָאֵי\">יָאֵי</a></div>","alt":["יָאִיתָא"]},"14120":{"h":"יָאִיר","r":"J00016","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Jair</i>, </div><div class=\"sense\"><b>1)</b>  son of Manasseh. <span class=\"citation\">B. Bath. 121ᵇ</span>. <span class=\"citation\">Num. R. s. 14</span>; a. e.</div><div class=\"sense\"><b>—2)</b>  J. the Gileadite. <span class=\"citation\">B. Bath. 113ᵃ</span>.—Denom. <span dir=\"rtl\">יָאִירִי</span>, ch. <span dir=\"rtl\">יָאִירָאָה</span> m. <i>Jairite</i>. <span class=\"citation\">Targ. II Sam. XX, 26</span> (missing in ed. Lag.).—Cant. R. to I, 2ᵇ; <span class=\"citation\">Erub. 63ᵃ</span>; a. e.</div>","alt":[]},"14121":{"h":"יָאֲיָתָא","r":"J00017","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יָאֲיוּתָא\">יָאֲיוּתָא</a>.—<a href=\"#\" data-headword=\"יָאיָיא\">יָאִיתָא</a>, v. <a href=\"#\" data-headword=\"יָאֵי\">יָאֵי</a>.</div>","alt":[]},"14122":{"h":"יָאַל","r":"J00018","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הוֹאִיל\">הוֹאִיל</a></div>","alt":["יָעַל"]},"14123":{"h":"יאנא","r":"J00019","html":"<div class=\"sense\">, <span class=\"citation\">Y. Kidd. IV, 66ᵇ</span> top <span dir=\"rtl\">את חמי מפייס י׳</span>, read: <span dir=\"rtl\">אתחמי מפייסי ואנא וכ׳</span> act as if you did appease me, and I will allow him to get up.—<span class=\"citation\">Y. Kil. III, beg. 28ᶜ</span> <span dir=\"rtl\">וי׳</span>, read: <span dir=\"rtl\">כל הן דאנא משכח לה וי&quot;ו אנא וכ׳</span> wherever I shall find it (<i>zeruëha</i>) with a <i>Vav</i>, I shall erase it; <span class=\"citation\">Y. Sabb. IX, 12ᵃ</span> top (corr. acc.), v. <a href=\"#\" data-headword=\"זֵרוּעַ\">זֵרוּעַ</a>.</div>","alt":[]},"14124":{"h":"יָאנִיבָא","r":"J00020","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יָנִיבָא\">יָנִיבָא</a></div>","alt":[]},"14125":{"h":"יָאסְיָן","r":"J00021","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Yasyan</i>. <span class=\"citation\">Koh. R. to VII, 11</span> R. José b. Y.; <span class=\"citation\">Ab. Zar. 42ᵃ</span>; <span class=\"citation\">Bets. 8ᵇ</span> יאסיין Ms. M. (ed. <span dir=\"rtl\">יאסיניא׳</span> v. Rabb. D. S. a. l. note); <span class=\"citation\">Men. 6ᵇ</span> (Ms. K. a. R. 2 <span dir=\"rtl\">אסיין</span>); <span class=\"citation\">Tosef. ib. I, 15</span>; (<span class=\"citation\">Y. Succ. IV, 54ᶜ</span> bot. <span dir=\"rtl\">יוסי בר אשיאן</span>).</div>","alt":["יַסְיָאן","יָאסְיָין"]},"14126":{"h":"יָארוֹד","r":"J00022","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יָרוֹד\">יָרוֹד</a></div>","alt":[]},"14127":{"h":"יָאַשׁ","r":"J00023","html":"<div class=\"sense\"> [<i>to exist, be strong</i>.]</div><div class=\"sense\"><b>Pi. יֵאֵשׁ</b> <div class=\"sense\"> (privat., cmp. <a href=\"#\" data-headword=\"דָּשֵׁן\">דִּשֵּׁן</a>) <i>to consider undone, to give up;</i> v. <a href=\"#\" data-headword=\"יֵאוּשׁ\">יֵאוּשׁ</a>.</div></div><div class=\"sense\"><b>Hithpa. הִתְיָאֵשׁ  הִתְיָי׳</b> <div class=\"sense\">; <i>Nithpa</i>. <span dir=\"rtl\">נִתְיָאֵשׁ</span>, <span dir=\"rtl\">נִתְיָי׳</span> </div><div class=\"sense\"><b>1)</b> <i>to lose energy, relax</i>. Y. Ber. IX, end, 14ᵈ <span dir=\"rtl\">שנִתְיָאֲשׁוּ ידיהם וכ׳</span> whose hands have grown lax concerning the Law (who do not care to uphold the Law; <span class=\"citation\">Midr. Till. to Ps. CXIX, 126</span> <span dir=\"rtl\">רפו ידיהם</span>).</div><div class=\"sense\"><b>—2)</b>  (with <span dir=\"rtl\">מן</span>) <i>to give up hope, to discard from the mind.</i> <span class=\"citation\">Ab. I, 7</span> <span dir=\"rtl\">אל תִּתְיָאֵשׁ וכ׳</span> do not give up the idea of divine retribution (when you see sinners prosper).—Esp. (of lost things) <i>to despair of recovery, to resign possession</i> (by which the finder acquires the right of keeping what he has found, and the robber obtains possession of the stolen object and must make restoration in value). <span class=\"citation\">B. Kam. 68ᵇ</span>, a. e. <span dir=\"rtl\">גזל ולא נִתְיָיאֲשׁוּ הבעלים</span> if one has robbed, and the owner has not yet given the hope of recovery. <span class=\"citation\">B. Mets. 21ᵇ</span> <span dir=\"rtl\">מפני שהבעלים מִתְיָאֲשִׁין מהן</span> because the owners (who dropped the coins) have given them up; a. v. fr.</div></div>","alt":[]},"14128":{"h":"יְאַשׁ","r":"J00024","html":"<div class=\"sense\">, <i>Pa</i>. <a href=\"#\" data-headword=\"יָאַשׁ\">יָאֵשׁ</a> ch. same, <i>to relax</i>. <span class=\"citation\">Targ. Koh. II, 20</span> <span dir=\"rtl\">ליָאָשָׁא ית לבי על וכ׳</span></div><div class=\"sense\"><b>Ithpa. אִתְיָאֵשׁ</b> <div class=\"sense\"><b>1)</b> <i>to become careless</i>. <span class=\"citation\">Targ. Y. Deut. XXIX, 18</span>.</div><div class=\"sense\"><b>—2)</b>  contr. <span dir=\"rtl\">אִיָּיאֵשׁ</span>, <span dir=\"rtl\">אִיָּאֵשׁ</span>, <i>Ithpe.</i> (<span dir=\"rtl\">אִיאוֹשׁ</span>) <span dir=\"rtl\">אִיאֵשׁ</span> <i>to resign possession, give up</i>. <span class=\"citation\">B. Kam. 68ᵇ</span> <span dir=\"rtl\">ודילמא לא איי׳</span> but may it not be that he has not resigned? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שמעיניה דאיאוש</span> they heard him say that he gave it up; <span class=\"citation\">B. Mets. 21ᵇ</span> <span dir=\"rtl\">דמֵיאַשׁ</span> (Ms. F. <span dir=\"rtl\">דאיאש</span>). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מִיָּאֲשֵׁי</span> (Ms. F. a. R. <span dir=\"rtl\">מִיָּי׳</span>) they give it up. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אִיאוּשֵׁי מֵיאוּשׁ</span> (better: <span dir=\"rtl\">יָאוּשֵׁי מִיָּיאֲשֵׁי</span>, v. Rabb. D. S. a. l. note 8). <span class=\"citation\">Ib. 22ᵃ</span>; a. fr.</div></div>","alt":[]},"14129":{"h":"יֹאשִׁיָּה","r":"J00025","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (b. h.) <i>Josiah</i>, </div><div class=\"sense\"><b>1)</b>  King of Judah. <span class=\"citation\">M. Kat. 25ᵇ</span> (ref. to <span class=\"citation\">Am. VIII, 9</span>) <span dir=\"rtl\">זה יומו של י׳</span> that is the day when J. was killed. Ib. 28ᵇ <span dir=\"rtl\">כמספד די׳ וכ׳</span> like the lamentation over J. &amp;c.; <span class=\"citation\">Meg. 3ᵃ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b>  R. J. a Tannai. <span class=\"citation\">Men. 57ᵇ</span>. <span class=\"citation\">Snh. 66ᵃ</span> (v. Fr. Darkhé, p. 146, sq.).</div><div class=\"sense\"><b>—3)</b>  R. J. name of two Amoraim (v. Fr. M’bo, p. 90ᵇ sq.). <span class=\"citation\">Y. Shebi. IX, 39ᵃ</span> top. <span class=\"citation\">Y. Snh. III, 21ᵈ</span>; a. fr.—<span class=\"citation\">Kidd. 36ᵇ</span>, v. <a href=\"#\" data-headword=\"דָּר ³\"><span dir=\"rtl\">דָּרָא</span> I</a>.</div>","alt":["יֹאשִׁיָּהוּ"]},"14130":{"h":"יָאֲתָא","r":"J00026","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יָאֵי\">יָאֵי</a></div>","alt":[]},"14131":{"h":"יַב","r":"J00027","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יְהַב\">יְהַב</a></div>","alt":[]},"14132":{"h":"יֵבָא","r":"J00028","html":"<div class=\"sense\"> (= <span dir=\"rtl\">יְהֵא בָא</span>) <span dir=\"rtl\">י׳ כ־</span> (= ch. <span dir=\"rtl\">אתיא כ־</span>, v. <a href=\"#\" data-headword=\"אֲתָא\">אֲתָא</a>) <i>it agrees with, corresponds to</i>. <span class=\"citation\">Y. Sabb. III, 6ᵇ</span> top <span dir=\"rtl\">י׳ כיי דמר ר׳ וכ׳</span> it agrees with what R. Z. said. Ib. XVI, 15ᶜ bot. <span dir=\"rtl\">יי׳ וכ׳</span>. <span class=\"citation\">Y. Erub. VI, 23ᶜ</span> top <span dir=\"rtl\">יי׳ כי וכ׳</span> (read <a href=\"#\" data-headword=\"כַּיי\">כיי</a>). <span class=\"citation\">Y. Pes. I, 27ᵇ</span> top [read:] <span dir=\"rtl\">יי׳ כהדא דתני כ׳ זכריה</span>; a. fr.—<span class=\"citation\">Y. Ber. I, 3ᵃ</span> top <span dir=\"rtl\">יֵיבָה כיי דר׳ זעירא</span> ed. Lehm. (oth. ed. <span dir=\"rtl\">יְהֵא בָא כיי דמר וכ׳</span>, ed. Krot. <span dir=\"rtl\">יהא בה</span>).—<span class=\"citation\">Y. B. Kam. II, end, 3ᵃ</span> <span dir=\"rtl\">יי׳ בתפלוגתה וכ׳</span> it enters into (depends upon) the difference of opinions between &amp;c.; ib. IV, 4ᵇ top <span dir=\"rtl\">יי׳ כפלוגתא</span> (read: <span dir=\"rtl\">בפ׳</span>).</div>","alt":["יֵיבָא"]},"14133":{"h":"יָבַב","r":"J00029","html":"<div class=\"sense\"> (b. h.) [<i>to break forth</i>, cmp. <span dir=\"rtl\">רעע</span>.]</div><div class=\"sense\"><b>Pi. יִבֵּב</b> <div class=\"sense\"><i>to speak in a trembling voice, to lament</i>. Y. Yeb. XVI, 15ᵈ <span dir=\"rtl\">מְיַבַּבְתּוֹ בין המתים</span> calling his name, in lamentation, among those of deceased persons; (<span class=\"citation\">Tosef. ib. XIV, 7</span> <span dir=\"rtl\">מַזְכַּרְתּוֹ</span>).</div></div>","alt":[]},"14134":{"h":"יְבַב","r":"J00030","html":"<div class=\"sense\">; <i>Pa</i>. <a href=\"#\" data-headword=\"יָבַב\">יַבֵּב</a> </div><div class=\"sense\"><b>1)</b>  (= h. <a href=\"#\" data-headword=\"רוּעַ I\">רוע</a>) <i>to sound an alarm</i>. <span class=\"citation\">Targ. Num. X, 7</span>; <span class=\"citation\">9</span>; a. fr.—</div><div class=\"sense\"><b>*2)</b>  (= h. <span dir=\"rtl\">רעע</span>) <i>to dash</i> waves against one another. <span class=\"citation\">Targ. Job XXXIV, 24</span> מְיַבֵּב Ms. Var. (ed. <span dir=\"rtl\">יתבר</span>; h. text <span dir=\"rtl\">יָרֹעַ</span>).</div><div class=\"sense\"><b>Ithpa. אִתְיַבֵּב</b> <div class=\"sense\"> (= h. <span dir=\"rtl\">התרועע</span>) <i>to shout</i>. <span class=\"citation\">Targ. Ps. LXV, 14</span>. <span class=\"citation\">Ib. CVIII, 10</span>.</div></div>","alt":[]},"14135":{"h":"יבבא","r":"J00031","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. Lev. XV, 19</span> some ed., read: <a href=\"#\" data-headword=\"יָתְבָא\">יָתָבָא</a>, v. <span dir=\"rtl\">יְתַב</span>.</div>","alt":[]},"14136":{"h":"יַבָּבָא","r":"J00032","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יבבא\">preced. art.</a>) <i>sounding an alarm, alarm</i>. <span class=\"citation\">Targ. Num. XXIX, 1</span>, quoted <span class=\"citation\">R. Hash. 33ᵇ</span>. <span class=\"citation\">Targ. O. Num. X, 5</span> sq. <a href=\"#\" data-headword=\"יַבַּבְתָּא\">יַבַּבְתָּא</a> ed. Berl. (oth. ed. <a href=\"#\" data-headword=\"יבבא\">יבבא</a>, Y. ed. <a href=\"#\" data-headword=\"יַבַּבְתָּא\">יַבֶּבְתָּא</a>). Y. ib. 10 <span dir=\"rtl\">יַבָּבוּ׳</span>; a. fr.</div>","alt":["יַבָּבוּתָא","יַבַּבְתָּא"]},"14137":{"h":"יַבָּבָה","r":"J00033","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, esp. <i>trembling, disconnected note</i> (<i>staccato</i>).—Pl. <span dir=\"rtl\">יַבָּבוֹת</span>. <span class=\"citation\">R. Hash. IV, 9</span> the value of a <i>T’ruah</i> <span dir=\"rtl\">כשלש י׳</span> (<a href=\"#\" data-headword=\"תְּרוּעָה\">תרועה</a>) is equal to three disconnected short notes. <span class=\"citation\">Pirké d’R. El. ch. XXXII</span>; <span class=\"citation\">Yalk. Gen. 102</span>.</div>","alt":[]},"14138":{"h":"יַבָּבוּתָא","r":"J00034","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יַבָּבָא\">יַבָּבָא</a></div>","alt":[]},"14139":{"h":"יבבי","r":"J00035","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. Lev. XI, 20</span> <span dir=\"rtl\">דְּיַבְבֵי</span>, read: <span dir=\"rtl\">דִּיבְבֵי</span>, v. <a href=\"#\" data-headword=\"דִּיבָבָא\">דִּיבָבָא</a>.</div>","alt":[]},"14140":{"h":"יַבַּבְתָּא","r":"J00036","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יַבָּבָא\">יַבָּבָא</a></div>","alt":["יַבֶּבְתָּא"]},"14141":{"h":"יְבַד","r":"J00037","html":"<div class=\"sense\"> Y. Shebi. IX, 38ᵈ <span dir=\"rtl\">אפי׳ צפור … לא יָבְדָּא</span> even a bird perishes not without the will of God; [<span class=\"citation\">Gen. R. s. 79</span>, a. e. <span dir=\"rtl\">מתצדא</span>, <span dir=\"rtl\">מצדיא</span>, v. <a href=\"#\" data-headword=\"צדי\">צדי</a>; <span class=\"citation\">Midr. Till. to Ps. XVII</span> <span dir=\"rtl\">אתיא</span> (ed. Bub. <span dir=\"rtl\">אתאי</span>); read: <a href=\"#\" data-headword=\"צוּד ²\">אתציד</a>;] <span class=\"citation\">Esth. R. to I, 9</span>; <span class=\"citation\">Koh. R. to X, 8</span> <span dir=\"rtl\">יברח</span> (corr. <span dir=\"rtl\">יָבְדָּה</span>).</div><div class=\"sense\"><b>Pa. יַבֵּד</b> <div class=\"sense\"><i>to ruin</i>. <span class=\"citation\">Targ. Prov. XII, 4</span> <a href=\"#\" data-headword=\"מְיַלְּדָא\">מְיַבְּדָא</a> (ed. Wil. <a href=\"#\" data-headword=\"מֵירְדָא\">מֵיבְדָא</a>).</div></div><div class=\"sense\"><b>Af. יוֹבֵד</b> <div class=\"sense\">, v. <a href=\"#\" data-headword=\"יְבַד\">אֲבַד</a></div></div>","alt":["אֲבַד"]},"14142":{"h":"יְבוּל","r":"J00038","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>growth, produce</i>. <span class=\"citation\">Ex. R. s. 12</span> <span dir=\"rtl\">י׳ הארץ</span> the produce of the ground; a. e.</div>","alt":[]},"14143":{"h":"יִבּוּם","r":"J00039","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יִבּוּם\">יִיבּוּם</a></div>","alt":[]},"14144":{"h":"יַבּוֹלֶת","r":"J00040","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יַבֶּלֶת\">יַבֶּלֶת</a></div>","alt":[]},"14145":{"h":"יַבְחוּשׁ","r":"J00041","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בָּחַשׁ\">בָּחַשׁ</a>) a sort of <i>gnat, a</i> (<i>red</i>) <i>insect</i> found in liquids. Tosef. Yad. (T’bul Yom) II, 3 <span dir=\"rtl\">י׳ שבריתו וכ׳</span> a <i>yabḥush</i> which originates in the water.—Pl. <span dir=\"rtl\">יַבְחוּשִׁים</span>, <span dir=\"rtl\">יַבְחוּשִׁין</span>. <span class=\"citation\">Tosef. Ter. VII, 11</span>; <span class=\"citation\">Ḥull. 67ᵃ</span>. <span class=\"citation\">Nidd. III, 2</span> <span dir=\"rtl\">כמין י׳ אדומים</span> looking like a mass of red insects; <span class=\"citation\">Tosef. ib. IV, 2</span>. <span class=\"citation\">Zeb. 22ᵃ</span></div>","alt":[]},"14146":{"h":"יְבִימָא","r":"J00042","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יָבָם\">יָבָם</a> ch.</div>","alt":["יְבִימָה"]},"14147":{"h":"יְבִימְתָּא","r":"J00043","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יְבַמְתָּא\">יְבִמְ׳</a></div>","alt":[]},"14148":{"h":"יְבֵישּׁ","r":"J00044","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יְבֵשׁ\">יְבֵשׁ</a></div>","alt":[]},"14149":{"h":"יַבִּישׁ","r":"J00045","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יָבֵשׁ\">יָבֵשׁ</a> ch.</div>","alt":[]},"14150":{"h":"יְבֵישָׁה","r":"J00046","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יָבֵשׁ I\"><span dir=\"rtl\">יָבֵשׁ</span> I</a></div>","alt":[]},"14151":{"h":"יַבִּישְׁתָּא","r":"J00047","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יַבַּשְׁתָּא\">יַבֶּשְׁתָּא</a>, a. <a href=\"#\" data-headword=\"יָבֵשׁ\">יָבֵשׁ</a> ch.</div>","alt":["יְבֵישְׁתָּא"]},"14152":{"h":"יָבַל I","r":"J00048","html":"<div class=\"sense\"> (b. h.) [<i>to break through, come forth, run, flow</i>.—V. <a href=\"#\" data-headword=\"יְבוּל\">יְבוּל</a>, <a href=\"#\" data-headword=\"יִבְלָא I\">יִבְלָא</a></div><div class=\"sense\"><b>Hif. הוֹבִיל</b> <div class=\"sense\"><i>to lead; to carry, bring</i>. <span class=\"citation\">Sifré Deut. 43</span> (ref. to <span dir=\"rtl\">יבולה</span>, <span class=\"citation\">Deut. XI, 17</span>) <span dir=\"rtl\">אף לא מה שאתה מוֹבִיל לה</span> not even as much as thou carriest to it (as seed); Yalk. ib. 869. <span class=\"citation\">R. Hash. 9ᵇ</span>, v. <a href=\"#\" data-headword=\"דּוּר\">דּוּר</a> ch.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"מוּבָל\">מוּבָל</a> <i>one carried, unable to move, feetless</i> &amp;c. <span class=\"citation\">Toh. VII, 5</span> <span dir=\"rtl\">אפי׳ מ׳ אפי׳ כפות</span> even if he is unable to move, even if he is tied; <span class=\"citation\">Tosef. ib. VIII, 7</span> <span dir=\"rtl\">והלה מוּוָל או כפות</span> ed. Zuck. (ed. <span dir=\"rtl\">ממלאו</span>, read: <span dir=\"rtl\">מוול או</span>); Y. Ḥag. II, end, 78ᶜ <span dir=\"rtl\">אפי׳ מאכל ואפי׳ כסות</span> (corr. acc.). [For <a href=\"#\" data-headword=\"יָבַל I\">הוֹבִיל</a> <i>to study</i>, v. <a href=\"#\" data-headword=\"בִּיל\">בִּיל</a> h.]</div></div>","alt":[]},"14153":{"h":"יְבַל","r":"J00049","html":"<div class=\"sense\">, Af. <span dir=\"rtl\">אוֹבִיל</span>, <span dir=\"rtl\"><span dir=\"rtl\">אֵיבֵיל</span> (הֵיבֵל</span>), <span dir=\"rtl\">אַיְיבֵל</span> ch. same. <span class=\"citation\">Targ. Ps. LXVI, 6</span>. <span class=\"citation\">Targ. Is. X, 32</span> (v. infra); a. fr.—<span class=\"citation\">Erub. 27ᵇ</span>, a. e. <span dir=\"rtl\">מוֹבִילְנָא מאניה וכ׳</span> I will carry his clothes after him to the bath-house. <span class=\"citation\">Snh. 95ᵃ</span> (ref. to <span dir=\"rtl\">ינפף</span>, Is. l. c.) <span dir=\"rtl\">מוֹבִיל ומייתי וכ׳</span> moving his hand to and back (= h. <span dir=\"rtl\">מוליך ומביא</span>, v. <a href=\"#\" data-headword=\"בּוֹא\">בּוֹא</a>); a. fr.—[<span class=\"citation\">Ezra V, 14</span>; <span class=\"citation\">VI, 5</span>.]—<span class=\"citation\">Y. Meg. IV, 75ᵇ</span> bot. <span dir=\"rtl\">כד דאינן תרתייתי מֵיבֵל וכ׳</span> when two scrolls are used, he carries one away and brings another in; <span class=\"citation\">Y. Sot. VII, end, 22ᵃ</span> <span dir=\"rtl\">תרתיי תו מַיְיבֵל</span> (corr. acc.); <span class=\"citation\">Y. Yoma VIII, 44ᵇ</span> top <span dir=\"rtl\">מייכל</span> (corr. acc.). Y. Sot. l. c. <span dir=\"rtl\">מַיְיבְלִין</span>, v. <a href=\"#\" data-headword=\"אוֹרָיָיא\">אוֹרָיָיא</a>. Y. Taan. III, 66ᵈ bot. <span dir=\"rtl\">הוה מַיְיבְלָהּ וכ׳</span> (not <span dir=\"rtl\">מייבללה</span>) brought it thither.—[Y. Ab. Zar. III, 43ᵃ <span dir=\"rtl\">נייבל</span>, v. <a href=\"#\" data-headword=\"בִּיל\">בִּיל</a> ch.</div><div class=\"sense\"><b>Ithpe. אִיתּוֹבִיל</b> <div class=\"sense\"><i>to be carried</i>. <span class=\"citation\">Targ. Is. XXXIX, 6</span>.</div></div>","alt":[]},"14154":{"h":"יָבַל II","r":"J00050","html":"<div class=\"sense\"><i>Pi</i>. <a href=\"#\" data-headword=\"יִבֵּם\">יִיבֵּל</a> (denom. of <a href=\"#\" data-headword=\"יַבֶּלֶת\">יַבֶּלֶת</a>) <i>to cut off dry twigs, warts</i> &amp;c., <i>to trim.</i> <span class=\"citation\">Shebi. II, 2</span> <span dir=\"rtl\">מְיַבְּלִין מפרקין</span> (Ms. M. a. Y. ed. <span dir=\"rtl\">מְזַבְּלִין</span>, incorr.); expl. Y. ib. 33ᵈ top, v. <a href=\"#\" data-headword=\"יַבֶּלֶת\">יַבֶּלֶת</a>.</div>","alt":[]},"14155":{"h":"יִבְלָא I","r":"J00051","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (יבל I) = h. <a href=\"#\" data-headword=\"יְבַל\">יֶבֶל</a>, <i>cut, brook</i>.—Pl. <span dir=\"rtl\">יִבְלִין</span>. <span class=\"citation\">Targ. Lam. III, 48</span> (Levita sing.)</div>","alt":[]},"14156":{"h":"*יִבְלָא II","r":"J00052","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָבָל I\">נבל</a>) <i>withered piece</i>.—Pl. constr. <span dir=\"rtl\">יִבְלֵי</span>. <span class=\"citation\">Targ. Is. XLIV, 19</span>, v. <a href=\"#\" data-headword=\"*בְּלֵי II\"><span dir=\"rtl\">בְּלֵי</span> II</a>.</div>","alt":[]},"14157":{"h":"יַבְלָא","r":"J00053","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"*יִבְלָא II\">preced.</a>, a. <a href=\"#\" data-headword=\"יַבֶּלֶת\">יַבֶּלֶת</a>) <i>a species of grass, Cynodon</i> (<i>Agrostis</i>, v. Sm. Ant. s. v., a. Löw Pfl. p. 183). <span class=\"citation\">Gitt. 68ᵇ</span> bot. <span class=\"citation\">Ab. Zar. 28ᵃ</span> bot., v. <a href=\"#\" data-headword=\"גִּירְדָּא I\"><span dir=\"rtl\">גִּירְדָּא</span> I</a>.—Pl. <span dir=\"rtl\">יַבְלֵי</span>. <span class=\"citation\">Sot. 10ᵃ</span> (quot. Rashi to Ab. Zar. l. c., ed. <a href=\"#\" data-headword=\"דּוּבְלָא\">דובלא</a>, read: <a href=\"#\" data-headword=\"דִּיאַטְרִיטָא\">דְּיַ׳</a>); <span class=\"citation\">Num. R. s. 9</span> (sing.), v. <a href=\"#\" data-headword=\"גִּירְדָּא I\"><span dir=\"rtl\">גִּירְדָּא</span> I</a>. <span class=\"citation\">Ḥull. 105ᵇ</span> <span dir=\"rtl\">כרך ריפתא אַיַּ׳</span> (not <a href=\"#\" data-headword=\"לִיפְתָּא\">ליפתא</a>) ate his meal so that the crumbs fell among the <i>yablé</i>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">עקרינהו לְיַ׳ וכ׳</span> he tore the plants out and cast them &amp;c.—<span class=\"citation\">Yoma 78ᵃ</span> <span dir=\"rtl\">בִּדְיַ׳</span> in shoes made of <i>yablé</i> [Ar. <span dir=\"rtl\">בדיקולי</span>, v. <a href=\"#\" data-headword=\"דִּיקוּלָא\">דִּיקוּלָא</a>).</div>","alt":[]},"14158":{"h":"יבלונה","r":"J00054","html":"<div class=\"sense\">, <span class=\"citation\">Y. Shebi. VI, 36ᵈ</span> top, read: <a href=\"#\" data-headword=\"גּוּבְלָנָא\">גּוּבְלָנָא</a>.</div>","alt":[]},"14159":{"h":"יַבְלִית","r":"J00055","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"יַבְלָא\">יַבְלָא</a>) <i>a pulp made of Cynodon leaves</i> and used for lining large water vessels. <span class=\"citation\">Kel. III, 6</span> (ed. Dehr. <a href=\"#\" data-headword=\"יַבְלִית\">יְבָלִית</a>); <span class=\"citation\">Tosef. Kel. B. Kam. III, 2</span> <span dir=\"rtl\">יַבְלוּת</span> (v. Löw Pfl. p. 186).</div>","alt":[]},"14160":{"h":"יַבְּלָן","r":"J00056","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"יַבֶּלֶת\">next w.</a>) <i>one afflicted with warts</i>. <span class=\"citation\">Targ. O. Lev. XXII, 22</span> (ed. Berl. <a href=\"#\" data-headword=\"יַבְּלָן\">יַבְלָן</a>).</div>","alt":[]},"14161":{"h":"יַבֶּלֶת","r":"J00057","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>withered excrescence;</i></div><div class=\"sense\"><b>1)</b> <i>wart</i> on the skin. <span class=\"citation\">Erub. X, 13</span> (<span class=\"citation\">103ᵃ</span>) <span dir=\"rtl\">חותכין י׳ וכ׳</span> (Rashi in ed. Sonc. <a href=\"#\" data-headword=\"יַבּוֹלֶת\">יַבּוֹלֶת</a>, v. Rabb. D. S. a. l. note) you may cut off (on the Sabbath) a wart of an animal in the Temple. Ib.; <span class=\"citation\">Pes. VI, 1</span> <span dir=\"rtl\">חתיכת יַבַּלְתּוֹ</span> the cutting of its (the sacrifice’s) warts; <span class=\"citation\">ib. 68ᵇ</span> <span dir=\"rtl\">(<a href=\"#\" data-headword=\"י׳\">י׳</a>) <a href=\"#\" data-headword=\"לֵחָה\">לחה</a></span> a moist wart, <a href=\"#\" data-headword=\"יַבָּשָׁה\">יבשה</a> whose neck is dried up; a. e.—Pl. <span dir=\"rtl\">יַבָּלוֹת</span>. <span class=\"citation\">Neg. VI, 7</span>; <span class=\"citation\">Tosef. ib. II, 12</span> <a href=\"#\" data-headword=\"יוֹבֶלֶת\">יובלת</a> (corr. acc.); Sifra Thazr., Neg., Par. 1, ch. II <span dir=\"rtl\">יַבּוֹלוֹת</span>, distinguished fr. <span dir=\"rtl\">דלדולים</span> or <a href=\"#\" data-headword=\"תַּלְתַּל\">תלתלים</a>, v. <a href=\"#\" data-headword=\"דִּלְדּוּל\">דִּלְדּוּל</a>.</div><div class=\"sense\"><b>—2)</b> <i>parasitic excrescences on trees</i>, or <i>withered twigs</i>. <span class=\"citation\">Y. Shebi. II, 33ᵈ</span> top (expl. <span dir=\"rtl\">מיבלין</span>, not <span dir=\"rtl\">מזבלין</span>, Mish.) <span dir=\"rtl\">מעבירין את היַבּוֹלֶת</span> to remove excrescences; v. <a href=\"#\" data-headword=\"יָבַל II\"><span dir=\"rtl\">יָבַל</span> II</a>.</div>","alt":[]},"14162":{"h":"יָבָם","r":"J00058","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>husband’s brother, brother-in-law</i> who in the case of his brother dying without issue enters his estate and marries his wife (<span class=\"citation\">Deut. XXV, 5</span>, sq.). <span class=\"citation\">Lev. R. s. 20</span>; <span class=\"citation\">Zeb. 102ᵃ</span> <span dir=\"rtl\">יְבָמָהּ מלך</span> her brother-in-law (Moses) was a ruler.—<span class=\"citation\">Yeb. IV, 3</span>, a. fr. <span dir=\"rtl\">שומרת י׳</span> a widow waiting for the <i>yabam</i> to marry or reject her. <span class=\"citation\">Ib. III, 9</span> <span dir=\"rtl\">שעליה זיקת י׳ אחד</span> who is tied to one <i>yabam</i>, v. <a href=\"#\" data-headword=\"זָקַק\">זָקַק</a>; a. fr.—Pl. <span dir=\"rtl\">יְבָמִין</span>. Ib. <span dir=\"rtl\">שעליה זיקת שני י׳</span> who is tied to two <i>yabamim</i> (one <i>yabam</i> having died after having engaged to marry her, the surviving brother combines in his person the original duty of the <i>yabam</i> to his first deceased brother, and the subsequent duty falling upon him on his second brother’s death). Ib. IX, 1 <span dir=\"rtl\">אסורות לִיבָמֵיהֶן</span> are forbidden in marriage to their brothers-in-law. Ib. 52ᵃ <span dir=\"rtl\">שטר כתובת י׳</span> the deed of marriage for <i>yabamim</i>. Ib. 52ᵇ <span dir=\"rtl\">התקדשי לו במאמר י׳</span> be betrothed unto me by dint of the promise arranged for <i>yabamin</i>; v. <a href=\"#\" data-headword=\"מַאֲמָר\">מַאֲמַר</a>. <span class=\"citation\">B. Bath. 119ᵇ</span> <span dir=\"rtl\">פרשת י׳</span> the chapter relating to the duties of the <i>yabam</i> and <i>y’bamah</i>; a. fr.—Denom.</div>","alt":[]},"14163":{"h":"יִבֵּם","r":"J00059","html":"<div class=\"sense\"> (b. h.) <i>to marry the wife of a brother who died without issue</i>. <span class=\"citation\">Yeb. II, 1</span> <span dir=\"rtl\">ואח&quot;כ י׳ וכ׳</span> and afterwards the second brother married &amp;c. <span class=\"citation\">Ib. 6</span> <span dir=\"rtl\">ואחד מְיַבֵּם</span> and one of the brothers may marry her. <span class=\"citation\">Ib. IV, 5</span> <span dir=\"rtl\">או חלוץ או יַבֵּם</span> either discharge (v. <a href=\"#\" data-headword=\"חָלַץ\">חָלַץ</a>) or marry (her). Ib. <span dir=\"rtl\">מצוה בגדול ליַבֵּם</span> on the eldest brother the duty devolves (in the first order) to marry the deceased’s widow. Ib. II, 7 <span dir=\"rtl\">לא יְיַבְּמוּ וכ׳</span> the other brothers must not both marry, but one discharges one, and the other &amp;c.; a. fr.</div><div class=\"sense\"><b>Hithpa. הִתְיַבְּמָה</b> <div class=\"sense\">, <i>Nithpa</i>. <span dir=\"rtl\">נִתְיַיבְּמָה</span> <i>to be married by the yabam</i>. Ib. I, 2 <span dir=\"rtl\">חולצת ולא מִתְיַבֶּמֶת</span> she must take off the <i>yabam</i>’s shoe, but cannot be married to him. Ib. 4 <span dir=\"rtl\">נִתְיַיבְּמוּ</span> if they have been married &amp;c. Ib. 20ᵇ <span dir=\"rtl\">לא תִתְיַיבַּמְנָה</span> ought not to be &amp;c. <span class=\"citation\">Num. R. s. 21</span> <span dir=\"rtl\">ואם לאו תִּתְיַיבֵּם אמנו</span> and if daughters are not considered as legal heirs, let our mother be taken in marriage by the <i>yabam;</i> a. fr.</div></div>","alt":["יִיבֵּם"]},"14164":{"h":"יַבֵּם","r":"J00060","html":"<div class=\"sense\"><span class=\"citation\">Targ. Gen. XXXVIII, 8</span>. <span class=\"citation\">Targ. Deut. XXV, 7</span>; a. e.—<span class=\"citation\">Yeb. 39ᵇ</span> <span dir=\"rtl\">אי בעית יַיבֵּם</span> if thou so desirest, marry her. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אי צבית ליַבֵּם יַבֵּם</span> if thou consentest to marry, marry. <span class=\"citation\">Ib. 40ᵃ</span> <span dir=\"rtl\">יַבּוּמֵי מְיַיבְּמֵי</span> they must marry &amp;c.—<span class=\"citation\">Ib. 31ᵇ</span> <span dir=\"rtl\">ונְיַיבֵּם לחדא וכ׳</span> let him marry one and &amp;c.; a. e.</div><div class=\"sense\"><b>Ithpa. אִתְיַיבֵּם</b> <div class=\"sense\">, contr. <span dir=\"rtl\">אִיַּיבֵּם</span> as <a href=\"#\" data-headword=\"יִבֵּם\">preced.</a> <i>Hithpa</i>. Ib. 30ᵇ <span dir=\"rtl\">לִיַּיבּוּמֵי</span> (= <span dir=\"rtl\">לְאִיַּי׳</span>) to be taken in marriage by the <i>yabam</i>. Ib. 32ᵃ <span dir=\"rtl\">תִּתְיַיבֵּם יַבּוּמֵי</span> let her be taken &amp;c.; a. e.</div></div>","alt":["יַיבֵּם"]},"14165":{"h":"יָבָם ²","r":"J00061","html":"<div class=\"sense\"> ch. = h. <a href=\"#\" data-headword=\"יָבָם\">יָבָם</a>. <span class=\"citation\">Targ. Y. Num. XXVII, 4</span> <span dir=\"rtl\">נטרא י׳</span> (= h. <span dir=\"rtl\">שומרת יבם</span>), v. <a href=\"#\" data-headword=\"יָבָם\">יָבָם</a> h.—<span class=\"citation\">Targ. Deut. XXV, 5</span>. Y. ib. 9 <span dir=\"rtl\">(<a href=\"#\" data-headword=\"יְבִימָא\">יְבִימָה</a>) <a href=\"#\" data-headword=\"יְבִימָא\">יְבִימָא</a></span>; a. e.</div>","alt":["יָי׳","יַבְמָא","יְבִימָא"]},"14166":{"h":"יְבָמָה","r":"J00062","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"יָבָם\">יָבָם</a>) <i>sister-in-law</i>, esp. <i>y’bamah,the widow of a brother who died without issue</i>. <span class=\"citation\">Yeb. IV, 10</span> <span dir=\"rtl\">הי׳ לא וכ׳</span> a widow must be neither discharged nor married before three months after her husband’s death. <span class=\"citation\">Ib. 1</span> <span dir=\"rtl\">החולץ לִיבֶמְתּוֹ</span> he who discharges his sister-in-law. <span class=\"citation\">Ib. 2</span> <span dir=\"rtl\">הכונס את יבמתו</span> he who marries &amp;c.; a. fr.—Pl. <a href=\"#\" data-headword=\"יַבָּמוּת\">יְבָמוֹת</a>. <span class=\"citation\">Ib. V, 3</span>; <span class=\"citation\">5</span>; a. fr.—<i>Y’bamoth</i> (the legal relations between Yabam and Y’bamah), name of a treatise of Mishnah, Tosefta, Talmud Babli and Y’rushalmi, of the Order of Nashim.</div>","alt":[]},"14167":{"h":"יַבָּמוּת","r":"J00063","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יְבָמָה\">preced.</a> wds.) <i>the marriage of the yabam</i>. <span class=\"citation\">Yeb. 52ᵇ</span> <span dir=\"rtl\">קידשה לשום י׳</span> if he betrothed her with the intention of complying with the law concerning the <i>yabam</i>, v. <a href=\"#\" data-headword=\"אִישׁוּת\">אִישׁוּת</a>.</div>","alt":[]},"14168":{"h":"יְבַמְתָּא","r":"J00064","html":"<div class=\"sense\"> ch. = h. <a href=\"#\" data-headword=\"יְבָמָה\">יְבָמָה</a>. <span class=\"citation\">Targ. Ruth I, 15</span>.—<span class=\"citation\">Targ. Deut. XXV, 7</span>; a. e.</div>","alt":["יְבִמְ׳","יְבִימְ׳"]},"14169":{"h":"יַבְנֶה","r":"J00065","html":"<div class=\"sense\"> (b. h.) pr. n. pl. <i>Jabneh, Jamnia</i>, north of west of Jerusalem, seat of the Sanhedrin after the destruction of Jerusalem. <span class=\"citation\">R. Hash. 31ᵃ</span>, sq. <span class=\"citation\">Gitt. 56ᵇ</span> <span dir=\"rtl\">תן לי י׳ וכ׳</span> give me (promise to spare) J. and her scholars; <span class=\"citation\">Ab. d’R. N. ch. IV</span>.—<span class=\"citation\">Keth. IV, 6</span>, a. fr. <span dir=\"rtl\">בכרם בי׳</span> in the college of R. Johanan b. Zackai in J., v. <a href=\"#\" data-headword=\"כֶּרֶם\">כֶּרֶם</a>. <span class=\"citation\">Y. Sot. VII, end, 22ᵃ</span>.—<span class=\"citation\">Tosef. Dem. I, 13</span> <span dir=\"rtl\">אוצר י׳ וכ׳</span> the store of provision in J., inside of the fortification. <span class=\"citation\">Ib. 14</span>; <span class=\"citation\">Tosef. Makhsh. III, 15</span>; <span class=\"citation\">Y. Dem. III, 23ᶜ</span> bot.; v. <a href=\"#\" data-headword=\"נָזָה\">נָזָה</a>.</div>","alt":[]},"14170":{"h":"יַבְּקָא","r":"J00066","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יוּבְּקָא\">יוּבְּקָא</a></div>","alt":[]},"14171":{"h":"יַבְרוּחַ","r":"J00067","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>mandragora, mandrake</i> (v. Löw Pfl., p. 188).—Pl. <span dir=\"rtl\">יַבְרוּחִין</span>. <span class=\"citation\">Gen. R. s. 72</span> (expl. <span dir=\"rtl\">דודאים</span>, <span class=\"citation\">Gen. XXX, 14</span>).</div>","alt":[]},"14172":{"h":"יַבְרוּחָא","r":"J00068","html":"<div class=\"sense\"> <span class=\"citation\">Y. Sabb. VI, 8ᵇ</span> top; <span class=\"citation\">Y. Erub. X, 26ᶜ</span> <span dir=\"rtl\">וההן דקרא על י׳ וכ׳</span> to read a Bible verse over mandrake is forbidden (as a superstitious practice).—Pl. <span dir=\"rtl\">יַבְרוּחִין</span>, <span dir=\"rtl\">יַבְרוּחֵי</span>. <span class=\"citation\">Targ. Gen. XXX, 14</span>, sq.—<span class=\"citation\">Snh. 99ᵇ</span></div>","alt":["יַבְרוּחָה"]},"14173":{"h":"יָבֵשׁ I","r":"J00069","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>parched, dry, withered</i>, opp. <span dir=\"rtl\">לח</span> moist, green. <span class=\"citation\">Dem. II, 3</span> <span dir=\"rtl\">לח וי׳</span> fresh or dried fruits. <span class=\"citation\">Ib. 5</span> <span dir=\"rtl\">בי׳ שלשת קבין</span> wholesale dealing in dried fruits means three Kab. Y. ib. II, end, 23ᵃ <span dir=\"rtl\">נתנו שיעור לי׳</span> for dried fruit they make quantity the standard; a. fr.—Pl. <span dir=\"rtl\">יְבֵשִׁים</span>, <span dir=\"rtl\">יְבֵשִׁין</span>; <span dir=\"rtl\">יְבֵי׳</span>. <span class=\"citation\">Sabb. IV, 1</span>. <span class=\"citation\">Pes. II, 6</span>; a. fr.—<i>Fem</i>. <a href=\"#\" data-headword=\"יַבָּשָׁה\">יְבֵשָׁה</a>, <span dir=\"rtl\">יְבֵי׳</span>. <span class=\"citation\">Ukts. I, 2</span>; a. fr.—<span class=\"citation\">Tosef. Ter. VII, 16</span> <span dir=\"rtl\">נעשית י׳</span> the date became dry (so as to be called <a href=\"#\" data-headword=\"יְבֵישָׁה\">יְבֵּישָׁה</a>).—Pl. <span dir=\"rtl\">יְבֵשׁוֹת</span>, <span dir=\"rtl\">יְבֵי׳</span>. <span class=\"citation\">T’bul Yom III, 6</span> <span dir=\"rtl\">תמרים י׳</span>, opp. <span dir=\"rtl\">רטובות</span>; a. fr.</div>","alt":[]},"14174":{"h":"יָבֵשׁ","r":"J00070","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Josh. IX, 5</span>; <span class=\"citation\">12</span>. <span class=\"citation\">Targ. Job. XIII, 25</span> (ed. Wil. <a href=\"#\" data-headword=\"יְבֵשׁ\">יְבֵשׁ</a>); a. e.—Pl. <span dir=\"rtl\">יְבֵשִׁין</span>, <span dir=\"rtl\">יְבֵשַׁיָּא</span>, <span dir=\"rtl\">יְבֵי׳</span>. <span class=\"citation\">Targ. Ez. XXXVII, 2</span>; <span class=\"citation\">4</span>.—<i>Fem</i>. <a href=\"#\" data-headword=\"יַבַּשְׁתָּא\">יְבֶשְׁתָּא</a>, <a href=\"#\" data-headword=\"יַבַּשְׁתָּא\">יְבֶישְׁ׳</a>. <span class=\"citation\">Gitt. 69ᵇ</span>. <span class=\"citation\">Bets. 33ᵃ</span>; a. e.—[V. <a href=\"#\" data-headword=\"יַבַּשְׁתָּא\">יַבַּשְׁתָּא</a>.]</div>","alt":["יַבִּישׁ"]},"14175":{"h":"יָבֵשׁ II","r":"J00071","html":"<div class=\"sense\"> <a href=\"#\" data-headword=\"יָבֵשׁ\">preced.</a>) <i>to be dry, to wither</i>. <span class=\"citation\">Bets. 26ᵇ</span> <span dir=\"rtl\">מוקצה שי׳</span> stored fruits (v. <a href=\"#\" data-headword=\"מוּקְצֶה\">מוקצה</a>) which were dry (on Friday), though the owner did not find it out until the Sabbath day; Y. ib. I, beg. 60ᵃ</div><div class=\"sense\"><b>Pi. יִיבֵּשׁ</b> <div class=\"sense\"><i>to dry up</i>. <span class=\"citation\">Gen. R. s. 33</span> <span dir=\"rtl\">עתיד … וליַיבֵּשׁ וכ׳</span> in the future a righteous man (Elijah) will come and lay the world dry (through want of rain).</div></div>","alt":[]},"14176":{"h":"יְבֵשׁ","r":"J00072","html":"<div class=\"sense\"><span class=\"citation\">Targ. O. Gen. VIII, 14</span> <a href=\"#\" data-headword=\"יְבֵישָׁה\">יְבֵישַׁת</a> ed. Berl. (oth. ed. <span dir=\"rtl\">יַבִּישַׁת</span>).—<span class=\"citation\">Y. Taan. III, 66ᵈ</span> <span dir=\"rtl\">יַבְשַׁת ידיה</span> his hand withered. <span class=\"citation\">Gitt. 69ᵇ</span> <span dir=\"rtl\">כי היכי דיביש הדא ידא וכ׳</span> (read <span dir=\"rtl\">דיְבִישַׁת</span>) as this hand (of the dead man) is withered, so may the milt of … dry (shrink to its normal size); a. e.</div><div class=\"sense\"><b>Pa. יַבֵּשׁ  יַי׳</b> <div class=\"sense\"><i>to dry</i>. <span class=\"citation\">Targ. Josh. II, 10</span>.—<span class=\"citation\">Targ. Prov. XVII, 22</span>; a. e.—Gitt. l. c. <span dir=\"rtl\">ונְיַיבְּשִׁינְהוּ בטולא</span> and let him dry them (the leeches) in the shade; a. e.</div></div><div class=\"sense\"><b>Ithpa. אִתְיַבֵּשׁ  אִיַּיבֵּשׁ</b> <div class=\"sense\"><i>to be dried up, withered</i>. <span class=\"citation\">Targ. Ps. CII, 5</span> Ms. (missing in ed.). <span class=\"citation\">Targ. Y. Gen. VIII, 14</span>; a. e.—<span class=\"citation\">Targ. Job XXXVIII, 11</span> Ms. (ed. <span dir=\"rtl\">תשוי</span>).—Gitt. l. c. <span dir=\"rtl\">נִיַּיבֵּשׁ ההיא טוחלא</span>, v. supra.</div></div>","alt":["יְבֵישׁ"]},"14177":{"h":"יַבָּשָׁה","r":"J00073","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"יְבֵשׁ\">preced.</a> wds.) <i>dry land, shore</i>. <span class=\"citation\">Gitt. 56ᵇ</span> <span dir=\"rtl\">עלה לַיַּ׳</span> he went ashore. <span class=\"citation\">Yeb. 121ᵃ</span> <span dir=\"rtl\">וכשעליתי בי׳</span> and when I landed. <span class=\"citation\">Ber. 61ᵇ</span>; a. fr.</div>","alt":[]},"14178":{"h":"יַבֶּשֶׁת","r":"J00074","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יַבָּשָׁה\">preced.</a>) <i>dry fruits, dried vegetables</i>. <span class=\"citation\">Tosef. Shebi. IV, 16</span>, contrad. to <a href=\"#\" data-headword=\"כַּבֶּשֶׁת\">כַּבֶּשֶׁת</a>.</div>","alt":[]},"14179":{"h":"יַבַּשְׁתָּא","r":"J00075","html":"<div class=\"sense\"> f. ch. = h. <a href=\"#\" data-headword=\"יַבָּשָׁה\">יַבָּשָׁה</a>. <span class=\"citation\">Targ. Gen. I, 9</span> (some ed. <a href=\"#\" data-headword=\"יַבַּשְׁתָּא\">יַבֶּשְׁ׳</a>).—<span class=\"citation\">Targ. Ps. XCV, 5</span>; a. e.—<span class=\"citation\">Tam. 32ᵃ</span>, v. <a href=\"#\" data-headword=\"יָאֵי\">יָאֵי</a></div>","alt":["יַבִּישְׁ׳","יַבִּשְׁ׳"]},"14180":{"h":"יגא","r":"J00076","html":"<div class=\"sense\">, <span class=\"citation\">Sifré Deut. 233</span>, v. <a href=\"#\" data-headword=\"*טוֹגָא\">טוֹגָא</a></div>","alt":[]},"14181":{"h":"יַגְדִּי","r":"J00077","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יַגְרִי\">יַגְרִי</a></div>","alt":[]},"14182":{"h":"יָגָה","r":"J00078","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הָגָה\">הָגָה</a></div>","alt":[]},"14183":{"h":"יגוד","r":"J00079","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יְגָר\">יְגָר</a></div>","alt":[]},"14184":{"h":"יְגוּדְיָא","r":"J00080","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Y’gudya</i>, near Ascalon. <span class=\"citation\">Tosef. Ohol. XVIII, 15</span> ed. Zuck. (R. S. to Ohol. XVIII, 9 <a href=\"#\" data-headword=\"יְגוֹר\">יְגוֹר</a>).</div>","alt":[]},"14185":{"h":"יָגוֹן","r":"J00081","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>pain, grief</i>. <span class=\"citation\">Midr. Till. to Ps. CXLVII</span>, end.—Tanḥ. Sh’mini 11 <span dir=\"rtl\">כי היין … והי׳ בא בלבו</span> for when the wine leaves his body, grief enters his (the drunkard’s) heart; a. fr.</div>","alt":[]},"14186":{"h":"יְגוֹר","r":"J00082","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יְגָר\">יְגָר</a>, a. <a href=\"#\" data-headword=\"יְגוּדְיָא\">יְגוּדְיָא</a>.</div>","alt":[]},"14187":{"h":"יגי\"ל","r":"J00083","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יג\">יג&quot;ל</a></div>","alt":[]},"14188":{"h":"יָגֵיעַ","r":"J00084","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"יָגֵעַ\">יָגֵעַ</a></div>","alt":[]},"14189":{"h":"יְגִיעַ","r":"J00085","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>painstaking, labor</i>. <span class=\"citation\">Ber. 8ᵃ</span> <span dir=\"rtl\">הנהנה מִיגִיעוֹ</span> he who enjoys the fruits of his own labor. <span class=\"citation\">Koh. R. to I, 3</span> <span dir=\"rtl\">כמה צער וכמה י׳ וכ׳</span> how much trouble and how much weariness does he experience. <span class=\"citation\">Midr. Till. to Ps. II</span> <span dir=\"rtl\">וכל יְגִיעָן וכ׳</span> and all their toil is in vain; a. fr.</div>","alt":[]},"14190":{"h":"יְגִיעָה","r":"J00086","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) <a href=\"#\" data-headword=\"יְגִיעַ\">same</a>. <span class=\"citation\">Gen. R. s. 10</span>, end; <span class=\"citation\">ib. s. 3</span>, a. e. <span dir=\"rtl\">לא בעמל ולא בי׳ וכ׳</span> (some ed. <span dir=\"rtl\">ביָגָע</span>) not with trouble and wearisome labor did the Lord create &amp;c.—<span class=\"citation\">Y. Snh. X, 28ᵃ</span> top <span dir=\"rtl\">לי׳</span>; <span class=\"citation\">Koh. R. to XII, 12</span> <span dir=\"rtl\">לִיגִיעַת בשר</span> for painful study, v. <a href=\"#\" data-headword=\"הִגָּיוֹן\">הִגָּיוֹן</a>. <span class=\"citation\">Taan. 16ᵃ</span> <span dir=\"rtl\">ויש לו י׳ בשדה</span> has his labor invested in the field.—<span class=\"citation\">Lev. R. s. 19</span>; Midr. Sam. ch. V <span dir=\"rtl\">לא שכר י׳ וכ׳</span> does not the Lord reward the work of studying?; a. fr.—Pl. <span dir=\"rtl\">יְגִיעוֹת</span>. <span class=\"citation\">Ber. 58ᵃ</span>; Y. ib. IX, 13ᶜ top <span dir=\"rtl\">כמה י׳ יגע וכ׳</span> how many labors did Adam have to go through &amp;c.; (Tosef. ib. VII (VI), 2 <span dir=\"rtl\">כמה יגע</span>). <span class=\"citation\">Lev. R. s. 28</span>, beg. <span dir=\"rtl\">כמה י׳ הוא יגע</span>; a. fr.</div>","alt":[]},"14191":{"h":"יג\"ל","r":"J00087","html":"<div class=\"sense\">, <i>Yagel</i>, a mnemotechnical acrostic, for <a href=\"#\" data-headword=\"יָחִיד\">יֹחיד</a> offering of an <i>individual</i>, <span dir=\"rtl\">בגֹלל עצמה</span>, being offered <i>by itself</i> (not as an attachment), <span dir=\"rtl\">ל̇בונה</span> requiring frankincense. <span class=\"citation\">Men. 51ᵃ</span> Ms. K. (v. Rabb. D. S. a. l. note; ed. <a href=\"#\" data-headword=\"יגי\">יגי&quot;ל</a>, the second <a href=\"#\" data-headword=\"י\">י</a> meaning <a href=\"#\" data-headword=\"יַיִן\">יֹין</a> requiring libation of <i>wine</i>, incorrect).</div>","alt":[]},"14192":{"h":"יָגַע","r":"J00088","html":"<div class=\"sense\"> [<i>to feel pain</i>,] <i>to take pains, to labor; to be tired</i>. <span class=\"citation\">Ber. 58ᵃ</span>, v. <a href=\"#\" data-headword=\"יְגִיעָה\">יְגִיעָה</a>. Y. ib. V, 5ᶜ <span dir=\"rtl\">אנו יָגַעְנוּ וכ׳</span> we have been busy at work for an entire day. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">י׳ זה לשתי וכ׳</span> this one has worked (accomplished) more in two hours &amp;c.; <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כך י׳ … בתורה וכ׳</span> so has R. Bun accomplished in studies in the twenty eight years (of his life) &amp;c.; <span class=\"citation\">Cant. R. to VI, 2</span>; <span class=\"citation\">Koh. R. to V, 11</span>. <span class=\"citation\">Meg. 6ᵇ</span> <span dir=\"rtl\">אם יאמר … יָגַעְתִּי וכ׳</span> if one tells thee, ‘I have toiled (studied) and achieved nothing’, do not believe; ‘I have not toiled and have achieved’, do not believe &amp;c.—<span class=\"citation\">Y. Ber. IX, end, 14ᵈ</span> <span dir=\"rtl\">צריך לִיגַע בתורה</span> must study the Law. <span class=\"citation\">Midr. Till. to Ps. XII</span>, beg. <span dir=\"rtl\">חדלו מליגע בתורה</span> they ceased from studying the Law; a. fr.</div><div class=\"sense\"><b>Pi. יִגֵּעַ  יִיגֵּעַ</b> <div class=\"sense\"><i>to put to trouble, to weary</i>. <span class=\"citation\">Sot. II, 1</span> (<span class=\"citation\">14ᵃ</span>) <span dir=\"rtl\">כדי לְיַגְּעָהּ</span> (Rashi: <a href=\"#\" data-headword=\"לֵיצָן\">לְיַי׳</a>) in order to wear her out (so that she may be induced to confess). Sifra Vayikra, Ḥobah, Par. 5, ch. VII <span dir=\"rtl\">אבל אם היה מְיַגְּעָן וכ׳</span> but if after having troubled them (the judges) an entire day, he says finally &amp;c.; <span class=\"citation\">Yalk. Lev. 469</span> <span dir=\"rtl\">היה מונע</span> (corr. acc.); <span class=\"citation\">Tosef. Toh. VI, 14</span> <span dir=\"rtl\">ומשהגיע</span> (read <span dir=\"rtl\">ומשהִגִּיעָן</span> <i>Hif.</i>). Y. Bets. II, 61ᶜ bot. <span dir=\"rtl\">מתוך שאתה מְיַיגְּעוֹ וכ׳</span> because you put him to special trouble (by ordering a special form of cakes) &amp;c.—<span class=\"citation\">Ex. R. s. 41</span> <span dir=\"rtl\">התלמיד … יִגַּעְתִּיךָ</span> the pupil says to the teacher, I have wearied thee; <span class=\"citation\">Yalk. Sam. 161</span>; a. fr.—Part. pass. <span dir=\"rtl\">מְיוּגָּע</span>, pl. <span dir=\"rtl\">מְיוּגָּעִים</span>, <span dir=\"rtl\">מְיוּגָּעִין</span>. <span class=\"citation\">Keth. 8ᵇ</span> <span dir=\"rtl\">ואתם אחינו המ׳ המדוכאין וכ׳</span> and you, our brethren, who are worn out and crushed by this bereavement.</div></div><div class=\"sense\"><b>Hif. הוֹגִיעַ</b> <div class=\"sense\"> (<a href=\"#\" data-headword=\"נָגַע\">הִגִּיעַ</a>) same. <span class=\"citation\">Tosef. Toh. VI, 14</span>, v. supra. <span class=\"citation\">Midr. Till. to Ps. XXXIX</span>, beg. (ref. to <span class=\"citation\">Mal. II, 17</span>) <span dir=\"rtl\">הוֹגַעְתֶּם לי במעשיכם וכ׳</span> (ed. Bub., differ.) it does not say, you wore me out with your doings, but with your words. <span class=\"citation\">Midr. Till. to Ps. XVIII, 36</span> <span dir=\"rtl\">והרב … רב לך כי הוֹגַעְתִּיךָ</span> and the teacher will say to the pupil, thou hast enough now, for I have wearied thee?; a. e.</div></div><div class=\"sense\"><b>Hithpa. הִתְיַיגֵּעַ</b> <div class=\"sense\">, <i>Nithpa</i>. <span dir=\"rtl\">נִתְיַיגֵּעַ</span> <i>to be tired, to take pains</i>. <span class=\"citation\">Gitt. 70ᵃ</span> <span dir=\"rtl\">הבא בדרך ונ׳</span> who has been travelling and is tired. Pesik. Shub., p. 164ᵃ <span dir=\"rtl\">שלא תִתְיַיגֵּעַ בחזירה</span> that you may not get tired on your way back. <span class=\"citation\">Pesik. R. s. 14</span> אני נִתְיַיגַּעְתִּי בה וכ׳ I took pains with her and smote her &amp;c.; a. fr.</div></div>","alt":[]},"14193":{"h":"יָגֵעַ","r":"J00089","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"יָגַע\">preced.</a>) <i>wearied, painstaking</i>. <span class=\"citation\">Ex. R. s. 13</span>, beg. <span dir=\"rtl\">במה אני יי׳</span> of whom am I wearied?—<span class=\"citation\">Y. Ḥag. II, 77ᵇ</span> bot. <span dir=\"rtl\">זה הוא הלשון שהיה י׳ וכ׳</span> is this the tongue which was wearing itself out with teaching the Law?; a. fr.—Pl. <span dir=\"rtl\">יְגֵעִים</span>, <span dir=\"rtl\">יְגֵעִין</span>, <span dir=\"rtl\">יְגֵי׳</span>. <span class=\"citation\">Midr. Till. to Ps. XII</span>, beg. <span dir=\"rtl\">י׳ בתורה</span> studying the Law. <span class=\"citation\">Y. Peah I, 15ᵇ</span> bot. ref. to <span class=\"citation\">Deut. XXXII, 47</span>) <span dir=\"rtl\">ואם רק הוא מכם למה שאין אתם י׳ בו</span> and if it (the word of the Law) seems to you empty, it is your fault, … because you do not study it carefully; <span dir=\"rtl\">אימתי בשעה שאתם י׳ בו</span> when (is it your life)? When you are busy studying it; Y. Succ. IV, beg. 54ᵇ; a. fr.</div>","alt":["יָגֵיעַ","יָי׳"]},"14194":{"h":"יָגָע","r":"J00090","html":"<div class=\"sense\"> m. (b. h.) = <a href=\"#\" data-headword=\"יְגִיעָה\">יְגִיעָה</a>. <span class=\"citation\">Gen. R. s. 10</span>, end, v. <a href=\"#\" data-headword=\"יְגִיעָה\">יְגִיעָה</a></div>","alt":[]},"14195":{"h":"יְגָר","r":"J00091","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, constr. <a href=\"#\" data-headword=\"יְגָר\">יְגַר</a> ch. = h. <a href=\"#\" data-headword=\"אֵגוֹר\">אֵגוֹר</a>, <i>hill, heap of stones</i>. <span class=\"citation\">Targ. O. Gen. XXXI, 47</span> (Y. <a href=\"#\" data-headword=\"אוֹגַר\">אוֹגַר</a>).—Pl. <a href=\"#\" data-headword=\"יַגְרִי\">יַגְרִין</a>. <span class=\"citation\">Targ. Jer. IX, 10</span>. <span class=\"citation\">Ib. XXVI, 18</span> (ed. Wil. <span dir=\"rtl\">יַגָרִין</span>); a. fr.—<span class=\"citation\">Targ. Job XV, 28</span> <span dir=\"rtl\">יְגוֹרִין</span>.—<span dir=\"rtl\">יְגַר שַׂהֲדוּתָא</span> pr. n. pl. (bibl.) <i>Y’gar Sahădutha</i> (Hill of Testimony). <span class=\"citation\">Tosef. Shebi. IV, 11</span> Var. (ed. Zuck. <span dir=\"rtl\">יגוד סיכותא</span>, read <a href=\"#\" data-headword=\"יְגוֹר\">יְגוֹר</a> v. <a href=\"#\" data-headword=\"סָכוּתָא\">סָכוּתָא</a>); Y. ib. VI, 36ᶜ (v. Hildesh. Beitr. p. 57, sq.).</div>","alt":[]},"14196":{"h":"יַגְרִי","r":"J00092","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Yagri</i>, in the district of Nivay (v. <a href=\"#\" data-headword=\"נְוַאי\">נִוַאי</a>). <span class=\"citation\">Tosef. Shebi. IV, 8</span>; Y. Dem. II, 22ᵈ top <a href=\"#\" data-headword=\"יַגְדִּי\">יגדי</a>.</div>","alt":[]},"14197":{"h":"יָד","r":"J00093","html":"<div class=\"sense\"> f. (rarely m.) (b. h.; </div><div class=\"sense\"><b>1)</b> <i>hand; forefoot</i>;<i> handle</i>. <span class=\"citation\">Ex. R. s. 42</span>, end <span dir=\"rtl\">מיד ליד</span> from hand to hand, directly, opp. <span dir=\"rtl\">ע&quot;י שלוחו</span> through his messenger.—<span dir=\"rtl\">י׳ רחבה</span> a wide hand, <i>liberality</i>. <span class=\"citation\">Y. Ḥag. I, 76ᶜ</span> top <span dir=\"rtl\">עני ויָדוֹ ר׳</span> a poor man who is liberal, opp. <span dir=\"rtl\">י׳ מעוטה</span> stingy.—<span class=\"citation\">Ḥull. 58ᵇ</span>, a. fr. <span dir=\"rtl\">בְּיָד</span> on the forefoot (of a quadruped).—<span class=\"citation\">Ukts. I, 1</span> <span dir=\"rtl\">כל שהוא יד ולא שזמר</span> whatever part of a fruit serves as a handle (as the stem) and not as a protector (as the shell of a nut &amp;c.). <span class=\"citation\">Kel. XXIX, 4</span> <span dir=\"rtl\">יַד הקורדום</span> the handle of an ax; a. v. fr.—<span class=\"citation\">Cant. R. to I, 4</span> <span dir=\"rtl\">לא חלתה יד ליד</span> hand does not fit hand, i.e. the two cases are incongruous.—Trnsf. <i>an intimation, an incomplete statement intelligible from context, surroundings</i> &amp;c. <span class=\"citation\">Y. Ned. I, 36ᵈ</span> top <span dir=\"rtl\">תופסין אותו משם יד לקרבן</span> we make him responsible because what he said is suggestive of the word <i>korban</i> (as a vow); a. fr.—<i>Du.</i> <span dir=\"rtl\">יָדַיִם</span>; <i>pl</i>. <span dir=\"rtl\">יָדוֹת</span>. <span class=\"citation\">Yad. I, 1</span> <span dir=\"rtl\">נותנין לי׳</span> is required for pouring on the hands. <span class=\"citation\">Ib. II, 3</span> <span dir=\"rtl\">הי׳ מטמאות וכ׳</span> hands (when being washed) become unclean or clean up to the wrist; a. v. fr.—<span dir=\"rtl\">י׳ יפות</span>, v. <a href=\"#\" data-headword=\"יָפֶה\">יָפֶה</a>.—<span class=\"citation\">Ned. 2ᵇ</span> <span dir=\"rtl\">ידות נדרים</span> (or <span dir=\"rtl\">ידות</span>) suggestions of vows, contrad. to <span dir=\"rtl\">כינויים</span>, v. <a href=\"#\" data-headword=\"כִּינּוּי\">כִּינּוּי</a>. <span class=\"citation\">Ib. 5ᵇ</span>, a. fr. <span dir=\"rtl\">י׳ שאין מוכיחות לא הויין י׳</span> suggestions which are not beyond doubt, are no (binding) suggestions; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>power, authority, possession, share</i>. <span class=\"citation\">B. Mets. 70ᵇ</span>, v. <a href=\"#\" data-headword=\"אֶמְצַע\">אֶמְצַע</a>. <span class=\"citation\">Kidd. 3ᵇ</span> <span dir=\"rtl\">קטנה דלית לה יד וכ׳</span> a minor who cannot accept a betrothal for herself. <span class=\"citation\">Ned. 88ᵇ</span> <span dir=\"rtl\">יד אשה כיד בעלה</span> the wife’s possession is her husband’s possession. <span class=\"citation\">Kidd. 23ᵃ</span> <span dir=\"rtl\">גיטו ויָדוֹ באים כאחד</span> his letter of manumission and his right of self-disposal come simultaneously. <span class=\"citation\">Yeb. 39ᵃ</span>; <span class=\"citation\">Keth. 83ᵃ</span> <span dir=\"rtl\">ידו כיָדָהּ</span> the husband’s right of disposal is as great as the wife’s (concerning what belongs to her); <span dir=\"rtl\">ידו עדיפא מידה</span> his rights are stronger than hers. <span class=\"citation\">B. Mets. VI, 2</span> <span dir=\"rtl\">יָדָן על התחתונה</span> their rights are the lowest, i.e. they are responsible for losses but can derive no benefits from favorable chances; ib. <span dir=\"rtl\">כל המשנה ידו על התחתונה וכ׳</span> whichever side changes the agreement is at a disadvantage, and whichever side breaks the agreement &amp;c.; a. v. fr.—<i>Du.</i> <span dir=\"rtl\">יָדַיִם</span>, constr. <a href=\"#\" data-headword=\"יְדִי\">יְדֵי</a>. <span class=\"citation\">Ab. Zar. 41ᵇ</span>, a. e. <span dir=\"rtl\">מִירֵי ודאי</span>, v. <a href=\"#\" data-headword=\"וַדַּאי\">וַדַּאי</a>.—<span dir=\"rtl\">יְדֵי חובתו</span>, v. <a href=\"#\" data-headword=\"יָצָא\">יָצָא</a>.</div><div class=\"sense\"><b>—3)</b> <i>portion, part.</i>—Pl. <span dir=\"rtl\">יָדוֹת</span>. <span class=\"citation\">Tosef. Men. IX, 10</span> <span dir=\"rtl\">שתי י׳</span> two thirds; a. fr.—<span dir=\"rtl\">מִיַּד</span> (= <span dir=\"rtl\">מיד ליד</span>) <i>at once, directly, immediately</i>. <span class=\"citation\">Tosef. Dem. VIII, 7</span>, v. <a href=\"#\" data-headword=\"חָלַל\">חָלַל</a> <i>Hif.</i>—<span class=\"citation\">Y. Pes. VI, 33ᵃ</span> <span dir=\"rtl\">מיד כל מי וכ׳</span> presently, every one whose Passover offering was a lamb &amp;c.; a. v. fr.— <span dir=\"rtl\">עַל יַד</span>, <span dir=\"rtl\">על יְדֵי</span> (abbr. <span dir=\"rtl\">ע&quot;י</span>) <i>through, by means of</i>. <span class=\"citation\">Gitt. 40ᵇ</span> <span dir=\"rtl\">שמא זיכה לו ע&quot;י אחר</span> he may have benefitted him (given him his liberty) through the agency of another person (without the slave’s knowledge). <span class=\"citation\">Nidd. I, 1</span> <span dir=\"rtl\">מעת לעת ממעטת ע&quot;ו וכ׳</span> the period of twenty four hours is modified by the interval between one examination and the other (if that interval is less than twenty four hours); a. v. fr.—על ידי ש־ <i>because</i>. <span class=\"citation\">Lev. R. s. 32</span> <span dir=\"rtl\">ע&quot;י שגדרו וכ׳</span> because the Israelites guarded themselves against unchastity, they were redeemed; a. v. fr.—עַל יָד עַל יָד <i>gradually, little by little</i>. <span class=\"citation\">B. Kam. 80ᵃ</span> (opp. <span dir=\"rtl\">מיד</span>); <span class=\"citation\">Tosef. ib. VIII, 15</span>. <span class=\"citation\">Par. VIII, 7</span> Hai G. (ed. only once <span dir=\"rtl\">ע&quot;י</span>).—<span dir=\"rtl\">כלאחר יד</span>, v. <a href=\"#\" data-headword=\"אַחַיי\">אַחַי</a>.—יָדַיִם <i>Yadayim</i>, name of a treatise of the Mishnah and Tosefta, of the Order of Tohăroth, containing the laws of levitical cleanness or uncleanness of the hands.</div>","alt":[]},"14198":{"h":"יַד","r":"J00094","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Num. XXXV, 17</span>; a. fr.—V. <a href=\"#\" data-headword=\"אִידָא I\">אִידָא</a>.—<span class=\"citation\">Kidd. 30ᵃ</span> top <span dir=\"rtl\">אַדְּיָדָךְ על וכ׳</span> while thy hand yet rests on thy son’s neck (as long as you have control over him). <span class=\"citation\">Ab. Zar. 15ᵃ</span> <span dir=\"rtl\">אַיָּדָא דספסירא</span> (= h. <span dir=\"rtl\">על ידי</span>) through an agent; a. fr.—Pl. <span dir=\"rtl\">יָדִין</span>, <span dir=\"rtl\">יָדַיָּא</span>. <span class=\"citation\">Targ. Ez. XXI, 12</span> (ed. Wil. <span dir=\"rtl\">יְדֵין</span>). <span class=\"citation\">Targ. Is. XIII, 7</span>; a. fr.—<span dir=\"rtl\">עַל יַד</span>, <span dir=\"rtl\">על יְדֵי</span>, v. <a href=\"#\" data-headword=\"יָד\">preced.</a> <span class=\"citation\">Targ. Ps. LXXXIX, 20</span>. <span class=\"citation\">Targ. Y. Num. XXXIII, 1</span>; a. fr.—<span dir=\"rtl\">על יְדֵי ד־</span> = h. <span dir=\"rtl\">ע&quot;י ש־</span>. <span class=\"citation\">Targ. Y. II, Gen. XLIV, 18</span>.—<span dir=\"rtl\">מִן יַד</span>, <span dir=\"rtl\">מִיַּד</span>, v. <a href=\"#\" data-headword=\"יָד\">preced.</a> <span class=\"citation\">Targ. Y. Gen. I, 3</span>. <span class=\"citation\">Targ. Ps. LIX, 12</span>; a. e.</div>","alt":["יְדָא"]},"14199":{"h":"*יְדַד","r":"J00095","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Y’dad</i>, <span class=\"citation\">Y. M. Kat. III, 82ᵃ</span>.</div>","alt":[]},"14200":{"h":"יָדָה","r":"J00096","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"ידי\">ידי</a></div>","alt":[]},"14201":{"h":"יַדּוּעַ","r":"J00097","html":"<div class=\"sense\">, (b. h.) pr. n. m. <i>Jaddua</i>. <span class=\"citation\">B. Mets. VII, 9</span> J. the Babylonian.</div>","alt":[]},"14202":{"h":"יִדּוֹעַ","r":"J00098","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> name of <i>abird</i> (Maim.) or <i>a beast</i> (Rashi), a bone of which is used for witchcraft. <span class=\"citation\">Targ. Y. Lev. XIX, 31</span> (ed. Amst. <a href=\"#\" data-headword=\"יָדוּעַ\">יָדוֹעַ</a>); a. e.—<span class=\"citation\">Snh. 65ᵇ</span>; (Tosef. ib. X, 6 <a href=\"#\" data-headword=\"יִדְעוֹנִי\">ידעוני</a>).</div>","alt":[]},"14203":{"h":"יָדוּעַ","r":"J00099","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יָדַע\">יָדַע</a></div>","alt":[]},"14204":{"h":"ידי","r":"J00100","html":"<div class=\"sense\"> (b. h.) <i>to point, move</i> (cmp. b. h. <a href=\"#\" data-headword=\"הָדָה I\">הָדָה</a>).—Denom. <a href=\"#\" data-headword=\"יָד\">יָד</a>.</div><div class=\"sense\"><b>Hif. הוֹדָה</b> <div class=\"sense\"> [<i>to raise hands</i>,] </div><div class=\"sense\"><b>1)</b> <i>to thank, acknowledge; to give praise</i>. <span class=\"citation\">Taan. 6ᵇ</span> <span dir=\"rtl\">מוֹדִים … לך</span> we offer thanks unto thee. <span class=\"citation\">Ber. V, 3</span> he who says in public prayer <span dir=\"rtl\">מודים מודים … אותו</span> ‘we thank, we thank’ (as if pointing in different directions and acknowledging two divinities) must be silenced. <span class=\"citation\">Ib. IX, 5</span> (play on <span dir=\"rtl\">מ̇אד̇ך</span>, <span class=\"citation\">Deut. VI, 5</span>) <span dir=\"rtl\">בכל מ̇ד̇ה ומדה … הוי מוֹדֶה לו</span> for whatever measure He metes out to thee, give thanks to Him. Ib. 54ᵇ <span dir=\"rtl\">ארבעה צריכין להוֹרוֹת</span> four persons are bound to offer public thanks; a. v. fr.</div><div class=\"sense\"><b>—2)</b> <i>to admit, consent, to confess</i>. <span class=\"citation\">Pes. IV, 9</span> (<span class=\"citation\">56ᵃ</span>); <span class=\"citation\">Ber. 10ᵃ</span> <span dir=\"rtl\">על ג׳ הוֹדוּ לו</span> concerning three of his acts they agreed with him. <span class=\"citation\">B. Mets. 3ᵃ</span>, a. fr. <span dir=\"rtl\">מוֹדֶה במקצת הטענה</span> he who admits part of his opponent’s claim. <span class=\"citation\">Shebu. VI, 3</span>; <span class=\"citation\">Keth. 108ᵇ</span>, a. e. <span dir=\"rtl\">טענו … וה׳ לו בשעורים</span>, v. <a href=\"#\" data-headword=\"טָעַן I\"><span dir=\"rtl\">טָעַן</span> I</a>. <span class=\"citation\">B. Mets. 12ᵇ</span> <span dir=\"rtl\">בשחייב מודה</span> when the debtor admits his indebtedness; a. v. fr. [<span class=\"citation\">Tosef. Par. IX</span> (<span class=\"citation\">VIII), 6</span> <span dir=\"rtl\">שהן מודין</span>, v. <a href=\"#\" data-headword=\"מוֹרִיר\">מוֹרִיר</a>.]</div></div><div class=\"sense\"><b>Hithpa. הִתְיַדֶּה</b> <div class=\"sense\">, <i>Nithpa</i>. <a href=\"#\" data-headword=\"נדי\">נִתְוַדֶּה</a>, (denom. of <a href=\"#\" data-headword=\"תּוֹדָה I\">תּוֹדָה</a>, cmp. <span class=\"citation\">Josh. VII, 19</span>) <i>to confess</i> one’s sins before God. <span class=\"citation\">Yoma III, 8</span> <span dir=\"rtl\">ומִתְיַרֶּה</span> and confesses in public. <span class=\"citation\">Ib. 40ᵃ</span> <span dir=\"rtl\">להגריל ולהִתְוַדּוֹת</span> to cast lots and to make confession (on the head of the scapegoat). Y. ib. VIII, end, 45ᶜ <span dir=\"rtl\">אע&quot;פ שנ׳ בערבית צריך להתודות וכ׳</span> although he has made confession in the evening prayer, he must again confess &amp;c.; a. fr.—V. <a href=\"#\" data-headword=\"וִידּוּי\">וִידּוּי</a>.</div></div>","alt":["יָדָה"]},"14205":{"h":"יְדִי","r":"J00101","html":"<div class=\"sense\">, <i>Pa</i>. <a href=\"#\" data-headword=\"ודי\">וַדֵּי</a>, <i>Ithpa.</i> <span dir=\"rtl\">אִתְוַדֵּי</span> ch. same, <i>to confess</i>. <span class=\"citation\">Targ. O. Lev. V, 5</span> (Y. <span dir=\"rtl\">יוֹדֵי</span> <i>Af</i>.). <span class=\"citation\">Targ. Y. II, Deut. III, 29</span> <span dir=\"rtl\">מִתְוַדִּין</span>; a. e.</div><div class=\"sense\"><b>Af. אוֹדִי  הוֹדִי</b> <div class=\"sense\"> as <a href=\"#\" data-headword=\"ידי\">preced.</a> <i>Hif.</i> <span class=\"citation\">Targ. Prov. XXVIII, 13</span>.—<span class=\"citation\">Targ. Gen. XLIX, 8</span>; a. fr.—<span class=\"citation\">Yoma 7ᵃ</span> מוֹדִינָא I admit (agree). <span class=\"citation\">Keth. 85ᵃ</span> <span dir=\"rtl\">ומוֹדְיָא</span> and she may admit her debt.—<span class=\"citation\">Ber. 54ᵇ</span> <span dir=\"rtl\">צריך לאוֹדוּיֵי וכ׳</span> he must offer thanks in the presence of &amp;c.—<span class=\"citation\">Shebu. 39ᵇ</span> <span dir=\"rtl\">כפר במקצת וא׳ במקצת</span> if he denies part and admits part of the claim; a. fr.</div></div>","alt":[]},"14206":{"h":"יָדִיד","r":"J00102","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> [<i>pointed out</i>,] <i>chosen, beloved; chosen spot</i>. <span class=\"citation\">Men. 53ᵃ</span> <span dir=\"rtl\">יבא י׳ בן י׳ ויבנה י׳ … ויתכפרו בו ידידים</span> the beloved (Solomon), son of the beloved (Abraham), shall rise and build a chosen structure (Temple) to the beloved (the Lord) in the lot of the beloved (Benjamin), that in it the chosen ones (Israel) be atoned for. <span class=\"citation\">Y. Ber. IX, 14ᵃ</span> bot.; <span class=\"citation\">Sabb. 137ᵇ</span> (benediction on circumcision) <span dir=\"rtl\">אשר קידש י׳ מבטן</span> who sanctified the chosen one (Abraham, <span class=\"citation\">Is. XLI, 8</span>; others: Isaac, with ref. to <span class=\"citation\">Gen. XXII, 2</span>) from the womb.—Pl. <span dir=\"rtl\">יְדִידִים</span>, v. supra.</div>","alt":[]},"14207":{"h":"יְדִידוּת","r":"J00103","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"יָדִיד\">preced.</a>) <i>choice; the chosen people</i>. <span class=\"citation\">Y. Ber. IX, 14ᵃ</span> bot.; <span class=\"citation\">Sabb. 137ᵇ</span> <span dir=\"rtl\"><a href=\"#\" data-headword=\"י׳\">י׳</a> (<span dir=\"rtl\">זרע קודש</span>) <span dir=\"rtl\">שארנו</span></span> the chosen (of the holy seed) of our blood (race).</div>","alt":[]},"14208":{"h":"יְדִיעָה","r":"J00104","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָדַע\">יָדַע</a>) <i>knowledge</i>, esp. (<span class=\"citation\">Lev. IV, 14</span>; <span class=\"citation\">23</span>; <span class=\"citation\">28</span>) <i>finding out, discovery, consciousness</i>. <span class=\"citation\">Shebu. 5ᵃ</span>, a. e. <span dir=\"rtl\">יְרִיעַת בית רבו שמה י׳</span> the knowledge acquired in the teacher’s house (a theoretical knowledge that one who touches an unclean thing becomes unclean &amp;c.) is also called a knowledge (as regards the applicability of the verb <a href=\"#\" data-headword=\"עָלַם II\">נעלם</a>). <span class=\"citation\">Ker. IV, 2</span> <span dir=\"rtl\">אם היתה י׳ בנתיים</span> if there was consciousness between the two acts (if he found out his first transgression before committing the second). <span class=\"citation\">Shebu. I, 2</span> <span dir=\"rtl\">י׳ בתחלה וי׳ בסוף והעלם בנתיים</span> original consciousness (knowing that he became unclean) and final consciousness (finding out that he had eaten sacred things in uncleanness) but forgetfulness between. <span class=\"citation\">Hor. 2ᵃ</span>, a. fr. <span dir=\"rtl\">השב מִידִיעָתוֹ</span> he who regrets when he finds out his transgression; a. fr.—Pl. <span dir=\"rtl\">יְדִיעוֹת</span>. Sheb. I, 1 <span dir=\"rtl\">י׳ הטומאה</span> the laws concerning the discovery of having sinned through uncleanness; <span class=\"citation\">ib. II, 1</span>; a. fr.</div>","alt":[]},"14209":{"h":"יְדִיעֲתָא","r":"J00105","html":"<div class=\"sense\">, <i>knowledge</i>. <span class=\"citation\">Targ. Prov. I, 4</span>. <span class=\"citation\">Ib. XXII, 17</span>; a. fr.</div>","alt":[]},"14210":{"h":"יָדַע","r":"J00106","html":"<div class=\"sense\"> [<i>to point out, select, love</i>,] </div><div class=\"sense\"><b>1)</b> <i>to recognize, know; to find out</i>. <span class=\"citation\">Pes. 87ᵇ</span> <span dir=\"rtl\">כיון שי׳ שחטא</span> when he was convinced that he had done wrong. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ואין אתה יוֹדֵעַ אם וכ׳</span> and thou knowest not whether &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">יודע הקב&quot;ה את ישראל וכ׳</span> the Lord knows that Israel cannot endure the cruel persecutions of Rome (v. Rabb. D. S. a. l. note); <span class=\"citation\">Yalk. Hos. 529</span>. <span class=\"citation\">Shebu. 4ᵇ</span>; <span class=\"citation\">ib. 5ᵃ</span> <span dir=\"rtl\">ונעלם מבלל שי׳</span> it says, ‘and it escaped his memory’ (<span class=\"citation\">Lev. V, 3</span>)—this proves that there was a time when he knew (the nature of his act, v. <a href=\"#\" data-headword=\"יְדִיעָה\">יְדִיעָה</a>). <span class=\"citation\">Zeb. 115ᵇ</span> <span dir=\"rtl\">דבר זה … ולא יְדָעוֹ וכ׳</span> this word (<span class=\"citation\">Ex. XXIX, 43</span>) the Lord had said to Moses, but he did not understand it, until the sons of Aaron died. Ib. <span dir=\"rtl\">כיון שי׳ … יְדוּעֵי מקום הן</span> when Aaron learned that his sons were the chosen of the Lord (<span class=\"citation\">Lev. X, 3</span>); a. v. fr.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"יָדוּעַ\">יָדוּעַ</a> a) <i>chosen. </i> Pl. <span dir=\"rtl\">יְדוּעִים</span>, constr. <span dir=\"rtl\">יְדוּעֵי</span>, v. supra.—b) <i>known, special, certain</i>. Sifra Vayikra, Ḥobah, Par. 6, ch. VIII <span dir=\"rtl\">חטא י׳</span> a known (discovered) sin, v. <a href=\"#\" data-headword=\"יְדִיעָה\">יְדִיעָה</a>. <span class=\"citation\">Y. Sot. I, 16ᶜ</span> <span dir=\"rtl\">טומאה יְדוּעָה</span> (not <span dir=\"rtl\">ידוע</span>) an ascertained levitical uncleanness, opp. <a href=\"#\" data-headword=\"סָפַק I\">ספק</a>; a. fr.—בְּיָדוּעַ <i>it is sure</i>. <span class=\"citation\">R. Hash. 20ᵇ</span> <span dir=\"rtl\">בי׳ שנראה וכ׳</span> the moon must have been visible &amp;c. <span class=\"citation\">Succ. 49ᵇ</span> <span dir=\"rtl\">כל אדם … בי׳ שהוא וכ׳</span> a popular man (v. <a href=\"#\" data-headword=\"חֵן\">חֵן</a>) is, you may be sure, a God-fearing man; a. fr.</div><div class=\"sense\"><b>—2)</b>  (euphem.) <i>to have sexual intercourse with</i>. <span class=\"citation\">Yeb. 57ᵃ</span> <span dir=\"rtl\">בלא יְדָעָהּ</span> when he never had connection with her. <span class=\"citation\">Esth. R. to III, 7</span> <span dir=\"rtl\">שלא יְדָעָהּ איש וכ׳</span> whom no man except her husband touched; a. e.</div><div class=\"sense\"><b>Hif. הוֹדִיעַ</b> <div class=\"sense\"><i>to make known, inform</i>. <span class=\"citation\">Gen. R. s. 22</span>, beg. (ref. to <span class=\"citation\">Gen. IV, 1</span>, reading <a href=\"#\" data-headword=\"יְדַע\">יִדַּע</a> for homiletical purposes) <span dir=\"rtl\">ה׳ דרך ארץ לכל</span> he showed to all the way of the land (propagation, v. <a href=\"#\" data-headword=\"דֶּרֶךְ\">דֶּרֶךְ</a>). <span class=\"citation\">Ḥull. V, 3</span> <span dir=\"rtl\">צריך להוֹדִיעַ</span> must inform (the purchaser). <span class=\"citation\">Ab. IV, 22</span> <span dir=\"rtl\">לֵידַע להודיע ולהִוָּורַע</span> to learn, to proclaim and to be made to feel (be thoroughly convinced). <span class=\"citation\">Sabb. 10ᵇ</span> <span dir=\"rtl\">צריך להוֹדִיעוֹ</span> must inform him. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לך והוֹדִיעֵם</span> go and tell them. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">הנותן … צריך לה׳ לאמו</span> he who gives bread to a child must inform his mother; a. fr.</div></div><div class=\"sense\"><b>Hof. הוֹדַע</b> <div class=\"sense\"><i>to be informed, become conscious; to be made known.</i> <span class=\"citation\">Shebu. I, 6</span> <span dir=\"rtl\">ה׳ ולא ה׳</span> whether he became conscious (of his transgression) or not. Sifra Vayikra, Ḥobah, ch. XX, Par. 12 (ref. to <span class=\"citation\">Lev. IV, 23</span>; <span class=\"citation\">28</span>) <span dir=\"rtl\">את ה׳ שלהם</span> when they become known; a. fr.—<span class=\"citation\">B. Bath. 113ᵇ</span> הוֹדְעָה Ms. M. (v. <a href=\"#\" data-headword=\"*אָרַע II\"><span dir=\"rtl\">אָרַע</span> II</a>).</div></div><div class=\"sense\"><b>Nif. נוֹדַע</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"יְדִיעֲתָא\">same</a>. <span class=\"citation\">Hor. III, 3</span>. <span class=\"citation\">Ab. IV, 22</span>, v. supra. <span class=\"citation\">Shebu. 9ᵇ</span> <span dir=\"rtl\">שסופו לִיוָּדַע</span> of which he is likely to be informed. <span class=\"citation\">Ḥull. 9ᵃ</span> <span dir=\"rtl\">עד שיִוָּדַע לך</span>, v. <a href=\"#\" data-headword=\"חֲזָקָה\">חֲזָקָה</a>. <span class=\"citation\">Nidd. IX, 5</span>, v. infra; a. fr.</div></div><div class=\"sense\"><b>Hithpa. הִתְוַודַּע</b> <div class=\"sense\">, <i>Nithpa</i>. <span dir=\"rtl\">נִתְוַודַּע</span> </div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"יְדִיעֲתָא\">same</a>. <span class=\"citation\">Bekh. 25ᵇ</span> <span dir=\"rtl\">עד שיִתְוַורַּע הטומאה</span> (Nidd. l. c. <span dir=\"rtl\">עד שיודע לך וכ׳</span>) until he ascertains the exact place of uncleanness; <span class=\"citation\">Pes. 10ᵃ</span> עד שתִּיוָּדַע לך Ms. M. (v. Rabb. D. S. a. l.). Y. Sabb. III, 6ᵇ <span dir=\"rtl\">נתודע לו וכ׳</span> he found it out after sunset; a. fr.</div><div class=\"sense\"><b>—2)</b>  (v. <span dir=\"rtl\">מוֹדַע</span>) <i>to force one’s self upon the notice of, to pretend friendship for.</i> <span class=\"citation\">Ab. I, 10</span> <span dir=\"rtl\">אל תִּתְוַדַּע לרשות</span> do not make thyself a partisan of the (foreign) government.</div></div>","alt":[]},"14211":{"h":"יְדַע","r":"J00107","html":"<div class=\"sense\"><span class=\"citation\">Targ. Gen. IV, 1</span>; a. fr.—<span class=\"citation\">Ib. XXX, 26</span>; a. fr:—Fut. <a href=\"#\" data-headword=\"יְדַע\">יִדַּע</a>, <a href=\"#\" data-headword=\"נדע\">יִנְדַּע</a> (fr. <a href=\"#\" data-headword=\"נדע\">נדע</a>). <span class=\"citation\">Targ. Ps. XXXIX, 5</span> אִידַּע Ms. (ed. <span dir=\"rtl\">אֵידַע</span>). <span class=\"citation\">Targ. Ex. VIII, 6</span>; a. fr.—<span class=\"citation\">Ber. 33ᵇ</span> אנא לא האי יְדַעְנָע I learned nothing either about this &amp;c. <span class=\"citation\">Snh. 103ᵃ</span> (prov.—of one who derives no lesson from adversity or success) <span dir=\"rtl\">בכיי ליה למר ולא י׳ וכ׳</span> Ms. M. (ed. <span dir=\"rtl\">דלא</span>, v. Rabb. D. S. a. l.) they lament to you and you understand it not, they laugh to you and you understand it not; <span dir=\"rtl\">וי ליה למאן דלא י׳ וכ׳</span> (not <span dir=\"rtl\">למר</span>) woe to him who knows not the difference between good and evil; a. fr.</div><div class=\"sense\"><b>Af. אוֹדַע  הוֹדַע</b> <div class=\"sense\"> as <a href=\"#\" data-headword=\"יָדַע\">preced.</a> <i>Hif.</i> <span class=\"citation\">Targ. Ex. XXXIII, 13</span>. <span class=\"citation\">Targ. Ps. CVI, 8</span> <span dir=\"rtl\">לאוֹדָעָה</span> (Ms. <span dir=\"rtl\">לאַנְדָּ׳</span>, v. supra); a. fr.—<span class=\"citation\">Snh. 11ᵇ</span> <span dir=\"rtl\">מְהוֹדְעִין אנחנא וכ׳</span> we (the Sanhedrin) notify you &amp;c.; Y. ib. I, 18ᵈ top <span dir=\"rtl\">מוֹדַעְנָא</span>; Tosef. ib. II, 6 <span dir=\"rtl\">מְהוֹדַעְנָא</span> (Var. <span dir=\"rtl\">מְהוֹדְעֵי אנחנא</span>). <span class=\"citation\">Sabb. 33ᵇ</span> <span dir=\"rtl\">מאן לוֹדְעֵיה לבר וכ׳</span> (Ms. M. <span dir=\"rtl\">מוֹדְעֵיה</span>) Oh, that some one would inform the son of Yoḥai &amp;c. <span class=\"citation\">Ned. 62ᵃ</span> <span dir=\"rtl\">לאוֹדוּעֵי נפשיה</span> to make one’s self known (as a scholar). <span class=\"citation\">Gen. R. s. 11</span> <span dir=\"rtl\">מנאן את מוֹדַע לי</span> (some ed. <span dir=\"rtl\">מְיַדַּע</span>) how will you prove it to me?; a. fr.</div></div><div class=\"sense\"><b>Pa. יַדַּע</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"יָדַע\">same</a>. <span class=\"citation\">Cant. R. to III, 6</span> <span dir=\"rtl\">לינא מְיַדַּע לדין וכ׳</span> shall I not let him know with whom he is dealing?. <span class=\"citation\">Gen. R. s. 11</span>, v. supra.—<i>Part. pass</i>. <span dir=\"rtl\">מְיַדַּע</span> <i>friend</i>. <span class=\"citation\">Targ. Ps. LXXXVIII, 9</span> מְיַדְּעַי Ms. (ed. <span dir=\"rtl\">מיודעי</span>, hebraism).</div></div><div class=\"sense\"><b>Ithpe. אִתְיְרַע</b> </div><div class=\"sense\"><b>Ithpa. אִתְיַדַּע</b> <div class=\"sense\"><i>to be made known, to make one’s self known</i>. <span class=\"citation\">Targ. O. Gen. XLV, 1</span>. <span class=\"citation\">Ib. XLI, 21</span>; a. fr.—[<span class=\"citation\">Targ. Y. Deut. XXI, 11</span> <span dir=\"rtl\">תתידעון</span>, read: <span dir=\"rtl\">תיתרעון</span>, as in v. 14.]—<span class=\"citation\">Hor. 2ᵃ</span> <span dir=\"rtl\">כי מִתְיַדַּע להו לבי דינא</span> if the court were made aware of it. <span class=\"citation\">Sabb. 71ᵇ</span> <span dir=\"rtl\">א׳ ליה קודם וכ׳</span> he became aware of it before setting the sacrifice aside; a. e.</div></div>","alt":[]},"14212":{"h":"יִדְעוֹנִי","r":"J00108","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>sooth-sayer, charmer</i>. <span class=\"citation\">Snh. 65ᵇ</span>; <span class=\"citation\">Tosef. ib. X, 6</span>, v. <span dir=\"rtl\">יִרּוֹעַ</span>; a. e.</div>","alt":[]},"14213":{"h":"יְדַעְיָה","r":"J00109","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Jedaiah</i>, </div><div class=\"sense\"><b>1)</b>  a priestly division, named after its head. <span class=\"citation\">Taan. 27ᵃ</span>, sq.; <span class=\"citation\">Arakh. 12ᵇ</span>. <span class=\"citation\">Y. Taan. IV, 68ᵈ</span></div><div class=\"sense\"><b>—2)</b>  poetic name of <i>Sepphoris</i> in Galilee whither the division of J. was exiled (v. Y. l. c.). <span class=\"citation\">Koh. R. to VII, 11</span>; <span class=\"citation\">IX, 10</span> <span dir=\"rtl\">בני י׳</span> sons of J. (inhabitants of Sepph.).</div>","alt":[]},"14214":{"h":"יָדְפָת","r":"J00110","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יוֹדְפָת\">יוֹדְפָת</a></div>","alt":[]},"14215":{"h":"יָדְקֶרֶת","r":"J00111","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יוֹדְקֶרֶת\">יוֹדְקֶרֶת</a></div>","alt":[]},"14216":{"h":"יָהּ","r":"J00112","html":"<div class=\"sense\"> (b. h.) <i>Yah</i>, abbreviation of the Tetragrammaton. <span class=\"citation\">Succ. IV, 5</span> (<span class=\"citation\">45ᵃ</span>, missing in Ms. M., v. marginal note to ed.); Tosef. ib. III, 1 <span dir=\"rtl\">לַיָּהּ ולך מזבח</span> unto Yah and unto thee, O altar (do we give praise); <span class=\"citation\">Succ. 45ᵇ</span> <span dir=\"rtl\">ליה אנחנו מודים ולך וכ׳</span> to Yah we offer thanks and thee (altar) we praise. <span class=\"citation\">Ib. V, 4</span> (<span class=\"citation\">51ᵇ</span>) <span dir=\"rtl\">אנו ליה וליה עינינו</span> we are Yah’s and to Y. we lift up your eyes. <span class=\"citation\">Gen. R. s. 79</span>, end, v. <a href=\"#\" data-headword=\"דְּיָקִינְתִּין\">דְיָקִינְתִּין</a>; a. e.</div>","alt":[]},"14217":{"h":"יָהּ II","r":"J00113","html":"<div class=\"sense\"> (interj.) <i>Oh!</i> exclamation of distress. <span class=\"citation\">Gen. R. s. 92</span> (play on <a href=\"#\" data-headword=\"יָהּ\">יה</a>, <span class=\"citation\">Ps. XCIV, 12</span>).</div>","alt":[]},"14218":{"h":"יְהַב","r":"J00114","html":"<div class=\"sense\"><i>to give</i>. <span class=\"citation\">Targ. Gen. III, 12</span>. <span class=\"citation\">Targ. Job III, 19</span> יֵיהַב Ms. (ed. <span dir=\"rtl\">יָהִיב</span>, ed. Wil. <span dir=\"rtl\">יְהִיב</span>); a. fr.—Part. pass. <span dir=\"rtl\">יְהִיב</span>. <span class=\"citation\">Targ. Num. III, 9</span>; a. fr.—Imperative <a href=\"#\" data-headword=\"הַב\">הַב</a>. <span class=\"citation\">Targ. Gen. XXX, 26</span>; a. fr.—Y. Ber. VIII, 11ᵇ bot., a. fr. <span dir=\"rtl\">י׳ ליה מילא</span> gave him assurance of safety. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">יהב את פלגא</span> (read as:) <span class=\"citation\">Y. Naz. V, end, 54ᵇ</span> <span dir=\"rtl\">הב וכ׳</span> give thou half of it. Ib. [read:] <span dir=\"rtl\">אמר דיֵיבִין ליה יַהֲבוּ ליה ואכל</span> he ordered that they give him (to eat); they gave him, and he ate. <span class=\"citation\">Kidd. 9ᵃ</span> <span dir=\"rtl\">אי יהבינא לך וכ׳</span> (read: <span dir=\"rtl\">יַהֲבִינָהּ</span>) if I give it to thee, wilt thou be betrothed unto me? Said she <span dir=\"rtl\">הָבָהּ מֵיהֲבָהּ</span> give it; <span dir=\"rtl\">כל הבה מיהבה וכ׳</span> all such phrases as ‘give it’, mean nothing (do not mean assent to the proposal); a. v. fr.—<span dir=\"rtl\">נסב וי׳</span> (h. = <span dir=\"rtl\">נשא ונתן</span>) <i>to deal</i>. <span class=\"citation\">Cant. R. to III, 6</span>. <span class=\"citation\">Y. Shebi. VII, 37ᶜ</span> top; a. e.—<span class=\"citation\">Lev. R. s. 19</span>, v. infra.—2) <i>to put, place</i>. <span class=\"citation\">Targ. Ex. XVI, 33</span>; a. fr.—<span class=\"citation\">Y. Keth. XII, 35ᵃ</span> bot. <span dir=\"rtl\">אין אנן יַהֲבִין ליה נֵיהֲבֵיה וכ׳</span> if we put him (his coffin) anywhere, we must put him with R. &amp;c.; a. fr.</div><div class=\"sense\"><b>Ithpa. אִתְרַהַב</b> </div><div class=\"sense\"><b>Ithpe. אִתְיְהַב  אִתְיְהֵיב</b> <div class=\"sense\"><i>to be given</i>. <span class=\"citation\">Targ. Is. IX, 5</span>. <span class=\"citation\">Targ. Ex. V, 16</span>; a. fr.—<span class=\"citation\">Kidd. 7ᵃ</span> <span dir=\"rtl\">משום דא׳ למחילה</span> because it (money or money’s worth) may be given away without consideration; v. <a href=\"#\" data-headword=\"נָתַן\">נָתַן</a>.—[<span class=\"citation\">Lev. R. s. 19</span> … <span dir=\"rtl\">תתיהב דיהבת וכ׳</span>, read: <span dir=\"rtl\">תִּתְיַתַּב … דיַתְּבַת</span>, v. <a href=\"#\" data-headword=\"יְתֵב II\"><span dir=\"rtl\">יְתֵב</span> I</a>.]</div></div>","alt":[]},"14219":{"h":"יְהָבָא","r":"J00115","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= b. h. <a href=\"#\" data-headword=\"יְהַב\">יְהָב</a>; <a href=\"#\" data-headword=\"יְהַב\">preced.</a>) [<i>that which is put on</i>,] <i>bundle, load</i> on the back. <span class=\"citation\">R. Hash. 26ᵇ</span>; <span class=\"citation\">Meg. 18ᵃ</span> (as an analogy to <a href=\"#\" data-headword=\"יְהַב\">יהב</a>, <span class=\"citation\">Ps. LV, 23</span>) the Arab said, <span dir=\"rtl\">שקול יְהָבִיךְ וכ׳</span> take off thy bundle and put it on my camel; <span class=\"citation\">Gen. R. s. 79</span>, end <span dir=\"rtl\">תלי הדין י׳ עלי</span> help me to put my load on; <span dir=\"rtl\">שמעון מיניה י׳ משדי</span> from this they learned that <i>y’haba</i> means <i>load</i></div>","alt":[]},"14220":{"h":"יְהָבִית","r":"J00116","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> constr. (<a href=\"#\" data-headword=\"יְהָבָא\">preced.</a> wds.) <i>giving; share, dispensation</i>. <span class=\"citation\">Targ. Koh. V, 10</span> <span dir=\"rtl\">יהבית אגרהא</span> = h. <span dir=\"rtl\">מַתַּן שָׂכַר</span>. <span class=\"citation\">Targ. Ps. XI, 6</span> (h. text <span dir=\"rtl\">מנת</span>).</div>","alt":["יַהֲבַת"]},"14221":{"h":"יַהֲדוּת","r":"J00117","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"יְהוּדִי\">יְהוּדִי</a>) <i>Jewish religion, monotheism</i>. <span class=\"citation\">Esth. R. to III, 7</span> <span dir=\"rtl\">והחזיקו ביַהֲדוּתָן</span> (not <span dir=\"rtl\">ביהודתן</span>) and clung to their creed.</div>","alt":[]},"14222":{"h":"יֵהוּא","r":"J00118","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Jehu</i>, King of Israel. <span class=\"citation\">Meg. 14ᵃ</span>. <span class=\"citation\">Hor. 11ᵇ</span> אף י׳ … לא נמשח וכ׳ Jehu, too, would not have been anointed, but for the opposition to Joram; a. e.</div>","alt":[]},"14223":{"h":"יְהוּד","r":"J00119","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Judaea.</i> <span class=\"citation\">Dan. II, 25</span>; a. e.—<span class=\"citation\">Lam. R. to I, 2</span> <span dir=\"rtl\">י׳ מדינתא</span> the province of J.</div>","alt":[]},"14224":{"h":"יְהוּדָא","r":"J00120","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"יְהוּדָה\">יְהוּדָה</a>.</div>","alt":[]},"14225":{"h":"יְהוּדָאָה","r":"J00121","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <span class=\"citation\">Targ. Esth. V, 13</span>; a. e.—<span class=\"citation\">Y. Shebi. IV, 35ᵇ</span> top, v. <a href=\"#\" data-headword=\"אַרְמַאי\">אַרְמַאי</a>.—Pl. <a href=\"#\" data-headword=\"יְהוּדָאִית\">יְהוּדָאִין</a>, <a href=\"#\" data-headword=\"יְהוּדָאָה\">יְהוּדָאֵי</a>, <a href=\"#\" data-headword=\"יְהוּדָאָה\">יְהוּדָיֵי</a>. <span class=\"citation\">Targ. Esth. IV, 16</span>; a. e.—<span class=\"citation\">Gen. R. s. 63</span> <span dir=\"rtl\">רברבני די׳</span> the leaders of the Jews (of Tiberias); a. fr.—<i>Fem</i>. <a href=\"#\" data-headword=\"יְהוּדָאִית\">יְהוּדָאִיתָא</a>. Targ. II Esth. IV, 1.—<span class=\"citation\">Lam. R. to I, 11</span> <span dir=\"rtl\">חזיין אפיך כי׳</span> (not <span dir=\"rtl\">כיהודיאתא</span>) thou lookest like a Jewess.—V. <a href=\"#\" data-headword=\"*יוּדַאי\">יוּדַאי</a>.</div>","alt":["יְהוּדַאי","יְהוּדַיי"]},"14226":{"h":"*יְהוּדָאִיקִי","r":"J00122","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (Ἰουδαική, sub. συναγωγή or ἀγωρά) <i>Jewish court-house</i>. <span class=\"citation\">Y. Gitt. I, 43ᵇ</span> top <span dir=\"rtl\">במקום י׳</span> in the Jewish meeting place (where Jews have their own jurisdiction); <span dir=\"rtl\">אם אין שם י׳ וכ׳</span> if there is no Jewish courthouse there, it must be done in the synagogue.</div>","alt":[]},"14227":{"h":"יְהוּדָאִית","r":"J00123","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יְהוּדָאָה\">יְהוּדָאָה</a></div>","alt":[]},"14228":{"h":"יְהוּדָה","r":"J00124","html":"<div class=\"sense\"> (b. h.) pr. n. <i>Judah</i>, </div><div class=\"sense\"><b>1)</b>  son of Jacob; <i>tribe of Judah</i>. <span class=\"citation\">Pes. 50ᵃ</span>. <span class=\"citation\">Yoma 12ᵃ</span>, a. e. <span dir=\"rtl\">מחלקו של י׳</span> from the area of Judah.—<span class=\"citation\">Gen. R. s. 85</span>; a. v. fr.</div><div class=\"sense\"><b>—2)</b>  name of several Tannaim; a) R. J. b. B’thera in Babylonia <span class=\"citation\">Ber. 22ᵃ</span>; a. fr.—b) J. b. Tabbai, chief of the Sanhedrin in the days of queen Salome. <span class=\"citation\">Ab. I, 8</span>. <span class=\"citation\">Ḥag. II, 2</span>; a. fr.—c) R. J. the priest. <span class=\"citation\">Eduy. VIII, 3</span>.—d) R. J. b. Baba. Ib. 2. <span class=\"citation\">Sabb. 62ᵇ</span>; a. fr.—e) R. J. b. Ilai, usu. mentioned in the Mishnah as R. J. only. <span class=\"citation\">Ber. 63ᵇ</span>; <span class=\"citation\">Sabb. 33ᵇ</span>. <span class=\"citation\">Men. 103ᵇ</span>; a. v. fr.—f) R. J. b. Tema. <span class=\"citation\">Ab. V, 20</span>. <span class=\"citation\">Erub. 17ᵃ</span>; <span class=\"citation\">Tosef. ib. III</span> (<span class=\"citation\">II), 6</span> (ed. Zuck. <a href=\"#\" data-headword=\"בְּתֵירָא\">בתירה</a>). <span class=\"citation\">Tosef. Gitt. VII</span> (<span class=\"citation\">V), 8</span>; a. fr.; a. others (v. Fr. Darkhé, p. 42; p. 137).—Esp. R. J. han-Nasi I a. II, surnamed Rabbi, v. <a href=\"#\" data-headword=\"רַבִּי\">רַבִּי</a>.</div><div class=\"sense\"><b>—3)</b>  name of several Amoraim, the most renowned of whom is R. J. (b. Ezekiel), a Babylonian. <span class=\"citation\">Keth. 110ᵇ</span> bot.—<span class=\"citation\">Y. Taan. I, 64ᵇ</span> top; a. fr.—V. Fr. M’bo p. 91ᵃ</div><div class=\"sense\"><b>—4)</b> <i>Judaea</i>, the southern province of Palestine. <span class=\"citation\">Keth. I, 5</span> (<span class=\"citation\">12ᵃ</span>); Tosef. ib. I, 4. <span class=\"citation\">Kidd. 6ᵃ</span>; a. v. fr.</div>","alt":[]},"14229":{"h":"יְהוּדִי","r":"J00125","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>Judaean, Jew</i> (mostly in a religious sense), <i>worshipper of one God</i>. <span class=\"citation\">Meg. 12ᵇ</span> <span dir=\"rtl\">קרי ליה י׳ אלמא מיהודה וכ׳</span> he is called Y’hudi (<span class=\"citation\">Esth. II, 5</span>), which would indicate that he belongs to the tribe of Judah, and yet he is called <i>ish y’mini</i> &amp;c.?, v. <a href=\"#\" data-headword=\"אַבְנִימוֹס\">נִימוֹס</a>. Ib. 13ᵃ … <span dir=\"rtl\">ואמאי י׳ … שכל הכופר בע&quot;ז נקרא י׳</span> but why is he designated as Y’hudi? Because he disowned idolatry; for whosoever disowns idolatry, is called a Jew (ref. to <span class=\"citation\">Dan. III, 12</span>); <span class=\"citation\">Esth. R. to II, 5</span> <span dir=\"rtl\">לפי שייחד … נקרא י׳ לומר י׳ יחירי</span> because he professed the unity of God, he was called Y’hudi, meaning to say, a Y’hudi, a believer in One God. <span class=\"citation\">Ex. R. s. 42</span> <span dir=\"rtl\">אתה סבור … או י׳ או צלוב</span> thou thinkest that calling Israel ‘persistent’ is meant for blame; it is meant for their praise, either a Jew or hanged. Meg. l. c. <span dir=\"rtl\">מאכל י׳</span> Jewish food (in accordance with the Jewish dietary laws); a. e.—[<span class=\"citation\">Pes. 113ᵇ</span> <a href=\"#\" data-headword=\"י׳\">י׳</a>, read with Mss. a. early ed. <a href=\"#\" data-headword=\"מִי I\">מי</a>; <span class=\"citation\">Yeb. 63ᵃ</span> <span dir=\"rtl\">כל י׳</span>, read <span dir=\"rtl\">אדם</span>.]—Pl. <a href=\"#\" data-headword=\"יְהוּדִי\">יְהוּדִים</a>. <span class=\"citation\">Esth. R. to III, 9</span>. <span class=\"citation\">Ib. to VIII, 8</span> <span dir=\"rtl\">שונאי הי׳</span> the enemies of the Jews. <span class=\"citation\">Ib. 15</span> מלך … על הי׳ Mardecai was made king of the Jews; a. fr.—<i>Fem</i>. <a href=\"#\" data-headword=\"יְהוּדִיָּה\">יְהוּדִיָּה</a>, <a href=\"#\" data-headword=\"יְהוּדִית\">יְהוּדִית</a>. Meg. l. c. (v. Rabb. D. S. a. l. note 7); <span class=\"citation\">Yalk. Esth. 1052</span> (ref. to <span class=\"citation\">I Chr. IV, 18</span>) <span dir=\"rtl\">אמאי קרי לה י׳</span> why is she (Bithya, the daughter of Pharaoh) called Y’hudiyah (a Jewess)?—<span class=\"citation\">Esth. R. to III</span>, I <span dir=\"rtl\">אם אסתר י׳ היא וכ׳</span> if Esther is a Jewess &amp;c., opp. <a href=\"#\" data-headword=\"גויה\">גויה</a>.—<span class=\"citation\">Keth. VII, 6</span> (<span class=\"citation\">72ᵃ</span>, sq.) <span dir=\"rtl\">דת י׳</span>, v. <a href=\"#\" data-headword=\"דָּת\">דַּת</a>.</div>","alt":[]},"14230":{"h":"יְהוּדִיָּה","r":"J00126","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יְהוּדִי\">preced.</a></div>","alt":[]},"14231":{"h":"*יְהוּדִינְיִי","r":"J00127","html":"<div class=\"sense\">, pr. n. f. <i>Y’hudinyi</i>, sister of R. Judah han-Nasi. <span class=\"citation\">Y. Naz. VII, 56ᵃ</span> top; (<span class=\"citation\">Y. Ber. III, 6ᵃ</span> bot. <a href=\"#\" data-headword=\"נְהוֹרַאי\">נהוראי</a>).</div>","alt":[]},"14232":{"h":"יְהוּדִית","r":"J00128","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יְהוּדִי\">יְהוּדִי</a></div>","alt":[]},"14233":{"h":"יהודת","r":"J00129","html":"<div class=\"sense\">, v. <span dir=\"rtl\">יַהֲרוּת</span></div>","alt":[]},"14234":{"h":"יְהוֹיָדָע","r":"J00130","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Jehoiada</i>, the high-priest. <span class=\"citation\">Num. R. s. 23</span>; a. e.</div>","alt":[]},"14235":{"h":"יְהוֹיָקִים","r":"J00131","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Jehoiakim</i>, king of Judah. <span class=\"citation\">M. Kat. 26ᵃ</span>. <span class=\"citation\">Snh. 103ᵃ</span>, sq. <span class=\"citation\">Lev. R. s. 19</span>; a. fr.</div>","alt":[]},"14236":{"h":"יְהוֹיָרִיב","r":"J00132","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Joiarib</i>, head of a priestly division named after him; (<i>fem</i>.) <i>the division J.</i> <span class=\"citation\">Y. Taan. IV, 68ᵈ</span></div>","alt":[]},"14237":{"h":"יְהוֹנָתָן","r":"J00133","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יוֹנָתָן\">יוֹנָתָן</a></div>","alt":[]},"14238":{"h":"יְהוֹרָם","r":"J00134","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Jehoram, Joram</i>, </div><div class=\"sense\"><b>1)</b>  son of Ahab, king of Israel. <span class=\"citation\">Ber. 10ᵃ</span>. <span class=\"citation\">Ex. R. s. 31</span>; a. e.</div><div class=\"sense\"><b>—2)</b>  son of Joshafat, king of Judah. <span class=\"citation\">Hor. 11ᵇ</span>, v. <a href=\"#\" data-headword=\"יֵהוּא\">יֵהוּא</a></div>","alt":["יוֹרָם"]},"14239":{"h":"יְהוֹשׁוּעַ","r":"J00135","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Joshua</i>, </div><div class=\"sense\"><b>1)</b> <i>J.</i> <i> bin Nun</i>, the successor of Moses. <span class=\"citation\">Ab. I, 1</span>. <span class=\"citation\">Ber. 4ᵃ</span> bot. <span class=\"citation\">B. Kam. 80ᵇ</span>, sq. <span dir=\"rtl\">עשרה … התנה י׳ וכ׳</span> J., on conquering the promised land, laid down ten conditions (regulations) &amp;c.; <span class=\"citation\">Erub. 17ᵃ</span>; a. v. fr.—<span class=\"citation\">Meg. I, 1</span>, a. fr. <span dir=\"rtl\">מומות י׳ בן נון</span> <i>dating from the days of the conquest or before</i></div><div class=\"sense\"><b>—2)</b>  the high-priest of the returning Babylonian exiles. <span class=\"citation\">Snh. 93ᵃ</span>; a. e.—3) name of several Tannaim; a) J.; a. e.</div><div class=\"sense\"><b>—3)</b>  name of several Tannaim; a) J. b. Praḥya. <span class=\"citation\">Ab. I, 6</span>; a. fr.—b) R. J. b. Ḥǎnania, mostly quoted as R. J. only. <span class=\"citation\">Maas. Sh. V, 9</span>. <span class=\"citation\">Erub. IV, 1</span>; <span class=\"citation\">2</span>. <span class=\"citation\">Ḥag. 5ᵇ</span>; a. v. fr.; and others (v. Fr. Darkhé pp. 97; 134; 178; 189).</div><div class=\"sense\"><b>—4)</b>  name of several Amoraim, esp. R. J. b. Levi. <span class=\"citation\">Ber. 3ᵇ</span>; a. v. fr.—R. J. of Sikhnin. Y. ib. IV, 7ᵇ bot.; a. fr.; and others (v. Fr. M’bo p. 91ᵃ, sq.).—(<span dir=\"rtl\">ספר</span>) <a href=\"#\" data-headword=\"י׳\">י׳</a> <i>the Book of Joshua</i>. <span class=\"citation\">B. Bath. 14ᵇ</span>; a. e.</div>","alt":["יְהוֹשֻׁעַ"]},"14240":{"h":"יְהוֹשַׁעְיָא","r":"J00136","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הוֹשַׁעְיָא\">הוֹשַׁעְיָא</a></div>","alt":[]},"14241":{"h":"יְהוֹשָׁפָט","r":"J00137","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Joshafat</i>, king of Judah. <span class=\"citation\">Sabb. 56ᵇ</span>. <span class=\"citation\">Gen. R. s. 33</span>; a. fr.</div>","alt":[]},"14242":{"h":"יהט","r":"J00138","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יְחַט\">יְחַט</a></div>","alt":[]},"14243":{"h":"יְהִי","r":"J00139","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יְחִי\">יְחִי</a></div>","alt":[]},"14244":{"h":"יָהִיר","r":"J00140","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> [<i>glittering</i>,] <i>showy, proud, aristocratic</i>.—Pl. <span dir=\"rtl\">יְהִירִים</span>. <span class=\"citation\">Sot. 47ᵇ</span>, v. <a href=\"#\" data-headword=\"מְשַׁךְ I\">מָשַׁךְ</a>; <span class=\"citation\">Tosef. ib. XIV, 8</span> (ed. Zuck. <span dir=\"rtl\">יְהִרִים</span>).</div>","alt":[]},"14245":{"h":"יָהִיר ²","r":"J00141","html":"<div class=\"sense\"> Targ. <span class=\"citation\">Hab. II, 5</span> <span dir=\"rtl\">י׳ ברשע</span> boastful of his wickedness.—<span class=\"citation\">Ḥull. 111ᵇ</span> top <span dir=\"rtl\">כמה י׳ וכ׳</span> how assuming is this scholar!; cmp. <a href=\"#\" data-headword=\"יוֹהֲרָא\">יוֹהֲרָא</a>.—[<span class=\"citation\">Meg. 29ᵃ</span> <span dir=\"rtl\">האי מאן די׳ וכ׳</span> he who is proud, has a certain blemish (missing in Mss., v. Rabb. D. S. a. l. note).]—<span class=\"citation\">B. Bath. 98ᵃ</span>, v. <a href=\"#\" data-headword=\"יְהַר\">יְהַר</a>.—Pl. <span dir=\"rtl\">יְהִירֵי</span>. <span class=\"citation\">Snh. 98ᵃ</span>, v. <a href=\"#\" data-headword=\"אַמְגֹּושָׁא\">אַמְגּוֹשָׁא</a>.—<i>Fem. </i> pl. <span dir=\"rtl\">יְהִירָן</span>. <span class=\"citation\">Meg. 14ᵇ</span> <span dir=\"rtl\">תרתי נשי י׳ וכ׳</span> there were two proud women (Deborah and Huldah), and their names are invidious.</div>","alt":[]},"14246":{"h":"יְהִירוּתָא","r":"J00142","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָהִיר ²\">preced.</a>) <i>haughtiness</i>. <span class=\"citation\">Meg. 14ᵇ</span> <span dir=\"rtl\">לא יאה י׳ וכ׳</span> pride is unbecoming to women.—V. <a href=\"#\" data-headword=\"יוֹהֲרָא\">יוֹהֲרָא</a>.</div>","alt":[]},"14247":{"h":"יָהִר","r":"J00143","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יָהִיר\">יָהִיר</a></div>","alt":[]},"14248":{"h":"יָהַר","r":"J00144","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"אוֹר\">אור</a>, <a href=\"#\" data-headword=\"נְהַר I\">נהר</a>) <i>to be shining, showy, proud</i>, v. <a href=\"#\" data-headword=\"יָהִיר\">יָהִיר</a>.</div><div class=\"sense\"><b>Hithpa. הִתְיָהֵר</b> <div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"יָהִיר\">יָהִיר</a>) <i>to assume airs, to be boastful</i>. <span class=\"citation\">Pes. 66ᵇ</span> <span dir=\"rtl\">כל המִתְיָהֵר וכ׳</span> whoever is boastful, if he is wise, his wisdom will desert him &amp;c. <span class=\"citation\">B. Bath. 10ᵇ</span> <span dir=\"rtl\">שׁאין עושין אלא להִתְיָהֵר בו</span> they do good only to boast themselves thereof; <span dir=\"rtl\">וכל המתיהר וכ׳</span> and whoever boasts, falls a prey to Gehenna.</div></div>","alt":[]},"14249":{"h":"יְהַר","r":"J00145","html":"<div class=\"sense\"><i>Ithpa.</i> <span dir=\"rtl\">אִיָּהֵר</span>, <i>Ithpe.</i> <span dir=\"rtl\">אִיהַר</span> same. <span class=\"citation\">Sot. 47ᵇ</span> <span dir=\"rtl\">האי מאן דמֵיהַר וכ׳</span> an overbearing man is unpopular even with his own household; <span class=\"citation\">B. Bath. 98ᵃ</span>; Yalk. Hab. 562 <span dir=\"rtl\">דיָהִיר</span>.</div>","alt":[]},"14250":{"h":"יוֹאָב","r":"J00146","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Joab</i>, general of king David. <span class=\"citation\">B. Bath. 116ᵃ</span>. <span class=\"citation\">Snh. 48ᵇ</span>; a. fr.</div>","alt":[]},"14251":{"h":"יוֹאֵל","r":"J00147","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Joel</i>, the prophet. <span class=\"citation\">Taan. 5ᵃ</span>. <span class=\"citation\">Succ. 52ᵃ</span>; a. e.</div>","alt":[]},"14252":{"h":"יואני","r":"J00148","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"וָאנַי\">וָאנַי</a></div>","alt":[]},"14253":{"h":"יוֹאָשׁ","r":"J00149","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Joash</i>, king of Judah. Tosef., <span class=\"citation\">Snh. IV, 11</span>; <span class=\"citation\">Y. Hor. III, 47ᶜ</span> bot.; Bab. <span class=\"citation\">Hor. 11ᵇ</span> <span dir=\"rtl\">ואת י׳ מפני עתלי׳</span> and they anointed J. on account of his opposition to Athalia; cmp. <a href=\"#\" data-headword=\"יֵהוּא\">יֵהוּא</a>. <span class=\"citation\">Snh. 95ᵇ</span>; a. e.</div>","alt":[]},"14254":{"h":"יוּבְדָּנָא","r":"J00150","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יְבַד\">יבד</a>) <i>perdition</i>. <span class=\"citation\">Targ. Prov. XI, 10</span> (Ms. <a href=\"#\" data-headword=\"מוֹבְדָנָא\">מוֹבְדָנָא</a>).</div>","alt":[]},"14255":{"h":"יוֹבֵילָא","r":"J00151","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יוּבְלָא\">יוּבְלָא</a></div>","alt":[]},"14256":{"h":"יוֹבֵל","r":"J00152","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b>  (cmp. <a href=\"#\" data-headword=\"בַּרְחָא\">בַּרְחָא</a>, <a href=\"#\" data-headword=\"נָגוֹדָא\">נָגוֹדָא</a>) <i>leader, bellwether, ram</i>. <span class=\"citation\">Y. Ber. IX, 13ᶜ</span> top (ref. to <span dir=\"rtl\">קרן יובל</span>, <span class=\"citation\">Josh. VI, 5</span>) <span dir=\"rtl\">בערביא … יובלא</span> in Arabia they call a ram <i>yubla;</i> <span class=\"citation\">R. Hash. 26ᵃ</span></div><div class=\"sense\"><b>—2)</b>  (ellipt. for <span dir=\"rtl\">קֶרֶן הַיּ׳</span>) <i>ram’s horn</i>. Mekh. Yithro, Baḥod., s. 3 (ref. to <span class=\"citation\">Ex. XIX, 14</span>) <span dir=\"rtl\">בשימשוך הי׳ את קולו</span> when the horn prolongs its sound; <span class=\"citation\">Yalk. Ex. 281</span>.</div><div class=\"sense\"><b>—3)</b>  c. (ellipt. for <span dir=\"rtl\">שְׁנַת הַיּ׳</span>) <i>Jubilee, Yobel-year, the fiftieth year, the year following the succession of seven Sabbatical years</i> (<span class=\"citation\">Lev. XXV, 8—16</span>; <span class=\"citation\">23—24</span>). <span class=\"citation\">R. Hash. III, 5</span> <span dir=\"rtl\">שוה הי׳ לר&quot;ה</span> the proclamation of the Jubilee resembles that of the New Year as to blowing &amp;c.—<span class=\"citation\">Arakh. 12ᵇ</span> <span dir=\"rtl\">בתחלת הי׳</span> at the beginning of the Jubilee cycle; a. fr.—Pl. <span dir=\"rtl\">יוֹבְלוֹת</span>. R. Hash. l. c. Arakh. l. c. <span dir=\"rtl\">י&quot;ז י׳ מנו וכ</span> the Israelites counted seventeen jubilee cycles from their entrance into the Holy Land to their leaving it.</div>","alt":[]},"14257":{"h":"יוּבְלָא","r":"J00153","html":"<div class=\"sense\"><b>1)</b> <i>ram</i>. <span class=\"citation\">Y. Ber. IX, 13ᶜ</span> top; <span class=\"citation\">R. Hash. 26ᵃ</span>, v. <a href=\"#\" data-headword=\"יוֹבֵל\">preced.</a> (cmp. <span class=\"citation\">Targ. Josh. VI, 4</span>, sq.).</div><div class=\"sense\"><b>—2)</b> <i>Jubilee</i>. <span class=\"citation\">Targ. O. Lev. XXV, 10</span> <a href=\"#\" data-headword=\"יוּבְלָא\">יוֹבֵלָא</a> (ed. Berl. <a href=\"#\" data-headword=\"יוֹבֵילָא\">יוֹבֵילָא</a>, ed. Amst. <a href=\"#\" data-headword=\"יוּבְלָא\">יוֹבָלָא</a>; Y. <a href=\"#\" data-headword=\"יוּבְלָא\">יוּבָלָא</a>); a. fr.—Pl. <span dir=\"rtl\">יוּבְלֵי</span>. <span class=\"citation\">Arakh. 12ᵇ</span> <span dir=\"rtl\">תמניא י׳</span> eight jubilee cycles; a. e.</div>","alt":[]},"14258":{"h":"יוֹבֶלֶת","r":"J00154","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יַבֶּלֶת\">יַבֶּלֶת</a></div>","alt":[]},"14259":{"h":"יוּבְּקָא","r":"J00155","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Yubka</i>, name of a brook, a valley and a border place. <span class=\"citation\">Targ. O. Gen. XXXII, 23</span> ed. Berl. (oth. ed. a. Y. <span dir=\"rtl\">יוּבְ׳</span>). <span class=\"citation\">Targ. O. Deut. III, 16</span> <span dir=\"rtl\">יוּבְ׳ נחלא</span> ed. Berl. (oth. ed. a. Y. <span dir=\"rtl\">יוּבְ׳ דנ׳</span>); a. e.—Y. Shebi. VI, 36ᶜ <span dir=\"rtl\">חשבון ויבקא</span>; <span class=\"citation\">Sifré Deut. 51</span> <span dir=\"rtl\">משקא וחשבון</span>; <span class=\"citation\">Yalk. ib. 874</span> <span dir=\"rtl\">יוסקא וח׳</span> (corr. acc.); <span class=\"citation\">Tosef. Shebi. IV, 11</span> <a href=\"#\" data-headword=\"יוקפא\">יוקפא</a> ed. Zuck. (Var. <a href=\"#\" data-headword=\"יַבְּקָא\">יבקא</a>).</div>","alt":[]},"14260":{"h":"יוֹבֶשׁ","r":"J00156","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָבֵשׁ I\">יְבַשׁ</a>) <i>dry matter, dry condition</i>. <span class=\"citation\">Targ. II Chr. IV, 5</span> <a href=\"#\" data-headword=\"בִּרְיְתָא\">בי׳</a> in dry measure. <span class=\"citation\">Targ. Jud. VI, 37</span>; <span class=\"citation\">39</span>, sq.</div>","alt":["יוּבְשָׁא"]},"14261":{"h":"יוֹבְשָׁנִי","r":"J00157","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"יוֹבֶשׁ\">preced.</a>) <i>rainless land</i>. <span class=\"citation\">Taan. 10ᵃ</span>, v. <a href=\"#\" data-headword=\"טוֹבְעָנִי I\"><span dir=\"rtl\">טוֹבְעָנִי</span> I</a>.</div>","alt":[]},"14262":{"h":"יו\"ד","r":"J00158","html":"<div class=\"sense\"><i>Yod</i>, the tenth letter of the Alphabet. <span class=\"citation\">Y. Shebi. I, 33ᵇ</span> bot.; <span class=\"citation\">Sabb. 103ᵇ</span>; <span class=\"citation\">Taan. 2ᵇ</span> <span dir=\"rtl\">הרי מ&quot;ם יו&quot;ד מ&quot;ם הרי מים</span> the Mem of <span dir=\"rtl\">ונסכיהם̇</span> (<span class=\"citation\">Num. XXIX, 19</span>), the Yod of <span dir=\"rtl\">ונסכיֹה</span> (ib. 31) , and the Mem of <span dir=\"rtl\">כמשפטם̇</span> (ib. 33) intimate <i>water</i> as libation. <span class=\"citation\">Gen. R. s. 47</span>, beg.; <span class=\"citation\">Num. R. s. 18</span>. <span class=\"citation\">Y. Snh. II, 20ᶜ</span> bot., a. e. <span dir=\"rtl\">יו&quot;ד שבירבה וכ׳</span> the Yod in <i>yarbeh</i> (<span class=\"citation\">Deut. XVII, 16</span>, sq.) denounced him (Solomon); a. e.—Pl. <span dir=\"rtl\">יוּדִים</span>, <span dir=\"rtl\">יוּדִין</span>. <span class=\"citation\">Sifré Deut. 36</span> <span dir=\"rtl\">לווים י׳ ולי׳ וכ׳</span> if he made the Vav like Yod or vice versa; Sabb. l. c.</div>","alt":[]},"14263":{"h":"יוּד","r":"J00159","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Yud</i>. <span class=\"citation\">Taan. 22ᵇ</span> <span dir=\"rtl\">רמי בר רב י׳</span> ed. (Ms. M. <span dir=\"rtl\">רב יהודה אמר רב</span>; v. Rabb. D. S. a. l. notes 1, 2). <span class=\"citation\">Ib. 9ᵃ</span> רמי בר רב י׳ Ms. M. 2 (v. Rabb. D. S. a. l. note 60); <span class=\"citation\">Sabb. 32ᵇ</span> Ms. M.; (<span class=\"citation\">Macc. 23ᵇ</span> <span dir=\"rtl\">רמי בר רב</span> only); <span class=\"citation\">Zeb. 55ᵇ</span> Ms. M. (ed. <a href=\"#\" data-headword=\"יוּדָא\">יודא</a>).</div>","alt":[]},"14264":{"h":"יוּדָא","r":"J00160","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Yuda</i>, an Amora. <span class=\"citation\">Y. Ned. VII, beg. 40ᵇ</span>. <span class=\"citation\">Zeb. 55ᵇ</span>, v. <a href=\"#\" data-headword=\"יוּד\">preced.</a></div>","alt":[]},"14265":{"h":"*יוּדַאי","r":"J00161","html":"<div class=\"sense\"> m. = <a href=\"#\" data-headword=\"יְהוּדָאָה\">יְהוּדָאָה</a>. <span class=\"citation\">Y. Ab. Zar. II, 41ᵃ</span> top <span dir=\"rtl\">והוה י׳ אזיל וכ׳</span></div>","alt":[]},"14266":{"h":"יודאפא","r":"J00162","html":"<div class=\"sense\">, read: <a href=\"#\" data-headword=\"יוֹדְפָאָה\">יוֹדְפָאָה</a>.</div>","alt":[]},"14267":{"h":"יוּדָה","r":"J00163","html":"<div class=\"sense\"> <span class=\"citation\">Y. Ber. III, 6ᵃ</span> bot.; a. fr.—V. Frank. M’bo, p. 92ᵃ, sq. V. <a href=\"#\" data-headword=\"יוּדָן\">יוּדָן</a>.</div>","alt":["יְהוּדָה"]},"14268":{"h":"יודייה","r":"J00164","html":"<div class=\"sense\">, <span class=\"citation\">Y. Succ. IV, 54ᶜ</span> top, read: <a href=\"#\" data-headword=\"וַדַּאי\">וַודָּיָיה</a>, v. <a href=\"#\" data-headword=\"וַדַּאי\">וַדַּאי</a></div>","alt":[]},"14269":{"h":"יודיקי","r":"J00165","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יודקו\">יודקי</a></div>","alt":[]},"14270":{"h":"יוּדָן","r":"J00166","html":"<div class=\"sense\"> q. v. <span class=\"citation\">Y. Ber. III, 6ᵃ</span> bot., a. fr. <span dir=\"rtl\">ר׳ י׳ נשייא</span> R. J. (II), the Nasi; (V. Fr. M’bo p. 92ᵃ, sq.).—<span class=\"citation\">Pesik. R. s. 14</span> <span dir=\"rtl\">ר׳ י׳</span>.—<span class=\"citation\">Gen. R. s. 10</span> <span dir=\"rtl\">אבא י׳</span> (abbr. <a href=\"#\" data-headword=\"אַבְדָּן\">אַבְדָּן</a> q. v.).—<span class=\"citation\">Y. Ber. II, 5ᵃ</span> top. Ib. IX, 14ᵃ top; a. v. fr.</div>","alt":["יְהוּדָה"]},"14271":{"h":"יוּדֵן","r":"J00167","html":"<div class=\"sense\"> (= <span dir=\"rtl\">הוּ דֵן</span>) <i>is this</i>. Targ. II Esth. VII, 5 (h. text <span dir=\"rtl\">הוא זה</span>, <span dir=\"rtl\">זה הוא</span>).</div>","alt":[]},"14272":{"h":"יוּדָנָה","r":"J00168","html":"<p class=\"morphology\">pr. n. f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"יוּדָן\">יוּדָן</a>) <i>Yudanah, Yudani</i>. <span class=\"citation\">Y. Ab. Zar. II, 41ᵃ</span> <span dir=\"rtl\">בר יודנה</span>; <span class=\"citation\">Y. Ter. VIII, 45ᶜ</span> bot. <span dir=\"rtl\">בר … י</span> Bar. Y.; cmp. <a href=\"#\" data-headword=\"*יְהוּדִינְיִי\">יְהוּדִינְיִי</a>.</div>","alt":["יוּדָנִי"]},"14273":{"h":"יוֹדְפָאָה","r":"J00169","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יוֹדְפָת\">next w.</a></div>","alt":[]},"14274":{"h":"יוֹדְפָת","r":"J00170","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Yodfath, Yotapata</i>, a fortress in Galilee (v. Jos. B. J. III, 7, 6, sq.; cmp. <span dir=\"rtl\">יָטְבָה</span> <span class=\"citation\">II Kings XXI, 19</span>). <span class=\"citation\">Arakh. IX, 6</span> <span dir=\"rtl\">י׳ הישנה</span> the old fort of J.—<span class=\"citation\">Tosef. Nidd. III, 11</span> <span dir=\"rtl\">בקעת יטבת</span> the valley of J.; <span class=\"citation\">Nidd. 20ᵃ</span> <span dir=\"rtl\">יודפ׳</span>.—Denom. <a href=\"#\" data-headword=\"יוֹדְפָאָה\">יוֹדְפָאָה</a> m. <i>of J</i>. <span class=\"citation\">Zeb. 110ᵇ</span>; <span class=\"citation\">Meïl. 13ᵇ</span> <span dir=\"rtl\">יודאפה</span> (corr. acc.); Y. Succ. IV, 54ᶜ bot. <a href=\"#\" data-headword=\"יוֹתְפָאָה\">יוֹתְפָיָיה</a>.</div>","alt":["יָדְפַת","יָטְבַת"]},"14275":{"h":"יודקו","r":"J00171","html":"<div class=\"sense\">, read: <span dir=\"rtl\">יוּדִיקִין</span> m. pl. (judices) <i>judges;</i> א׳ י׳ <i>chief justice</i>, v. <a href=\"#\" data-headword=\"אַרְכִי III\"><span dir=\"rtl\">אַרְכִי</span> III</a>. <span class=\"citation\">Gen. R. s. 50</span>, beg. Ar.—[Mus. in Ar. ed. Koh. s. v. <a href=\"#\" data-headword=\"ארכידיקי\">ארכידיקי</a>, Var. <span dir=\"rtl\">אַרְכִיקְרִיטֵיס</span> (ἀρχικρίτης); ed. <span dir=\"rtl\">א׳ הדיינים</span>.]</div>","alt":["יודקי","יודיקי","ארכי י׳"]},"14276":{"h":"יוֹדְקֶרֶת","r":"J00172","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Yodkereth</i> (a disguised translation of <i>Diospolis = Lydda</i>). <span class=\"citation\">Taan. 23ᵇ</span>, sq. <span dir=\"rtl\">ר׳ יוסי דמן יודק׳</span> Ar. (ed. <a href=\"#\" data-headword=\"יוֹקֶרֶת\">יוֹקֶרֶת</a>, Ms. M. <a href=\"#\" data-headword=\"יוֹקֶרֶת\">יוקרת</a>, Ms. M. 2 <a href=\"#\" data-headword=\"יָדְקֶרֶת\">ידקרת</a>) R. J. of Yodkereth (cmp. <span dir=\"rtl\">ר׳ יוסי דרומייא</span>, Fr. M’bo, p. 5ᵇ, sq.).—*<span class=\"citation\">Kidd. 16ᵇ</span> י׳ קא חזינא הכא Ar. (ed. <span dir=\"rtl\">יו&quot;ד קרת</span>) I see here the influence of the Yodk. school; (for other explan., v. Rashi a. l., a. Koh. Ar. Compl. s. v. <a href=\"#\" data-headword=\"יָדְקֶרֶת\">ידקרת</a>).</div>","alt":["יָדְ׳"]},"14277":{"h":"יוֹהֲרָא","r":"J00173","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יְהַר\">יְהַר</a>) </div><div class=\"sense\"><b>1)</b> <i>a sparkling gem</i>. <span class=\"citation\">Targ. Y. Gen. VI, 16</span>.—Pl. <span dir=\"rtl\">יוֹהֲרִין</span>. <span class=\"citation\">Targ. Esth. I, 4</span>; <span class=\"citation\">Targ. Lam. IV, 7</span> (Var. <a href=\"#\" data-headword=\"זָהוֹר\">זְהוֹרִין</a>); <span class=\"citation\">Targ. Cant. VII, 2</span> (ed. Lag. <span dir=\"rtl\">גּוּהֲרִין</span>.).</div><div class=\"sense\"><b>—2)</b>  (= <a href=\"#\" data-headword=\"יְהִירוּתָא\">יְהִירוּתָא</a>) <i>haughtiness, assumption</i>. <span class=\"citation\">Ber. 17ᵇ</span> <span dir=\"rtl\">מחזי כי׳</span> it looks like an assumption (to appear more observant than others). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">חייש לי׳</span> cares for the appearance of assumption (and therefore forbids); <span class=\"citation\">Pes. 55ᵃ</span>. <span class=\"citation\">Succ. 26ᵇ</span> <span dir=\"rtl\">לית ביה משום י׳</span> there is no appearance of presumption to be apprehended in doing so.</div>","alt":[]},"14278":{"h":"יָוָון","r":"J00174","html":"<div class=\"sense\"><b>,</b> v. <a href=\"#\" data-headword=\"יָוָן\">יָוָן</a>, <span dir=\"rtl\">יְוָנ׳</span>.</div>","alt":["יְוָונָאָה","יְוָונִי"]},"14279":{"h":"יוֹזִיף","r":"J00175","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"*יָזַף\">יְזַף</a>) <i>debtor</i>. <span class=\"citation\">Targ. Prov. XXII, 7</span>; v. <a href=\"#\" data-headword=\"יַזְפָא\">יַזְפָא</a>.</div>","alt":[]},"14280":{"h":"יוֹחַאי","r":"J00176","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Yoḥai</i>, esp. known Y. the father of R. Simeon. <span class=\"citation\">Sabb. 33ᵇ</span>; a. v. fr.</div>","alt":["יוֹחַי"]},"14281":{"h":"יוֹחָנָא I","r":"J00177","html":"<div class=\"sense\"><i>Yoḥana</i>. </div><div class=\"sense\"><b>1)</b>  pr. n. m. <span class=\"citation\">Ḥull. 133ᵃ</span> <a href=\"#\" data-headword=\"יָנוּקָא II\">מר י׳</a>; <span class=\"citation\">Ab. Zar. 16ᵇ</span> <span dir=\"rtl\">מר יוֹחָנִי</span>.</div><div class=\"sense\"><b>—2)</b>  pr. n. pl. <span class=\"citation\">Gen. R. s. 40</span>, beg.; ib. s. 25, end; ib. s. 64, beg.; Midr. Sam. ch. XXVIII, a. e. (prov.) <span dir=\"rtl\">שילה חטייא וי׳ משתלמא</span> (not <a href=\"#\" data-headword=\"חִטָּא I\">חטא</a>) Shilo sinned a. Y. is punished (i.e. the later generation pays for the sins of ancestors).—V. <a href=\"#\" data-headword=\"יוֹחָנִי\">יוֹחָנִי</a>.</div>","alt":["יוֹחָנָה"]},"14282":{"h":"יוֹחָנָא II","r":"J00178","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>Yoḥana</i>, name of a species of <i>locusts</i>. Sifra Sh’mini, Par. 3, ch. V; <span class=\"citation\">Ḥull. 65ᵃ</span> <span dir=\"rtl\">י׳ ירושלמית</span> the Jerusalem Y.</div>","alt":[]},"14283":{"h":"יוֹחָנִי","r":"J00179","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Yoḥani</i>; </div><div class=\"sense\"><b>1)</b>  pr. n. m. <span class=\"citation\">Ab. Zar. 16ᵇ</span>, v. <a href=\"#\" data-headword=\"יוֹחָנָא I\"><span dir=\"rtl\">יוֹחָנָא</span> I</a>.—<span class=\"citation\">Men. 85ᵃ</span> <span dir=\"rtl\">י׳ וממרא</span> (some ed. <a href=\"#\" data-headword=\"יוֹחָנָא I\">יוחנא</a>) Y. and Mamre (two Egyptian sorcerers); v. <a href=\"#\" data-headword=\"יַנִּיס\">יַנִּיס</a>—<span class=\"citation\">Esth. R. to I, 4</span> <span dir=\"rtl\">בר י׳</span> (some ed. <span dir=\"rtl\">יוחני׳</span>) Bar-Y.</div><div class=\"sense\"><b>—2)</b>  pr. n. f.—<span class=\"citation\">Zeb. 62ᵇ</span> (a fictitious name).—<span class=\"citation\">Sot. 22ᵃ</span> <span dir=\"rtl\">י׳ בת רטיבי</span> (a hypocritical sorceress, v. Rashi a. l.).</div>","alt":[]},"14284":{"h":"יוֹחָנָן","r":"J00180","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Johanan, John;</i> </div><div class=\"sense\"><b>1)</b>  J. ben Kareah, a follower of the Babylonian governor of Judaea (<span class=\"citation\">Jer. XL, 8</span> sq.). Esth. R. introd., beg.; <span class=\"citation\">Y. Succ. V, 55ᵇ</span> top; Mekh. B’shall., Vayhi, s. 2.</div><div class=\"sense\"><b>—2)</b>  John Hyrcan, the Asmonean highpriest and king <span dir=\"rtl\">(י׳ כהן גדול</span>). Maash. Sh. V, 15; <span class=\"citation\">Sot. IX, 10</span>; a. fr.</div><div class=\"sense\"><b>—3)</b>  name of several Tannaim, esp. a) Rabban J. b. Zaccai. <span class=\"citation\">Ab. II, 8</span>. <span class=\"citation\">R. Hash. IV, 3</span>. Mekh. Yithro, Baḥod., s. 11. <span class=\"citation\">Sot. IX, 9</span>; <span class=\"citation\">15</span>. <span class=\"citation\">Gitt. 56ᵃ</span>, sq.; a. v. fr.—b) R. J. b. Bag-Bag (usu. only Ben-Bag-Bag). <span class=\"citation\">Y. Keth. V, 29ᵈ</span> bot. <span class=\"citation\">B. Kam. 27ᵇ</span>; a. fr.—c) R. J. b. B’roka. <span class=\"citation\">B. Kam. X, 2</span>; a. fr.—d) R. J. b. Godgada. <span class=\"citation\">Eduy. VII, 9</span>; a. e.—e) R. J. has-Sandlar. <span class=\"citation\">Ab. IV, 11</span>; a. fr.—f) R. J. b. Nuri. <span class=\"citation\">Erub. IV, 5</span>; <span class=\"citation\">Gitt. 67ᵃ</span>; a. fr.; </div><div class=\"sense\"><b>4)</b>  name of several Amoraim, esp. R. J. han-Nappaḥ or Bar Nafḥa (the Smith). <span class=\"citation\">Y. R. Hash. II, 58ᵇ</span> top. <span class=\"citation\">Ḥull. 137ᵇ</span>; a. v. fr. (as R. J. only); v. Fr. M’bo p. 95ᵇ, sq.—V. <a href=\"#\" data-headword=\"חִיקוֹק\">חִיקוֹק</a>.</div>","alt":[]},"14285":{"h":"יוֹחָס","r":"J00181","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <span dir=\"rtl\">יוֹחֲסִים</span>, (<a href=\"#\" data-headword=\"יָחַס\">יָחַס</a>) <span dir=\"rtl\">יוֹחֲסִין</span> <i>genealogical records, traced genealogy</i>. <span class=\"citation\">Kidd. IV, 1</span> <span dir=\"rtl\">עשרה י׳ עלו וכ׳</span> ten classes of Jews of traced genealogy went up from Babylonian captivity. <span class=\"citation\">Y. Taan. IV, 68ᵃ</span> bot.; <span class=\"citation\">Gen. R. s. 98</span> <span dir=\"rtl\">מגילת י׳ מצאו וכ׳</span> a roll containing genealogical records was found &amp;c. <span class=\"citation\">Yeb. IV, 13</span>; <span class=\"citation\">ib. 49ᵇ</span>.—<span class=\"citation\">Y. Succ. V, end, 55ᵈ</span>; <span class=\"citation\">Cant. R. to V, 5</span> <a href=\"#\" data-headword=\"שַׁלְשֶׁלֶת\">שלשלת</a> (<a href=\"#\" data-headword=\"ה\">ה</a>)<a href=\"#\" data-headword=\"י׳\">י׳</a> the genealogical chain; <span class=\"citation\">Gen. R. s. 82</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בכורת י׳</span> the genealogical privileges of the first-born, opp. to <span dir=\"rtl\">בכורת ממון</span> the material privileges (double-share). Ruth R., end <span dir=\"rtl\">מה אתם יש לכם י׳</span> what records have you to show?—<span class=\"citation\">Pes. 62ᵇ</span> <span dir=\"rtl\">מיום שנגנז ספר י׳</span> since the Book of Genealogy (a commentary to Chronicles) was suppressed (or disappeared, in the Roman days). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ניתני לי מר ספר י׳</span> teach me the book of records (Chronicles); a. e.—V. <a href=\"#\" data-headword=\"יִחוּס\">יִחוּס</a>.</div>","alt":[]},"14286":{"h":"יוֹכֶבֶד","r":"J00182","html":"<div class=\"sense\"> (b. h.) pr. n. f. <i>Jochebed</i>, the mother of Moses and Aaron. <span class=\"citation\">Sot. 12ᵃ</span>; <span class=\"citation\">B. Bath. 120ᵃ</span>; <span class=\"citation\">Ex. R. s. 1</span>; <span class=\"citation\">Gen. R. s. 94</span>; a. fr.</div>","alt":[]},"14287":{"h":"יוּכְלָא","r":"J00183","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , <i>power, ability</i>. <span class=\"citation\">Targ. Y. Gen. IV, 13</span>. <span class=\"citation\">Targ. Num. XIV, 16</span>; a. e.; v. <a href=\"#\" data-headword=\"יְכוּלְתָּא\">יְכוּלְתָּא</a>.</div>","alt":[]},"14288":{"h":"יוֹכָנִי","r":"J00184","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>Bar-Yokhani</i>, name of a fabulous bird. <span class=\"citation\">Bekh. 57ᵇ</span>. <span class=\"citation\">Yoma 80ᵃ</span> (Ms. M. 2 <span dir=\"rtl\">בריכני</span>, v. Rabb. D. S. a. l. note 9); <span class=\"citation\">Succ. 5ᵇ</span> top.—[Koh. Ar. Compl. s. v. <span dir=\"rtl\">בר</span> (vol. II, p. 176) refers to <i>Varaghna</i> (Bactrian) <i>ostrich</i>.]</div>","alt":["בַּר י׳"]},"14289":{"h":"יָוַל","r":"J00185","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יָבַל I\">יָבַל</a> Hif.</div>","alt":[]},"14290":{"h":"יוּלָּד","r":"J00186","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יָלַד\">יָלַד</a></div>","alt":[]},"14291":{"h":"יוֹלֵד","r":"J00187","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> <span dir=\"rtl\">יוֹלְדִים</span> (b. h.; <i>parents</i>. <span class=\"citation\">Keth. VII, 6</span> <span dir=\"rtl\">המקללת יוֹלְדָיו בפניו</span> she who curses his (her husband’s) parents in his presence; quot. <span class=\"citation\">ib. 72ᵇ</span> <span dir=\"rtl\">יוֹלֵידָיו</span> (an emphatic form), and interpreted <span dir=\"rtl\">במקללת יוֹלֵידָיו בפני מוֹלֵידָיו</span> (v. <a href=\"#\" data-headword=\"מוֹלֵד\">מוֹלֵד</a>) also when she curses his parents before any one of his begotten; Y. ib. VII, 31ᵇ bot. <span dir=\"rtl\">וולדיו בפני יולדיו</span>, v. <a href=\"#\" data-headword=\"וָלָד\">וָלָד</a>.</div>","alt":[]},"14292":{"h":"יוֹלֵדָה","r":"J00188","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"יוֹלֵד\">preced.</a>) <i>a woman in confinement; a mother.</i> <span class=\"citation\">Ab. II, 8</span> <span dir=\"rtl\">אשרי יוֹלַדְתּוֹ</span> blessed is his mother.—Pl. <span dir=\"rtl\">יוֹלְדוֹת</span>. <span class=\"citation\">Sabb. 32ᵃ</span> <span dir=\"rtl\">נשים מתות י׳</span> women die in confinement (v. <a href=\"#\" data-headword=\"לֵידָה\">לֵידָה</a>); Y. ib. II, 5ᵇ top; v. <span dir=\"rtl\">יַלְדָּה</span>.—<span class=\"citation\">Sot. I, 5</span> <span dir=\"rtl\">את הי׳</span> (not <a href=\"#\" data-headword=\"יוֹלֵדָה\">יולדת</a>) the women appearing in the Temple after confinement.</div>","alt":["יוֹלֶדֶת"]},"14293":{"h":"יוֹלַדְתָּא","r":"J00189","html":"<div class=\"sense\">, <i>midwife</i>, v. <a href=\"#\" data-headword=\"יְלַדְתָּא\">יְלַדְתָּא</a>.</div>","alt":[]},"14294":{"h":"יוֹלֵיד","r":"J00190","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יוֹלֵד\">יוֹלֵד</a></div>","alt":[]},"14295":{"h":"*יוֹלִימְנָא","r":"J00191","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Yolimna</i>, an Amora. <span class=\"citation\">Pesik. R. s. 7</span>, beg.</div>","alt":[]},"14296":{"h":"יולין","r":"J00192","html":"<div class=\"sense\">, <span class=\"citation\">Pes. 39ᵃ</span>, <span dir=\"rtl\">חזרת י׳</span>, v. <a href=\"#\" data-headword=\"*חַוְורוּלִין\">חַוְורוּלִין</a></div>","alt":[]},"14297":{"h":"יוּלְפָנָא","r":"J00193","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יְלֵף\">יְלַף</a>) = <a href=\"#\" data-headword=\"אוּלְפָן\">אוּלְפָנָא</a>, <i>instruction</i>. <span class=\"citation\">Targ. Prov. IV, 2</span>.</div>","alt":[]},"14298":{"h":"יוֹם","r":"J00194","html":"<div class=\"sense\"> (b. h.) <i>light, day</i> (opp. night); (<i>astronomical</i>) <i>day;</i> trnsf. <i>day of life; time</i>. <span class=\"citation\">Gen. R. s. 6</span> <span dir=\"rtl\">הי׳ והגשמים וכ׳</span> the noise of the moving light (<span class=\"citation\">Yoma 20ᵇ</span> <span dir=\"rtl\">קול גלגל חמה</span>) and the rains &amp;c.; Midr. Sam. ch. IX. Gen. R. l. c. (ref. to <span class=\"citation\">Mal. III, 19</span>) <span dir=\"rtl\">י׳ שהוא מלהט וכ׳</span> it is the day light which will glow the wicked (cmp. <a href=\"#\" data-headword=\"נַרְתֵּק\">נַרְתֵּק</a>). <span class=\"citation\">M. Kat. 25ᵇ</span> (ref. to <span class=\"citation\">Am. VIII, 9</span>) <span dir=\"rtl\">זה יוֹמוֹ של וכ׳</span> that means the day of life of Josiah (who was slain in the bloom of manhood). <span class=\"citation\">Gen. R. s. 3</span> (ref. to <span class=\"citation\">ib. I, 5</span>) <span dir=\"rtl\">י׳ אחד … ואיזה זה יוה&quot;כ</span> ‘one (distinguished) day’ … that is the Day of Atonement. <span class=\"citation\">Ḥull. V, 5</span> (<span class=\"citation\">83ᵃ</span>) <span dir=\"rtl\">הי׳ הולך וכ׳</span> the day follows the night, i.e. the beginning of the night is the beginning of the new day. <span class=\"citation\">Taan. 29ᵃ</span>, v. <a href=\"#\" data-headword=\"זַכַּאי\">זַכַּאי</a>; a. v. fr.—<span dir=\"rtl\">י׳ טוב</span> (abbr. <span dir=\"rtl\">יו&quot;ט</span>) <i>Holy Day; festival</i>. <span class=\"citation\">R. Hash. IV, 1</span>; a. fr.—<span class=\"citation\">Yoma VII, 4</span> <span dir=\"rtl\">ויו&quot;ט היה וכ׳</span> and the Highpriest gave a festival to his friends; a. fr.—<i>Yom Tob</i>, name of a treatise of the Tosefta (v. <a href=\"#\" data-headword=\"בֵּיצָה\">בֵּיצָה</a>).—<span dir=\"rtl\">י׳ הכפורים</span> (abbr. <span dir=\"rtl\">יו&quot;כ</span>, <span dir=\"rtl\">יה&quot;כ</span>) Day of Atonement. <span class=\"citation\">Yoma I, 1</span>; a. v. fr.—בֶּן יוֹמוֹ <i>of the same day, not quite one day old, used on the same day</i>. <span class=\"citation\">Sabb. 151ᵇ</span>. <span class=\"citation\">B. Kam. 65ᵇ</span>; a. fr.—Tanḥ. Kor. 3; ed. Bub. 6; <span class=\"citation\">Num. R. s. 18</span> <span dir=\"rtl\">תינוקות בְּנֵי יוֹמָן</span> (not <a href=\"#\" data-headword=\"בֵּן\">בן</a>) children just born; a. fr.—<i>Du.</i> <span dir=\"rtl\">יוֹמַיִם</span>. Mekh. Mishp., N’zikin, s. 7; <span class=\"citation\">B. Kam. 90ᵃ</span> <span dir=\"rtl\">ישנו בדין יום או י׳</span> comes under the law of ‘one or two days’ (<span class=\"citation\">Ex. XXI, 21</span>) ; <span class=\"citation\">B. Bath. 50ᵃ</span>.—Mekh. l. c. <span dir=\"rtl\">יום שהוא כי׳ וי׳ שהוא כיום</span> a time which counts like two days, and two days which count like a day, which is twenty four hours (from the time of the accident, including part of this and part of the next day).—<span class=\"citation\">Snh. 65ᵇ</span> <span dir=\"rtl\">מה יום מיומים</span> (Ms. M. a. Rashi <span dir=\"rtl\">מה היום וכ׳</span>) what difference is there between to-day (Sabbath) and the next day?; <span class=\"citation\">Gen. R. s. 11</span>; <span class=\"citation\">Yalk. Deut. 918</span>; <span class=\"citation\">Yalk. Lev. 617</span>.—Pl. <a href=\"#\" data-headword=\"יָמִים\">יָמִים</a>; constr. <a href=\"#\" data-headword=\"יְמֵי\">יְמֵי</a>, <a href=\"#\" data-headword=\"יְמוֹת\">יְמוֹת</a>. <span class=\"citation\">Erub. III, 6</span> <span dir=\"rtl\">לשני י׳</span> for both days. <span class=\"citation\">Zeb. V, 7</span> <span dir=\"rtl\">לשני י׳</span> during two days and one night. <span class=\"citation\">Pes. 52ᵃ</span>, a. fr. <span dir=\"rtl\">שני י׳ טובים של גליות</span>, v. <a href=\"#\" data-headword=\"גָּלוּת\">גָּלוּת</a>. <span class=\"citation\">Taan. IV, 8</span> לא היו י׳ ט׳ וכ׳ Israel had no days as merry as &amp;c.; a. fr.—<span class=\"citation\">Ab. I, 17</span>, a. fr. <span dir=\"rtl\">כל יָמַי</span> all my lifetime.—Esp. <a href=\"#\" data-headword=\"יְמוֹת\">יְמוֹת</a> <i>season, period of</i>. <span dir=\"rtl\">י׳ הגשמים</span>, v. <a href=\"#\" data-headword=\"גֶּשֶׁם I\"><span dir=\"rtl\">גֶּשֶׁם</span> I</a>.—<span dir=\"rtl\">י׳ החמה</span> a) <i>summer season.</i> <span class=\"citation\">Toh. VI, 7</span>; a. fr.—b) <i>the solar year</i>. <span class=\"citation\">Gen. R. s. 33</span>, end; a. fr.—י׳ הלבנה <i>the lunar year</i>. Ib.; a. fr.—<span dir=\"rtl\">י׳ בגרות</span>, <span dir=\"rtl\">י׳ נערות</span>, v. <a href=\"#\" data-headword=\"בַּגְרוּת\">בַּגְרוּת</a></div>","alt":[]},"14299":{"h":"יוֹם ²","r":"J00195","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Gen. I, 5</span>. <span class=\"citation\">Ib. XXXIX, 11</span>; a. fr.—<span class=\"citation\">Targ. Prov. XII, 16</span> <span dir=\"rtl\">בר יוֹמֵיה</span> (ed. Wil. incorr. <a href=\"#\" data-headword=\"כַּד I\">כד</a>) on the same day, <i>at once</i>.—<span class=\"citation\">Kidd. 39ᵇ</span> <span dir=\"rtl\">דעבדין ליה י׳ טב וי׳ ביש</span> they prepare for him (the righteous man) a good day, and (for the bad man) a bad day (v. Rashi a. Tosaf. a. l.).—<span class=\"citation\">Sabb. 134ᵃ</span>; <span class=\"citation\">Ḥull. 60ᵃ</span> top <span dir=\"rtl\">להדי י׳</span> towards the sunlight. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">י׳ דחד וכ׳</span> the sun which is only one of the ministering powers &amp;c. <span class=\"citation\">Keth. 106ᵃ</span> <span dir=\"rtl\">וכסי ליה לי׳</span> and obscured the sun.—<span class=\"citation\">Yeb. 72ᵃ</span> <span dir=\"rtl\">י׳ דעיבא</span> a cloudy day; <span dir=\"rtl\">י׳ דשותא</span> a day when a southern wind blows. <span class=\"citation\">Erub. 40ᵇ</span> <span dir=\"rtl\">במעלי י׳ דריש וכ׳</span> on the eve of the New Year’s day.—<span class=\"citation\">R. Hash. 21ᵃ</span> <span dir=\"rtl\">י׳ רבה</span> the Great Day, Day of Atonement (also only <a href=\"#\" data-headword=\"יוֹם ²\">יומא</a>, v. infra); a. v. fr.—<a href=\"#\" data-headword=\"יוֹכָנִי\">בַּר י׳</a>, <span dir=\"rtl\">בַּת י׳</span> <i>of the same day, one day old, used the same day</i>. <span class=\"citation\">Bets. 4ᵇ</span>, v. <a href=\"#\" data-headword=\"בֵּיעָא\">בֵּיעָא</a>. <span class=\"citation\">Ḥull. 58ᵇ</span>, v. <a href=\"#\" data-headword=\"בַּקָּא\">בַּקָּא</a>.—<span class=\"citation\">Sabb. 134ᵃ</span> <span dir=\"rtl\">גבינה בת י׳</span> fresh-made cheese. <span class=\"citation\">Ab. Zar. 67ᵇ</span>, a. fr. <span dir=\"rtl\">קדירה בת י׳</span> a pot used the same day.—<span class=\"citation\">Sabb. 49ᵇ</span> bot. <span dir=\"rtl\">ההוא מרבנן בר יוֹמֵיה</span> (omitted in Ms. M.) a student that had just come to college; [oth. opin.: allusion to R. Idi, dubbed <span dir=\"rtl\">בר בי רב דחד י׳</span> the one day’s student of the college, <span class=\"citation\">Ḥag. 5ᵇ</span>].—<span dir=\"rtl\">י׳ חרא</span>, <span dir=\"rtl\">יום מחרא</span>, <span dir=\"rtl\">י׳ מחרן</span>, v. next w.—Pl. <span dir=\"rtl\">יוֹמִין</span>, <span dir=\"rtl\">יוֹמַיָּא</span>, <span dir=\"rtl\">יוֹמֵי</span>. <span class=\"citation\">Targ. Gen. VIII, 10</span>. <span class=\"citation\">Targ. Esth. I, 2</span>; a. v. fr.—<span class=\"citation\">Bets. 4ᵇ</span> <span dir=\"rtl\">עבדינן תרי י׳</span> we observe two days (as Holy Days). <span class=\"citation\">Erub. 65ᵃ</span> <span dir=\"rtl\">השתא … י׳ דאריכי וכ׳</span> soon will come the days which are long (of duration) and short (of action), when we shall sleep much; a. v. fr.—<a href=\"#\" data-headword=\"יוֹם ²\">יוֹמָא</a> (sub <a href=\"#\" data-headword=\"רַבָּה I\">רבה</a>, v. supra) <i>Yoma</i>, name of a treatise of the Mishnah, Tosefta (where it is named <span dir=\"rtl\">יום כפורים</span>), Talmud Babli a. Y’rushalmi. <span class=\"citation\">Yoma 14ᵇ</span> <span dir=\"rtl\">סדר י׳</span> the treatise on the order of exercises of the Day of Atonement.—V. <a href=\"#\" data-headword=\"יוֹמָנָא\">יוֹמָנָא</a>, <a href=\"#\" data-headword=\"יְמָמָא\">יְמָמָא</a>.</div>","alt":["יוֹמָא"]},"14300":{"h":"יוֹמָחְרָא","r":"J00196","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">יומא אוחרא</span>, <span dir=\"rtl\">י׳ אוחרן</span>) <i>tomorrow, next day</i>. <span class=\"citation\">Targ. Y. Ex. XIX, 10</span> (ed. Amst. <span dir=\"rtl\">יום מחרא</span>). <span class=\"citation\">Targ. Esth. III, 4</span> ed. Lag. (ed. Amst. <a href=\"#\" data-headword=\"יוֹם ²\">יומא</a>). <span class=\"citation\">Targ. Y. Lev. VII, 16</span> (ed. Amst. <span dir=\"rtl\">יום מחרן</span>); a. e. [<span class=\"citation\">Targ. II Chr. XX, 16</span> <span dir=\"rtl\">יומא חרא</span>, ed. Lag. <span dir=\"rtl\">יומא אחרא</span>.]—V. <a href=\"#\" data-headword=\"חֲרָא\">חֲרָא</a>.</div>","alt":["יוֹמָחֲרָן"]},"14301":{"h":"יוֹמָנָא","r":"J00197","html":"<div class=\"sense\"> (contr. of <span dir=\"rtl\">יוֹמָא דְנָא</span>) <i>this day, this life</i>. <span class=\"citation\">Targ. Y. Deut. XXVII, 1</span>.—<span class=\"citation\">Targ. Y. I Deut. XXVI, 17</span> (Y. II <span dir=\"rtl\">יומא דין</span>); ib. 18. <span class=\"citation\">Targ. Prov. VII, 14</span>. [Ib. v. 20 וליומנא וועידא Ms., ed. <span dir=\"rtl\">וליומא דעידא</span>.] <span class=\"citation\">Targ. Ps. XXIII, 6</span> <span dir=\"rtl\">נגדא די׳</span> (h. text <span dir=\"rtl\">ארך ימים</span>).</div>","alt":[]},"14302":{"h":"יָוֵן","r":"J00198","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> יון <i>to be thick, dark</i>, <i>thickness</i>, <span dir=\"rtl\">טיט הי׳</span> <i>thick, heavy clay</i>, opp. to <span dir=\"rtl\">טיט טופח</span> (v. <a href=\"#\" data-headword=\"טָפַח II\"><span dir=\"rtl\">טָפַח</span> II</a>). <span class=\"citation\">Mikv. IX, 2</span>. <span class=\"citation\">Tosef. ib. VI</span> (<span class=\"citation\">VII), 12</span>; <span class=\"citation\">13</span> <span dir=\"rtl\">אם היה טיט</span> (<a href=\"#\" data-headword=\"ה\">ה</a>)<span dir=\"rtl\">י׳ וחיברו</span> if it was a thick massive clay and he attached it.—Denom. <a href=\"#\" data-headword=\"יְוֵנִי\">יְוֵנִי</a> m. <i>muddy, thick</i>. Mikv. l. c., v. <a href=\"#\" data-headword=\"גֵּץ\">גֵּץ</a> 2.</div>","alt":[]},"14303":{"h":"יָוָן","r":"J00199","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b>  pr. n. m. <i>Javan</i>, son of Japheth, progenitor of the Grecian tribes, in gen. <i>Greek, Greece;</i></div><div class=\"sense\"><a href=\"#\" data-headword=\"מַלְכוּת\">מלכות</a>) <i>Greek</i> (<i>Syrian</i>) <i>Government</i>. <span class=\"citation\">Targ. Gen. X, 2</span>; a. e.—<span class=\"citation\">Targ. Y. Gen. XV, 12</span>.—<span class=\"citation\">Gen. R. s. 44</span> (ref. to <span dir=\"rtl\">איל משלש</span>, <span class=\"citation\">Gen. XV, 9</span>) <span dir=\"rtl\">זו י׳</span> this alludes to the Greek government (founded by Alexander the Great). Ib. <span dir=\"rtl\">כל רוחות כבשו בני י׳ וכ׳</span> in all directions did the Greeks conquer, except in the East. Esth. R. introd. <span dir=\"rtl\">בבקרה של י׳</span> when Greece (Syria) is in the ascendancy, v. <a href=\"#\" data-headword=\"בֹּקֶר\">בֹּקֶר</a>; a. fr.—Denom. <a href=\"#\" data-headword=\"יְוָנִי\">יְוָנִי</a>, <a href=\"#\" data-headword=\"יְוָנָאָה\">יְוָנָאָה</a>.</div>","alt":["יָוָון"]},"14304":{"h":"יוֹן","r":"J00200","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יוֹנְתָא\">יוֹנְתָא</a></div>","alt":["יוֹנָא"]},"14305":{"h":"יְוָנָאָה","r":"J00201","html":"<p class=\"morphology\">m.</p><div class=\"sense\">—Pl. <span dir=\"rtl\">יְוָנָאֵי</span>. <span class=\"citation\">Targ. I Sam. II, 4</span> (ed. Lag. <a href=\"#\" data-headword=\"יָוָון\">יְוָונֵי</a>, ed. Wil. <span dir=\"rtl\">מַקְדּוּנָאֵי</span>). <span class=\"citation\">Targ. Y. I Deut. XXXII, 24</span> (ed. Amst. <span dir=\"rtl\">יוֹוָ׳</span>, ed. Vien. <a href=\"#\" data-headword=\"יוֹן\">יוֹנָ׳</a>; corr. acc.).</div>","alt":["יְוָו׳"]},"14306":{"h":"יוֹנָה I","r":"J00202","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Jonah</i>, </div><div class=\"sense\"><b>1)</b>  the prophet. <span class=\"citation\">Y. Erub. X, beg. 26ᵃ</span>; Bab. <span class=\"citation\">Erub. 96ᵃ</span>. <span class=\"citation\">Snh. 89ᵃ</span>, sq <span class=\"citation\">Gen. R. s. 21</span>; a. fr.</div><div class=\"sense\"><b>—2)</b>  name of several Amoraim. a) R. J. father of R. Mana. <span class=\"citation\">Taan. 23ᵇ</span>. <span class=\"citation\">Y. Shebi. IV, 35ᵃ</span> bot.; a. v. fr.—b) R. J. of Bozra. <span class=\"citation\">Y. Kil. IX, beg. 31ᵈ</span>; a. fr.—[<span class=\"citation\">Ḥull. 43ᵇ</span> י׳ אמר ר׳ זירא Jonah said in behalf of R. Z.; oth. opin.: as to the gullet of a <i>dove</i>, &amp;c., v. next w.]</div>","alt":[]},"14307":{"h":"יוֹנָה II","r":"J00203","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) <i>dove</i>. <span class=\"citation\">Ḥull. 6ᵃ</span> <span dir=\"rtl\">דמות י׳ וכ׳</span> the effigy of a dove was found on Mount Gerizim which they (the Samaritans) worshipped. <span class=\"citation\">Gen. R. s. 39</span> <span dir=\"rtl\">הי׳ הזו בשעה שהיא פורחת וכ׳</span> the dove when flying and tired, flaps one wing and flies with the other. <span class=\"citation\">Gen. R. s. 44</span> (expl. <span dir=\"rtl\">גוזל</span>, <span class=\"citation\">Gen. XV, 9</span>) <span dir=\"rtl\">בר י׳</span> a young dove, (v. infra, a. Targ. Gen. l. c.).—<a href=\"#\" data-headword=\"הֲדָיָא II\">בֶּן י׳</a>, pl. <a href=\"#\" data-headword=\"בְּרַק II\">בְּנֵי י׳</a> <i>pigeons</i>. <span class=\"citation\">Ḥull. I, 5</span> <span dir=\"rtl\">כשר בתורין פסול בבני י׳</span> what is fit for offering in doves (large size), is a defect in pigeons; a. fr.—[<span class=\"citation\">Sabb. 129ᵃ</span> <span dir=\"rtl\">פתורא דיונה</span>, v. <a href=\"#\" data-headword=\"*יוֹנָס\">יוֹנָס</a>.].—Pl. <span dir=\"rtl\">יוֹנִים</span>, <span dir=\"rtl\">יוֹנִין</span>. <span class=\"citation\">Snh. III, 3</span> <span dir=\"rtl\">מפריחי י׳</span> those who let doves fly (betting on them), v. <a href=\"#\" data-headword=\"יוֹנְתָא\">יוֹנְתָא</a>. <span class=\"citation\">B. Bath. V, 3</span>, v. <a href=\"#\" data-headword=\"שׁוֹבָךְ\">שׁוֹבָךְ</a>. <span class=\"citation\">Ib. 79ᵃ</span>; a. e.</div>","alt":[]},"14308":{"h":"יונוס","r":"J00204","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יַנִּיס\">יַנִּיס</a></div>","alt":[]},"14309":{"h":"יְוֵנִי","r":"J00205","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יָוֵן\">יָוֵן</a></div>","alt":[]},"14310":{"h":"יְוָנִי","r":"J00206","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָוָן\">יָוָן</a>) <i>Grecian, Greek</i>. <span class=\"citation\">B. Kam. 82ᵇ</span> <span dir=\"rtl\">חָכְמַת י׳</span> the principle of Greek culture (philosophy, ethics, religion &amp;c.). <span class=\"citation\">Ib. 83ᵃ</span> לשון י׳ Greek language, distinguished fr. <span dir=\"rtl\">חכמת י׳</span>. <span class=\"citation\">Meg. 9ᵃ</span> <span dir=\"rtl\">התירו יונית</span> permitted the use of a Greek translation. Y. ib. I, 71ᶜ top, v. <a href=\"#\" data-headword=\"בָּדָא\">בָּדָא</a>; a. fr.—V. <a href=\"#\" data-headword=\"לָשׁוֹן\">לָשׁוֹן</a>.—Pl. <a href=\"#\" data-headword=\"יְוָנִי\">יְוָנִים</a>, <a href=\"#\" data-headword=\"יְוָנָאָה\">יְוָו׳</a> <i>Greeks</i> (mostly of the Syrian government). <span class=\"citation\">Meg. 11ᵃ</span> <span dir=\"rtl\">בימי י׳</span> in the days of the Greeks (of Antiochus Epiphanes and successors); Esth. R., beg. <a href=\"#\" data-headword=\"טרקווינוס\">טרקווינוס</a> (corr. acc.).</div>","alt":["יְוָו׳","יְוָנִית","יְוָו׳"]},"14311":{"h":"*יוֹנָס","r":"J00207","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (prob. a corrupt. of juniperus) <i>Juniper-tree</i> (v. Sm. Ant. s. v. Cedrus). <span class=\"citation\">Sabb. 129ᵃ</span> <span dir=\"rtl\">פתורא די׳</span> old ed. (later ed. <span dir=\"rtl\">דיונה</span>, Ms. M. <span dir=\"rtl\">דיינס</span>, v. Rabb. D. S. a. l. note; Ar. <span dir=\"rtl\">יינוס</span>, expl.: <i>cypress</i></div>","alt":[]},"14312":{"h":"יוֹנֵק","r":"J00208","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>child.</i>—Pl. <span dir=\"rtl\">יוֹנְקִים</span>. <span class=\"citation\">Cant. R. to I, 4</span> <span dir=\"rtl\">הי׳</span> the school children. V. <a href=\"#\" data-headword=\"יָנוּקָא I\">יָנוּקָא</a>.</div>","alt":[]},"14313":{"h":"יוֹנְקָא","r":"J00209","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יַנְקָא I\">יַנְקָא</a></div>","alt":[]},"14314":{"h":"יוֹנֶקֶת","r":"J00210","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>sucker, sprout</i> (of hyssop).—Pl. <span dir=\"rtl\">יוֹנְקוֹת</span>. <span class=\"citation\">Par. XI, 7</span>, v. <a href=\"#\" data-headword=\"גָּמַל\">גָּמַל</a>; <span class=\"citation\">Tosef. ib. XI</span> (<span class=\"citation\">X), 7</span> (one opin.) <span dir=\"rtl\">י׳ שלא הנצו וכ׳</span> <i>yon’koth</i> are such as have not yet begun to blossom.</div>","alt":[]},"14315":{"h":"יוֹנְתָא","r":"J00211","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יוֹן\">יוֹן</a> c.) ch. = h.. <span class=\"citation\">Targ. Gen. VIII, 8</span>, sq. <span class=\"citation\">Targ. Ps. LVI, 1</span>; a. e.—<span class=\"citation\">Snh. 25ᵃ</span> (expl. <span dir=\"rtl\">מפריחי יונים</span>, v. <a href=\"#\" data-headword=\"יוֹנָה II\"><span dir=\"rtl\">יוֹנָה</span> II</a>) <span dir=\"rtl\">אי תקדמיה יוֹנָךְ ליון</span> if thy dove shall overtake the cock-pigeon (thou shalt win &amp;c.). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">תולה בדעת יוֹנוֹ</span> v. <a href=\"#\" data-headword=\"דַּעַת\">דַּעַת</a>. <span class=\"citation\">Y. Ab. Zar. V, 44ᵈ</span> bot. <span dir=\"rtl\">כמין יון וכ׳</span> they (the Samaritans) have an image resembling a cock-pigeon to which they offer libations (cmp. <a href=\"#\" data-headword=\"יוֹנָה II\"><span dir=\"rtl\">יוֹנָה</span> II</a>). <span class=\"citation\">Snh. 95ᵃ</span> <span dir=\"rtl\">אתא יונה וכ׳</span> (masc.) a dove came down &amp;c., v. <a href=\"#\" data-headword=\"טְרַף I\"><span dir=\"rtl\">טְרַף</span> I</a>.—Pl. <span dir=\"rtl\">יוֹנִין</span>, <span dir=\"rtl\">יוֹנַיָּא</span>, <span dir=\"rtl\">יוֹנֵי</span>, <span dir=\"rtl\">יוֹנָן</span>, <a href=\"#\" data-headword=\"יוֹנְתָא\">יוֹנָתָא</a>. <span class=\"citation\">Targ. Is. LIX, 11</span>. <span class=\"citation\">Targ. Y. Lev. V, 7</span>; <span class=\"citation\">11</span> <span dir=\"rtl\">בני יוניא</span> (O. <span dir=\"rtl\">כני יונה</span>, v. <a href=\"#\" data-headword=\"יוֹנָה II\"><span dir=\"rtl\">יוֹנָה</span> II</a>). <span class=\"citation\">Ib. XII, 6</span> <span dir=\"rtl\">בר יונן</span> (O. <a href=\"#\" data-headword=\"יוֹנְתָא\">יונה</a>). <span class=\"citation\">Targ. Cant. I, 15</span>.—<span class=\"citation\">Ber. 56ᵃ</span> תזאי תרתי יוני דפרחן I saw (in my dream) two doves fly off. <span class=\"citation\">Ib.ᵇ</span> <span dir=\"rtl\">תרי יוני</span>.</div>","alt":["יוֹנָא","יוֹנָה"]},"14316":{"h":"יוֹנָתָן","r":"J00212","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Jonathan</i>, </div><div class=\"sense\"><b>1)</b>  J. b. Gershom (<span class=\"citation\">Jud. XVIII, 30</span>), a priest of idolatry, supposed to be a descendant of Moses. <span class=\"citation\">B. Bath. 109ᵇ</span> יו׳ Ms. M. (ed. <span dir=\"rtl\">יהו׳</span>). <span class=\"citation\">Cant. R. to II, 5</span>; <span class=\"citation\">Ab. d’R. N. ch. XXXIV</span>; <span class=\"citation\">Y. Ber. IX, 13ᵈ</span> top; a. e.</div><div class=\"sense\"><b>—2)</b>  J. son of Saul. <span class=\"citation\">Ab. V, 16</span> <span dir=\"rtl\">אהבת דוד וי׳</span> the friendship between David and J. <span class=\"citation\">Ḥull. 95ᵇ</span> <span dir=\"rtl\">כי׳ בן וכ׳</span> like the omen of J. &amp;c. (1 Sam. XIV, 8 sq.). <span class=\"citation\">Cant. R. to VIII, 6</span>; a. e.</div><div class=\"sense\"><b>—3)</b>  J. b. Uziel, author of the Chaldaic version of the Prophets (v. Zunz, Gottesd. Vortr. p. 66, sq.). <span class=\"citation\">Succ. 28ᵃ</span>; <span class=\"citation\">B. Bath. 134ᵃ</span>. <span class=\"citation\">Meg. 3ᵃ</span> <span dir=\"rtl\">תרגיס של נכיאים י׳ וכ׳</span> the version of the Prophets has been composed by J. b. U. at the dictation of Haggai &amp;c. <span class=\"citation\">Y. Ned. V, end, 39ᵇ</span> <span dir=\"rtl\">גדול שבהן י׳ ב׳ ע׳</span></div><div class=\"sense\"><b>—4)</b>  R. J., a Tannai. <span class=\"citation\">Sot. 24ᵃ</span>. <span class=\"citation\">Pes. 24ᵃ</span>. <span class=\"citation\">Ḥull. 70ᵇ</span>; a. v. fr.—[<span class=\"citation\">Erub. 96ᵃ</span> <span dir=\"rtl\">י׳ הקיטוני</span>.]—[<span class=\"citation\">Ab. IV, 9</span>, v. Frank. Darkhé, p. 147, note.]</div><div class=\"sense\"><b>—5)</b>  name of several Amoraim (v. Fr. M’bo, p. 99ᵃ, sq.). <span class=\"citation\">Gitt. 78ᵇ</span>. <span class=\"citation\">Y. Maas. Sh. III, 54ᵇ</span> top. <span class=\"citation\">Ber. 18ᵃ</span>; Y. ib. II, 4ᶜ bot.; a. fr.—<span class=\"citation\">Y. Yoma VII, 44ᵇ</span> bot. R. J. of Beth Gubrin.—<span class=\"citation\">Y. Peah V, beg. 18ᵈ</span> (R. S. to <span class=\"citation\">Peah V, 1</span> quotes R. Johanan); <span class=\"citation\">Y. Shek. I, 46ᵃ</span> bot. R. J. son of R. Isaac bar Aḥa.—<span class=\"citation\">Y. Ter. XI, end, 48ᵇ</span> J. b. ʿAkhmai; a. e.</div>","alt":["יְהוֹנָתָן"]},"14317":{"h":"יוֹסָא","r":"J00213","html":"<div class=\"sense\">, abbrev. of <a href=\"#\" data-headword=\"יוֹסֵף\">יוֹסֵף</a>, v. <a href=\"#\" data-headword=\"יוֹסֵי\">יוֹסֵי</a>.</div>","alt":["יוֹסָה"]},"14318":{"h":"יוּסְטָא","r":"J00214","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (abbrev. of Justus or Justinus) <i>Yusta, Yusti</i>. </div><div class=\"sense\"><b>1)</b>  <span class=\"citation\">Cant. R. to VI, 12</span> י׳ חייטא Yusta, the tailor.</div><div class=\"sense\"><b>—2)</b>  name of several Amoraim. <span class=\"citation\">Y. Erub. VI, 23ᶜ</span> bot. <span dir=\"rtl\">ר׳ יוסטי</span>; <span class=\"citation\">Y. Shek. II, beg. 46ᶜ</span> <span dir=\"rtl\">ר׳ יוסטא</span>.—<span class=\"citation\">Y. Ter. XI, 48ᵃ</span>; <span class=\"citation\">Y. Maas. Sh. V, 55ᵈ</span> bot. <span dir=\"rtl\">יוסטי בר שונם</span>; <span class=\"citation\">Y. Shebi. VI, 36ᵈ</span> <span dir=\"rtl\">יוסטא בר ש׳</span>.</div>","alt":["יוּסְטִי"]},"14319":{"h":"יוּסְטִינָה","r":"J00215","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"יוּסְטָא\">preced.</a>; abbrev. of Justinus or Justinianus) <i>Yustinah, Yustini</i>, an Amora. <span class=\"citation\">Y. Keth. IX, 32ᵈ</span> bot. (not <a href=\"#\" data-headword=\"יוסטתה\">יוסטתה</a>); <span class=\"citation\">Y. B. Bath. VIII, 16ᵇ</span> <a href=\"#\" data-headword=\"יוּסְטִינָה\">יוסטיני</a>.</div>","alt":["יוּסְטִינִי"]},"14320":{"h":"יוסטתה","r":"J00216","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יוּסְטִינָה\">preced.</a></div>","alt":[]},"14321":{"h":"יוֹסֵי","r":"J00217","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (abbrev. of Joseph, interch. with <a href=\"#\" data-headword=\"יוֹסֵף\">יוֹסֵף</a>, <a href=\"#\" data-headword=\"יוֹסָא\">יוֹסָא</a>, <a href=\"#\" data-headword=\"יוֹסָא\">יוֹסָה</a>, <a href=\"#\" data-headword=\"יַסָּא\">יַסָּא</a>, <a href=\"#\" data-headword=\"יַסָּה\">יַסָּה</a>, <a href=\"#\" data-headword=\"אַסִּי\">אַסִּי</a>, <a href=\"#\" data-headword=\"אִיסִי\">אִיסִי</a>) <i>José</i> </div><div class=\"sense\"><b>1)</b>  name of several Tannaim, esp. J. b. Joezer, and J. b. Johanan. <span class=\"citation\">Ab. I, 4</span>, sq. <span class=\"citation\">Eduy. VIII, 4</span>; a. fr.—<span class=\"citation\">B. Bath. 133ᵇ</span> <a href=\"#\" data-headword=\"יוֹסֵף\">יוסף</a> (Ms. H. a. R. <a href=\"#\" data-headword=\"יוֹסֵי\">יוסי</a>).—R. J. hak-Kohen, or only R. J. <span class=\"citation\">Ab. II, 8</span>; <span class=\"citation\">12</span>. <span class=\"citation\">Ḥag. 14ᵇ</span>; Y. ib. II, 77ᵃ bot. <a href=\"#\" data-headword=\"יוֹסֵף\">יוסף</a>; a. v. fr.—R. J. b. Ḥalafta, or only R. J. <span class=\"citation\">B. Kam. 70ᵃ</span>; <span class=\"citation\">Tosef. B. Bath. II, 10</span> (v. Fr. Darkhé, p. 132). <span class=\"citation\">Erub. 46ᵇ</span>. <span class=\"citation\">Maas. Sh. IV, 7</span>; a. v. fr. (v. Fr. ib. p. 164, sq.).—R. J., the Galilean. <span class=\"citation\">Zeb. 57ᵃ</span>. <span class=\"citation\">Ab. Zar. III, 5</span>. <span class=\"citation\">Tosef. Mikv. VII</span> (<span class=\"citation\">VIII), 11</span>; a. fr. (v. Fr. ib., p. 125).</div><div class=\"sense\"><b>—2)</b>  name of several Amoraim, esp. R. J. (in Babli <a href=\"#\" data-headword=\"אַסִּי\">אַסִּי</a>, in Y. also <a href=\"#\" data-headword=\"יַסָּא\">יַסָּא</a>, <a href=\"#\" data-headword=\"יוֹסָא\">יוֹסָה</a>). Y. Ber. II, 5ᶜ bot. Y. Kil. IX, 29ᵇ bot.; <span class=\"citation\">Y. Erub. I, 19ᶜ</span>; a. v. fr.—R. J. bar Zabda, mate of R. Jonah. <span class=\"citation\">Y. Shek. VII, 50ᶜ</span> bot. <span class=\"citation\">Men. 70ᵇ</span>; a. v. fr.</div><div class=\"sense\"><b>—3)</b>  <a href=\"#\" data-headword=\"יוֹסֵי\">יוסי</a> or <a href=\"#\" data-headword=\"יוֹסָא\">יוסה</a> a disguise of one of the Divine Names. <span class=\"citation\">Snh. VII, 5</span> (<span class=\"citation\">56ᵃ</span>) <span dir=\"rtl\">בכל יום … יכה י׳ את י׳</span> (v. Rabb. D. S. a. l. note) during the proceedings against the blasphemer the witnesses are requested to make their statements in disguise (v. <a href=\"#\" data-headword=\"כִּינּוּי\">כִּינּוּי</a>), e.g.: “the defendant said, ‘May J. strike J.’  ” (meaning, I curse Jehovah Elohim, J. Zebaoth &amp;c.; cmp. ib. <span dir=\"rtl\">עד שיברך שם בשם</span>).</div><div class=\"sense\"><b>—4)</b>  one <i>J.</i> <i> M’shitha</i>, a repentant Hellenist. <span class=\"citation\">Gen. R. s. 65</span> (some ed. <a href=\"#\" data-headword=\"יוֹסֵף\">יוסף</a>); <span class=\"citation\">Yalk. ib. 115</span>.</div>","alt":[]},"14322":{"h":"יוֹסִינָא","r":"J00218","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Josina</i>. <span class=\"citation\">Y. Meg. IV, 75ᵇ</span> bot.; <span class=\"citation\">Y. Yeb. XIII, 13ᶜ</span> top; ib. X, 10ᵈ top. <span class=\"citation\">Cant. R. to V, 1</span> <span dir=\"rtl\">יוֹסָנָה</span>; <span class=\"citation\">Pesik. R. s. 5</span> <span dir=\"rtl\">יוֹסנִי</span>; <span class=\"citation\">Num. R. s. 13</span> <span dir=\"rtl\">יוֹסַנְיָה</span>.</div>","alt":["יוֹסִינָה"]},"14323":{"h":"יוֹסֵף","r":"J00219","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Joseph</i>, </div><div class=\"sense\"><b>1)</b>  son of Jacob. <span class=\"citation\">B. Bath. 123ᵃ</span>, v. <a href=\"#\" data-headword=\"בְּכוֹרָה\">בְּכוֹרָה</a>. <span class=\"citation\">Sot. I, 9</span>. <span class=\"citation\">Gen. R. s. 30</span>; a. v. fr.</div><div class=\"sense\"><b>—2)</b>  name of several Tannaim and Amoraim, v. <a href=\"#\" data-headword=\"יוֹסֵי\">יוֹסֵי</a></div><div class=\"sense\"><b>—3)</b>  <span class=\"citation\">Sabb. 119ᵃ</span> י׳ מוקיר שבי Joseph, the honorer of the Sabbaths.—Ib. 130ᵃ J. Rishba (the fowler).—<span class=\"citation\">Gen. R. s. 65</span>, v. <a href=\"#\" data-headword=\"יוֹסֵי\">יוֹסֵי</a></div>","alt":[]},"14324":{"h":"יוסתיניא","r":"J00220","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"וַוסְתַּנְיָא\">וַוסְתַּנְיָא</a></div>","alt":["יוסתניא"]},"14325":{"h":"יוֹעֶזֶר","r":"J00221","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b>  pr. n. m. <i>Joezer</i>. Orlah II, 12 a disciple of Shammai’s school.—<span class=\"citation\">Ab. I, 4</span>; a. fr., v. <a href=\"#\" data-headword=\"יוֹסֵי\">יוֹסֵי</a></div><div class=\"sense\"><b>—2)</b>  name of <i>a plant</i>. <span class=\"citation\">Sabb. XIV, 3</span>, expl. Y. ib. 14ᶜ פוליטריכין <i>polytrichon, Maiden-hair</i>; Bab. ib. 109ᵇ <a href=\"#\" data-headword=\"פּוּתְנַק\">פותנק</a>.</div>","alt":[]},"14326":{"h":"יוֹפִי","r":"J00222","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>fine build, beauty; propriety</i> <span class=\"citation\">Taan. 31ᵃ</span> (the fair maiden said) <span dir=\"rtl\">תנו עיניכם לי׳</span> ed. (Ms. M. <a href=\"#\" data-headword=\"בִּרְיְתָא\">בי׳</a>) put your eyes on (give your choice to) beauty. <span class=\"citation\">Succ. 45ᵇ</span> Ms. M. (ed. in Mish., <span class=\"citation\">ib. 45ᵃ</span>, v. Rabb. D. S. a. l.) <span dir=\"rtl\">י׳ לך מזבח</span> thine, altar, is the beauty (of forgiveness). <span class=\"citation\">Ex. R. s. 25</span> אני מראה לך י׳ פנים אל פנים I shall let thee see the beauty of a revelation of face to face (as granted to Moses). <span class=\"citation\">Yoma 54ᵇ</span> <span dir=\"rtl\"><span dir=\"rtl\">מוכלל</span> (<span dir=\"rtl\">יָפְיוֹ</span>) <span dir=\"rtl\">יוֹפְיוֹ של וכ׳</span></span> the perfection of the beauty (harmony) of the universe. <span class=\"citation\">Kidd. 49ᵇ</span> <span dir=\"rtl\">עשרה קבים י׳ וכ׳</span> ten measures of beauty have come down to the world, nine of which Jerusalem has taken; <span class=\"citation\">Esth. R. to I, 3</span>. <span class=\"citation\">B. Mets. 87ᵃ</span> <span dir=\"rtl\">וחזר י׳ למקומו</span> and (her) beauty came back again; a. fr.—<span class=\"citation\">Peah VI, 6</span> <span dir=\"rtl\">י׳ כח</span>, v. <a href=\"#\" data-headword=\"יָפֶה\">יָפֶה</a>.</div>","alt":[]},"14327":{"h":"יוֹפִיאֵל","r":"J00223","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יוֹפִי\">preced.</a>) <i>Yofiël</i>, name of an angel. <span class=\"citation\">Targ. Y. I Deut. XXXIV, 6</span>.</div>","alt":[]},"14328":{"h":"יוֹפְיוּת","r":"J00224","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יָפְיוּת\">יָפְיוּת</a></div>","alt":[]},"14329":{"h":"יוֹצְאָנִית","r":"J00225","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָצָא\">יָצָא</a>) <i>loving to go out, restless</i>. Tanḥ. Vayishl. 7.—Pl. <span dir=\"rtl\">יוֹצְאָנִיּוֹת</span>. <span class=\"citation\">Gen. R. s. 45</span>.</div>","alt":[]},"14330":{"h":"יוֹצֵאת","r":"J00226","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> constr., <span dir=\"rtl\">י׳ החוץ</span> (<a href=\"#\" data-headword=\"יוֹצְאָנִית\">preced.</a>) <i>running about, prostitute.</i> <span class=\"citation\">Kel. XXVIII, 9</span>; <span class=\"citation\">Tosef. Kel. B. Bath. V, 14</span>, v. <a href=\"#\" data-headword=\"חוּץ II\"><span dir=\"rtl\">חוּץ</span> II</a>.—Pl. <span dir=\"rtl\">יוֹצְאוֹת</span>. Ib. some ed.</div>","alt":[]},"14331":{"h":"יוּצְפָּא","r":"J00227","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יְצַף\">יְצַף</a></div>","alt":[]},"14332":{"h":"יוֹצֵר","r":"J00228","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>Creator</i>. <span class=\"citation\">Lev. R. s. 23</span>, end (ref. to <span class=\"citation\">Deut. XXXII, 18</span>) <span dir=\"rtl\">רפו ידיו של י׳</span> the Creator’s hands become lax (undecided). [Ib. <span dir=\"rtl\">תשו ידיו של י׳</span>, read: <a href=\"#\" data-headword=\"צַיָּיר\">צַיָּיר</a>.]—Mekh. Bo. s. 13; Tanḥ. Bo. 7 (ref. to <span class=\"citation\">Ex. XII, 29</span>) <span dir=\"rtl\">יוֹצרוֹ חלקז</span> He who created it (the night) divided it (exactly into two halves); <span class=\"citation\">Gen. R. s. 43</span>. <span class=\"citation\">Ber. 61ᵃ</span> (play on <span dir=\"rtl\">וייצר</span>, <span class=\"citation\">Gen. II, 7</span>, v. <a href=\"#\" data-headword=\"יְצִירָה\">יְצִירָה</a>) <span dir=\"rtl\">אוי לי מִיּוֹצְרִי אוי לי מִיִּצְרִי</span> woe is to me from (my responsibility to) my Creator, woe to me from (my struggle with) my inclination; a. fr.</div><div class=\"sense\"><b>—2)</b>  [<i>turner</i>,] <i>potter</i>. <span class=\"citation\">Gen. R. s. 55</span> (ref. to <span class=\"citation\">Ps. XI, 5</span>) <span dir=\"rtl\">הי׳ הזה וכ׳</span> the potter when examining his batch, will not try the defective vessels &amp;c. Lev. R. l. c. <span dir=\"rtl\">תלמידו של י׳</span> a potter’s apprentice; a. fr.;—Pl. <span dir=\"rtl\">יוֹצְרִים</span>. <span class=\"citation\">Maasr. III, 7</span>; <span class=\"citation\">Succ. 8ᵇ</span>, a. fr., v. <a href=\"#\" data-headword=\"סוּכָּה\">סוּכָּה</a>.—<span class=\"citation\">Par. V, 6</span>, v. <a href=\"#\" data-headword=\"בֵּיצָה\">בֵּיצָה</a>.—Lev. R. l. c. <span dir=\"rtl\">שגנב ביצת י׳</span> who stole a lump of potters’ clay; <span class=\"citation\">Pesik. R. s. 24</span> <span dir=\"rtl\">שגנב יצרים</span> (corr. acc.).</div>","alt":[]},"14333":{"h":"יוצרה","r":"J00229","html":"<div class=\"sense\">, Y. B. Mets. VIII, end, 11ᵈ, v. <a href=\"#\" data-headword=\"יְצִירָה\">יְצִירָה</a> 2.</div>","alt":[]},"14334":{"h":"יוֹקֵידְתָּא","r":"J00230","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יְקֵדָא\">יְקֵדָא</a></div>","alt":[]},"14335":{"h":"יוֹקְיָנוֹס","r":"J00231","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"אוֹקְיָינוֹס\">אוֹקְיָינוֹס</a>(?). Targ. Y. II. <span class=\"citation\">Num. XXXIV, 15</span>; [the entire verse is corrupt].</div>","alt":["דְּיוֹ׳"]},"14336":{"h":"יוקפא","r":"J00232","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יוּבְּקָא\">יוּבְּקָא</a></div>","alt":[]},"14337":{"h":"יוֹקֶר","r":"J00233","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָקַר\">יָקַר</a>) [<i>weight, importance</i>,] </div><div class=\"sense\"><b>1)</b> <i>high price</i> (opp. <a href=\"#\" data-headword=\"זוּל I\">זול</a>); <i>dearth, scarcity.</i> <span class=\"citation\">Maas. Sh. IV, 1</span> <span dir=\"rtl\">מקום י׳</span> where fruits are dear; <span class=\"citation\">B. Mets. 73ᵃ</span>. <span class=\"citation\">Sabb. 32ᵇ</span> <span dir=\"rtl\">והי׳ הוה</span> and scarcity is permanent. <span class=\"citation\">Y. Hor. III, 48ᶜ</span> top <span dir=\"rtl\">יין בי׳</span> wine is dear; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>nobility, aristocracy</i>. <span class=\"citation\">Sot. IX, 15</span>, a. e.; v. <a href=\"#\" data-headword=\"אָמַר II\"><span dir=\"rtl\">אָמַר</span> II</a>.</div>","alt":[]},"14338":{"h":"יוֹקְרָא","r":"J00234","html":"<div class=\"sense\"><b>1)</b> <i>high price</i>. <span class=\"citation\">Targ. Job XXVIII, 17</span>.</div><div class=\"sense\"><b>—2)</b> <i>weight</i>. <span class=\"citation\">Men. 94ᵇ</span> <span dir=\"rtl\">אגב י׳ דלחם</span> on account of the heavy pressure of the bread.</div><div class=\"sense\"><b>—3)</b> <i>feeling of heaviness;</i> י׳ דְלִבָּא <i>asthma</i>. <span class=\"citation\">Sabb. 140ᵃ</span></div>","alt":[]},"14339":{"h":"יוֹקֶרֶת","r":"J00235","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יוֹדְקֶרֶת\">יוֹדְקֶרֶת</a></div>","alt":[]},"14340":{"h":"יורדא","r":"J00236","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Ez. XXVII, 24</span> <span dir=\"rtl\">דיו׳</span> ed. Lag., read: <span dir=\"rtl\">דִּי וַרְדָּא</span> v. <a href=\"#\" data-headword=\"וְרַד\">וְרַד</a>. [<span class=\"citation\">Targ. Y. Gen. VI, 16</span> ed. pr., read: <a href=\"#\" data-headword=\"יוֹהֲרָא\">יוֹהֲרָא</a>.]</div>","alt":[]},"14341":{"h":"יוֹרְדְּנָא","r":"J00237","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יַרְדְּנָא\">יַרְדְּנָא</a></div>","alt":[]},"14342":{"h":"יוֹרֶדֶת","r":"J00238","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָרַד\">יָרַד</a>) <i>rivulet</i> (cmp. <a href=\"#\" data-headword=\"מוֹרָד I\">מוֹרָד</a>). <span class=\"citation\">Tosef. Par. IX</span> (<span class=\"citation\">VIII), 2</span> <span dir=\"rtl\">י׳ הצלמון</span> the rivulet coming down from Mount Zalmon.</div>","alt":[]},"14343":{"h":"יוֹרֶה I","r":"J00239","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>a soaking rain, early rain</i>. <span class=\"citation\">Sifré Deut. 42</span> (ref. to <span class=\"citation\">Deut. XI, 14</span>) <span dir=\"rtl\">י׳ במרחשון וכ׳</span> <i>yoreh</i> (early rain) is the rain of Marḥeshvan, the late rain (<i>malkosh</i>) in Nisan; <span class=\"citation\">Taan. 5ᵃ</span>. <span class=\"citation\">Ib.</span> (ref. to Mish. <span class=\"citation\">ib. I, 2</span>) <span dir=\"rtl\">י׳ בניסן וכ׳</span> is the <i>yoreh</i> in Nisan? is it not in Marḥeshvan? Ib. 6ᵃ; a. e.—Trnsf. <i>early season, spring</i>. Tanḥ. Ḥayé 6 (ref. to <span class=\"citation\">Koh. XI, 6</span>) <span dir=\"rtl\">אם זרעת בי׳ וכ׳</span> if thou hast sown in the spring &amp;c.; cmp. <a href=\"#\" data-headword=\"בַּכִּיר\">בַּכִּיר</a>.—</div>","alt":[]},"14344":{"h":"יוֹרֶה II","r":"J00240","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"אוּר I\">אוּר</a>, cmp. Syr. <a href=\"#\" data-headword=\"אִירָא\">אירא</a> P. Sm. 167) <i>boiler, kettle</i>. <span class=\"citation\">Ḥull. 108ᵃ</span> <span dir=\"rtl\">י׳ של חלב</span> a kettle of milk. <span class=\"citation\">Ib. 108ᵇ</span> <span dir=\"rtl\">י׳ רותחת</span> a boiling kettle. <span class=\"citation\">Ab. Zar. 76ᵃ</span> <span dir=\"rtl\">י׳ קטנה בתוך י׳ גדולה</span> put a small boiler into a large one filled with water, v. <a href=\"#\" data-headword=\"גָּעַל\">גָּעַל</a>; a. fr.—Esp. <i>the dyer’s kettle, dye</i>. <span class=\"citation\">B. Kam. 99ᵃ</span> top <span dir=\"rtl\">הקדיחו י׳</span> (Ms. H. <span dir=\"rtl\">הקדיחתו</span>) the dye burnt it (the wool); <span class=\"citation\">ib. IX, 4</span> (<span class=\"citation\">100ᵇ</span>) <span dir=\"rtl\">הקדיחתו י׳</span> (v. Rabb. D. S. a. l. note 30); Y. ib. IX, 6ᵈ bot. <span dir=\"rtl\">הקדיחה י׳</span>.—<span class=\"citation\">Ḥag. 15ᵇ</span> (in Chald. dict.) <span dir=\"rtl\">כל עמר דנחית לי׳ סליק</span> does the wool that goes into the kettle always come out sound?, i.e. does every student of mystic philosophy escape death or scepticism?—<span class=\"citation\">Sabb. I, 6</span>; a. e.—Pl. <span dir=\"rtl\">יוֹרוֹת</span>; <span dir=\"rtl\">י׳ הערביים</span> <i>improvised fire places of the Arabs, a cavity in the ground laid out with clay.</i> <span class=\"citation\">Kel. V, 10</span> (ed. Dehr. <span dir=\"rtl\">יוֹרַת</span>). <span class=\"citation\">Men. V, 9</span> (<span class=\"citation\">63ᵃ</span>).</div>","alt":["יוֹרָה"]},"14345":{"h":"יורית","r":"J00241","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Gen. 133</span> Koh. Ar. Compl., v. <a href=\"#\" data-headword=\"יְרִיָיה\">יְרִיָּיה</a></div>","alt":[]},"14346":{"h":"יורכין","r":"J00242","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. Deut. XXXIV, 6</span>, read: <span dir=\"rtl\">יוֹהֲרִין</span> (cmp. <span class=\"citation\">Targ. Esth. I, 4</span>); v. <a href=\"#\" data-headword=\"יוֹהֲרָא\">יוֹהֲרָא</a></div>","alt":[]},"14347":{"h":"יוֹרָם","r":"J00243","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"יְהוֹרָם\">יְהוֹרָם</a></div>","alt":[]},"14348":{"h":"יורם","r":"J00244","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Prov. XVIII, 11</span> some ed., read <span dir=\"rtl\">ירום</span>, v. <a href=\"#\" data-headword=\"רוּם\">רוּם</a>.—<span class=\"citation\">Ib. XXIII, 29</span> <span dir=\"rtl\">יורם קנצן עינוי</span> ed. Lag., Ms. Var. <span dir=\"rtl\">יודמקנען</span>, <span dir=\"rtl\">יודענען</span>, a corrupt. of <span dir=\"rtl\">סומקנות עיינין</span>, v. <a href=\"#\" data-headword=\"סוּמְקָנוּתא\">סוּמְקָנוּתָא</a>.</div>","alt":[]},"14349":{"h":"יוּרְקָא","r":"J00245","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יָרוֹק ²\">יָרוֹקָא</a> a. <a href=\"#\" data-headword=\"יַרְקָא\"><a href=\"#\" data-headword=\"יַרְקָא\">יַרְקָא</a>.</a></div>","alt":[]},"14350":{"h":"*יוּרְקָמִי","r":"J00246","html":"<div class=\"sense\"> (<span dir=\"rtl\">יורקמו</span>, Ar.  pr. n. <i>Yurkami</i>, name of an angel. <span class=\"citation\">Pes. 118ᵃ</span> י׳ שר הברד Y. the chief of the hail storms; <span class=\"citation\">Yalk. Ps. 873</span>; <span class=\"citation\">Midr. Till. to Ps. CXVII</span>.</div>","alt":[]},"14351":{"h":"יוּרְקָנָא","r":"J00247","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יַרְקוֹנָא\">יַרְקוֹנָא</a></div>","alt":[]},"14352":{"h":"יוֹרֵשׁ","r":"J00248","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>heir, successor, heir-at-law</i>. <span class=\"citation\">B. Bath. IX, 2</span> <span dir=\"rtl\">אם אין שם י׳ וכ׳</span> if there is no other heir besides. <span class=\"citation\">Ib. 139ᵃ</span> <span dir=\"rtl\">שויוה רבנן כי׳ … כלוקח</span> the Rabbis gave him the privileges of an heir (to his wife’s property) and those of a purchaser; a. v. fr.—Pl. <span dir=\"rtl\">יוֹרְשִׁים</span>, <span dir=\"rtl\">יוֹרְשִׁין</span>. <span class=\"citation\">Ib. 140ᵃ</span>. <span class=\"citation\">Ib. IX, 9</span> <span dir=\"rtl\">יוֹרְשֵׁי האשה וכ׳</span> the wife’s heirs-at-law claim that the husband died first; a. v. fr.—<i>Fem</i>. <span dir=\"rtl\">יוֹרֶשֶׁת</span>, <i>pl</i>. <span dir=\"rtl\">יוֹרְשׁוֹת</span>. <span class=\"citation\">Ib. 119ᵃ</span> יודע … י׳ הן Moses knew that the daughters of Z. were legal heirs.</div>","alt":[]},"14353":{"h":"יוֹשֶׁן","r":"J00249","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָשָׁן\">יָשָׁן</a>) <i>former condition, original usage</i> (cmp. <a href=\"#\" data-headword=\"אֵיתָן\">אֵיתָן</a>). <span class=\"citation\">Snh. 19ᵃ</span> <span dir=\"rtl\">החזיר … הדבר ליוֹשְׁנוֹ</span> restored the usage to its original state; Y. ib. II, 20ᵃ bot.; <span class=\"citation\">Y. Ber. III, 6ᵇ</span> <span dir=\"rtl\">חזרו הדברים ליוֹשְׁנָן</span>; <span class=\"citation\">Keth. 8ᵇ</span> <span dir=\"rtl\">החזירו הדבר ליוֹשְׁנוֹ</span> (not <span dir=\"rtl\">ליושנה</span>). <span class=\"citation\">Kidd. 66ᵃ</span> <span dir=\"rtl\">עד שבא … והחזיר את התורה ליוֹשְׁנָהּ</span> until Simon b. Sh. came and restored the Law to its former authority. <span class=\"citation\">Yoma 69ᵇ</span>, v. <a href=\"#\" data-headword=\"עֲטָרָה\">עֲטָרָה</a>; <span class=\"citation\">Y. Ber. VII, 11ᶜ</span>; a. e.</div>","alt":[]},"14354":{"h":"יוֹשֶׁר","r":"J00250","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>straightness, equity</i>. Ruth R. introd. <span dir=\"rtl\">במדת י׳</span> in equity, v. <a href=\"#\" data-headword=\"יַשְׁרוּת\">יַשְׁרוּת</a>.</div>","alt":[]},"14355":{"h":"יוֹתָא","r":"J00251","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אָתָא III\"><span dir=\"rtl\">אָתָא</span> III</a></div>","alt":[]},"14356":{"h":"יוֹתָם","r":"J00252","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Jotham</i>, king of Judah. <span class=\"citation\">Succ. 45ᵇ</span></div>","alt":[]},"14357":{"h":"יוּתָּן","r":"J00253","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נָתַן\">נָתַן</a></div>","alt":["כִּי י׳"]},"14358":{"h":"יוֹתְפָאָה","r":"J00254","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יוֹדְפָת\">יוֹדְפָת</a></div>","alt":[]},"14359":{"h":"יוֹתֵר","r":"J00255","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>much;</i> (followed by <span dir=\"rtl\">מ־</span>, or <span dir=\"rtl\">מ־</span> implied) <i>more</i>. <span class=\"citation\">Y. Ber. IV, 7ᵈ</span> top <span dir=\"rtl\">בן תורה י׳ ממני</span> a greater scholar than I am. <span class=\"citation\">Keth. 86ᵃ</span>, a. e. <span dir=\"rtl\">י׳ ממה שהאיש וכ׳</span> more than man desires to marry, does woman desire to be married. <span class=\"citation\">Pes. 112ᵃ</span> <span dir=\"rtl\">י׳ ממה שהעגל וכ׳</span> more auxious than the calf is to suck, is the cow to nurse, i.e. the teacher is more anxious to teach than the pupil to learn. <span class=\"citation\">M. Kat. 27ᵇ</span> <span dir=\"rtl\">י׳ מדאי</span> more than enough, <span dir=\"rtl\">י׳ מכשיעור</span> more than the proper measure, <i>too much;</i> a. v. fr.—<a href=\"#\" data-headword=\"בִּרְיְתָא\">בי׳</a> a) <i>in a higher degree, especially</i>. <span class=\"citation\">Sifré Deut. 31</span> <span dir=\"rtl\">עלינו הוחל שמו בי׳</span> upon us especially has His name been made to rest. <span class=\"citation\">Lev. R. s. 14</span> <span dir=\"rtl\">ובי׳ אם היה זכר</span> and especially so when it is a male; a. e.—b) <i>for a higher price, above market value</i>. <span class=\"citation\">Ned. III, 11</span>; a. e.—V. <a href=\"#\" data-headword=\"יֶתֶר I\">יֶתֶר</a>.</div>","alt":[]},"14360":{"h":"יוֹתִר","r":"J00256","html":"<div class=\"sense\"><span class=\"citation\">Targ. Ruth I, 13</span>. <span class=\"citation\">Ib. III, 12</span> (ed. Lag. <a href=\"#\" data-headword=\"יָתֵר\">יָתֵר</a>).</div>","alt":[]},"14361":{"h":"יוּתְרָן","r":"J00257","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"יִתְרוֹן\">יִתְרוֹן</a>, <i>advantage, profit</i>. <span class=\"citation\">Targ. Prov. XXVIII, 3</span> (ed. Wil. <a href=\"#\" data-headword=\"יִתְרָן\">יִתְרָן</a>). <span class=\"citation\">Ib. XIV, 23</span>. <span class=\"citation\">Ib. XXI, 5</span>.</div>","alt":["יוּתְרָנָא"]},"14362":{"h":"יוֹתֶרֶת","r":"J00258","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>the large lobe of the liver</i>. Sifra Vayikra, N’dabah, ch. XVII, Par. 14; <span class=\"citation\">Yalk. Lev. 462</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>an additional limb</i> or <i>lobe</i>, v. <a href=\"#\" data-headword=\"יְתֶרֶת\">יְתֶרֶת</a>.</div>","alt":[]},"14363":{"h":"יְזוּפְתָּא","r":"J00259","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"*יָזַף\">יְזַף</a>) <i>a loan</i>. <span class=\"citation\">M. Kat. 28ᵇ</span> (Ms. M. <a href=\"#\" data-headword=\"יְזוּפְתָּא\">יְזִפְ׳</a>, v. Rabb. D. S. a. l. note); v. <a href=\"#\" data-headword=\"*אַוְורָא\">אַוְורָא</a>.</div>","alt":["יְזִיפְ׳"]},"14364":{"h":"יְזִיף","r":"J00260","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*יָזַף\">יְזַף</a></div>","alt":[]},"14365":{"h":"יָזַן","r":"J00261","html":"<div class=\"sense\">, <i>Pi</i>. <span dir=\"rtl\">יִוֵּן</span> (denom. of <a href=\"#\" data-headword=\"זַן\">זַן</a>) <i>to supply with all kinds and assort</i>.—Part. pass. f. <span dir=\"rtl\">מְיוּזֵּנֶת</span> <i>well supplied and assorted</i>. <span class=\"citation\">Gitt. 67ᵃ</span>, v. <a href=\"#\" data-headword=\"חָנוּת\">חָנוּת</a>.</div>","alt":[]},"14366":{"h":"יָזַע","r":"J00262","html":"<div class=\"sense\">, <i>Hif.</i> הִזִּיעַ <i>to sweat</i>, v. <a href=\"#\" data-headword=\"זוּעַ\">זוּעַ</a>.</div>","alt":[]},"14367":{"h":"*יָזַף","r":"J00263","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"זוּף\">זוּף</a>) [<i>to join</i>; cmp. <a href=\"#\" data-headword=\"לָוָה\">לָוָה</a>,] <i>to borrow</i>.</div><div class=\"sense\"><b>Hif. הוֹזִיף</b> <div class=\"sense\"><i>to lend</i>. <span class=\"citation\">Sot. 48ᵇ</span> המוֹזִיף Ar. (not found in ed.), v. <a href=\"#\" data-headword=\"טוּלְמָא I\"><span dir=\"rtl\">טוּלְמָא</span> I</a>.</div></div>","alt":[]},"14368":{"h":"יִזַף","r":"J00264","html":"<div class=\"sense\"><b>1)</b> <i>to borrow</i>. <span class=\"citation\">Targ. O. Deut. XV, 6</span>; <span class=\"citation\">ib. XXVIII, 12</span> <span dir=\"rtl\">תְזִיף</span> (some ed. <span dir=\"rtl\">תְזוּף</span>); Y. ib. <span dir=\"rtl\">למֵיזוֹף</span>.—Part. <a href=\"#\" data-headword=\"יְזִיף\">יָזֵיף</a>. <span class=\"citation\">Targ. II Kings IV, 1</span> (ed. Lag. <span dir=\"rtl\">מוֹזִיף</span> <i>Af</i>.).—<span class=\"citation\">B. Mets. 64ᵃ</span> <span dir=\"rtl\">כי יְזִיף וכ׳</span> if this man shall borrow money of thee. <span class=\"citation\">Kidd. 20ᵃ</span> <span dir=\"rtl\">ולא נֵיזִיף וכ׳</span> (some ed. <span dir=\"rtl\">נוֹזִיף</span>, v. infra) rather than borrow on interest. <span class=\"citation\">Erub. 65ᵃ</span> הוה י׳ ופרע Ms. M. (v. Rabb. D. S. a. l.) borrowed and paid off (made up by night for neglect of study by day). <span class=\"citation\">Taan. 12ᵇ</span> לֵיזוֹף מר וכ׳ Ms. M. (ed. <span dir=\"rtl\">לוֹזִיף</span>) borrow and pay back (postpone your fast for another day); a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to lend</i>. <span class=\"citation\">Targ. Y. Deut. XV, 2</span> <span dir=\"rtl\">דְּיִזּוֹף ב־</span>.—<span class=\"citation\">Sabb. 119ᵃ</span> <span dir=\"rtl\">מאן דיזיף שבתא וכ׳</span> (Ms. M. <span dir=\"rtl\">לשב׳</span>, Buxt. <span dir=\"rtl\">דיוֹזִיף</span>) him who lends to the Sabbath (incurring an additional expense in honoring the Sabbath), the Sabbath will repay; <span class=\"citation\">Yalk. Gen. 16</span>; <span class=\"citation\">Yalk. Is. 356</span>.</div><div class=\"sense\"><b>Af. אוֹזִיף</b> <div class=\"sense\"><b>1)</b> <i>to borrow</i>. <span class=\"citation\">Targ. Ps. XXXVII, 21</span>.—<span class=\"citation\">B. Bath. 32ᵇ</span> <span dir=\"rtl\">הדרת אוֹזַפְתִּינְהוּ מינאי</span> (Rashb. <span dir=\"rtl\">הדר יזפתינהו</span>, Ms. M. <span dir=\"rtl\">שקלתינהו</span>) thou hast borrowed it again of me. <span class=\"citation\">B. Mets. 63ᵇ</span> <span dir=\"rtl\">האי מאן דאו׳ וכ׳</span> (Ms. H. <span dir=\"rtl\">דיזיף</span>) if one borrowed &amp;c. <span class=\"citation\">Kidd. 20ᵃ</span>; <span class=\"citation\">Taan. 12ᵇ</span>, v. supra.—<span class=\"citation\">Lam. R. to I, 2</span> <span dir=\"rtl\">אוֹזְפִיתוּן</span>, v. <a href=\"#\" data-headword=\"חוֹבָא\">חוֹבָא</a>.—<span class=\"citation\">Lev. R. s. 3</span> beg. <span dir=\"rtl\">דיוֹזִיף וכ׳</span> some ed. he who borrows on interests.</div><div class=\"sense\"><b>—2)</b> <i>to lend</i>. <span class=\"citation\">Targ. O. Deut. XV, 6</span>. <span class=\"citation\">Ib. 8</span> <span dir=\"rtl\">אוֹזָפָא תּוֹזְפִינֵּיה</span> (Y. <span dir=\"rtl\">מוּזְפָא תּוּז׳</span>). Ib. XXVIII, 12; a. e.—<span class=\"citation\">Targ. Prov. XIX, 17</span> נְיוֹזִיף Ms. (ed. <a href=\"#\" data-headword=\"נְזַף\">נְזִיף</a>).—<span class=\"citation\">Bekh. 8ᵇ</span> <span dir=\"rtl\">גברא דאו׳ וטרף דהדר מוֹזִיף …</span> he who once lent money and had to resort to seizing (v. <a href=\"#\" data-headword=\"טְרַף I\"><span dir=\"rtl\">טְרַף</span> I</a>), why does he lend again?; a. e.</div></div>","alt":["זִיף","(זוּף)"]},"14369":{"h":"יַזְפָא","r":"J00265","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יִזַף\">preced.</a>) <i>debtor</i>. <span class=\"citation\">Targ. Is. XXIV, 2</span>.—V <a href=\"#\" data-headword=\"יוֹזִיף\">יוֹזִיף</a>.</div>","alt":[]},"14370":{"h":"יָזֵק","r":"J00266","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><b>1)</b> <i>Yazek</i>, name of a Babylonian river or channel. Y. Kidd. IV, 65ᵈ top; Bab. <span class=\"citation\">Kidd. 71ᵇ</span> <a href=\"#\" data-headword=\"עָזַק\">עָזֵק</a>; Y. Yeb. I, 3ᵇ top <a href=\"#\" data-headword=\"זְרוֹק\">זרוק</a>.</div><div class=\"sense\"><b>—2)</b>  <span dir=\"rtl\">בית י׳</span>, v. <a href=\"#\" data-headword=\"יַעְזֵק\">יַעֲזֵק</a></div>","alt":[]},"14371":{"h":"יְחָא","r":"J00267","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יְחִי\">יְחִי</a></div>","alt":[]},"14372":{"h":"יָחַד","r":"J00268","html":"<div class=\"sense\">, <i>Pi</i>. <span dir=\"rtl\">יִחֵד</span>, <span dir=\"rtl\">יִיחֵד</span> (b. h.; v. <a href=\"#\" data-headword=\"אֶחָד\">אֶחָד</a>) </div><div class=\"sense\"><b>1)</b> <i>to unite, concentrate</i>. <span class=\"citation\">Y. Ber. IV, 7ᵈ</span> bot. <span dir=\"rtl\">ותְיַיחֵד לבבינו וכ׳</span> and concentrate our hearts (inclinations) to fear thy Name.</div><div class=\"sense\"><b>—2)</b>  (with <span dir=\"rtl\">על</span>) <i>to confer a distinction, name</i> &amp;c. <span class=\"citation\">Gen. R. s. 68</span> <span dir=\"rtl\">אברהם י׳ … שמו עליו</span> on Abraham did the Lord confer His Name (<span class=\"citation\">Gen. XXVI, 24</span>, a. e.). Ib. <span dir=\"rtl\">ידע שהקב&quot;ה מְיַחֵד שמו עליו</span> he inferred that the Lord would confer His Name upon him (to be called ‘the God of Jacob’). Mekh. Mishp. s. 20 <span dir=\"rtl\">על ישראל י׳ שמו ביותר</span> (although the Lord of the universe) He conferred His Name particularly on Israel (v. <a href=\"#\" data-headword=\"יוֹתֵר\">יוֹתֵר</a>); a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to declare the unity of God, to recite Sh’ma</i> (<span class=\"citation\">Deut. VI, 4</span>). <span class=\"citation\">Gen. R. s. 20</span> <span dir=\"rtl\">אנו … ומְיַחֲדִים שמו וכ׳</span> we trust in Him and profess His unity &amp;c. <span class=\"citation\">Cant. R. to II, 16</span> <span dir=\"rtl\">ואני מְיַחֶדֶת שמו וכ׳</span> and I (Israel) profess the unity of His name twice every day, (saying) Hear, O Israel &amp;c.; a. fr.</div><div class=\"sense\"><b>—4)</b> <i>to single out, select, designate</i>. <span class=\"citation\">Snh. 57ᵃ</span> <span dir=\"rtl\">שיי׳ שפחה לעבדו</span> who designated a handmaid (as a wife) for his slave. <span class=\"citation\">Lev. R. s. 12</span> <span dir=\"rtl\">ויי׳ אליו הדבור וכ׳</span> addressed the command to him exclusively (<span class=\"citation\">Lev. X, 8</span>); a. e.—<span class=\"citation\">Yoma 11ᵇ</span> (ref. to <span class=\"citation\">Lev. XIV, 35</span>) <span dir=\"rtl\">מי שמְיַיחֵד ביתו לו וכ׳</span> he who devotes his household exclusively to himself, and is unwilling to lend his vessels &amp;c.; <span class=\"citation\">Arakh. 16ᵃ</span> <span dir=\"rtl\">שמיוחד</span> (v. infra); <span class=\"citation\">Yalk. Lev. 564</span>.—5) <i>to leave persons alone in a special room, to arrange a private meeting for</i>. <span class=\"citation\">Keth. 12ᵃ</span>; <span class=\"citation\">Tosef. ib. I, 4</span>; Y. ib. I, 25ᵃ bot. <span dir=\"rtl\">היו מְיַיחֲדִין וכ׳</span> they used to leave bride and groom in a private room alone for a while.—<i>Part. pass</i>. <span dir=\"rtl\">מְיוּחָד</span>, f. <span dir=\"rtl\">מְיוּחֶדֶת</span>; pl. <span dir=\"rtl\">מְיוּחָדִים</span>, <span dir=\"rtl\">מְיוּחָדִין</span>, <span dir=\"rtl\">מְיוּחָדוֹת</span> a) <i>especial, particular, designated; chosen, distinguished</i> (v. <a href=\"#\" data-headword=\"יָחִיד\">יָחִיד</a>). <span class=\"citation\">Snh. 60ᵃ</span>, a. e. <span dir=\"rtl\">שם המי׳</span> the proper Name of the Lord (Jehovah).—<span class=\"citation\">Yoma 11ᵃ</span> ביתך ביתך המי׳ לך ‘<i>thy</i> house’ (<span class=\"citation\">Deut. VI, 9</span>; <span class=\"citation\">XI, 20</span>), thy house which is designated for thy personal use. Ib.ᵇ מה בית מ׳ לדירה <i>bayith</i> means a room designated for a dwelling, <span dir=\"rtl\">יצאו אלו שאינן מי׳ לדירה</span> to the exclusion of those rooms (gate lodge &amp;c.) which are not designated for dwellings. Arakh. l. c. <span dir=\"rtl\">מי׳ לו</span> devoted to his own exclusive use, v. supra; a. fr.—<span class=\"citation\">Gen. R. s. 99</span>, end (ref. to <span dir=\"rtl\">כאחד</span>, <span class=\"citation\">Gen. XLIX, 16</span>) <span dir=\"rtl\">כמי׳ שבשבטים</span> like the most distinguished among the tribes. <span class=\"citation\">Yeb. 62ᵃ</span> אני שמ׳ לדבור בכל וכ׳ I (Moses) who am singled out (must be prepared) for divine communication every hour; <span class=\"citation\">Ab. d’R. N., II</span> Vers., ch. II (ed. Schechter, p. 10) <span dir=\"rtl\">שאני כלי מי׳</span> who am a special vessel (of revelation). <span class=\"citation\">Meïl. 15ᵃ</span> <span dir=\"rtl\">קדשים המי׳ לה׳</span> sanctified things which are exclusively dedicated to the Lord; Sifra Vayikra, Ḥobah, Par. 11, ch. XX.—Ib. Sh’mini, ch. II, Par. 2 <span dir=\"rtl\">כבשים ועזים המי׳</span> lambs and goats which are specified (<span class=\"citation\">Deut. XIV, 4</span>); a. fr.—b) <i>locked up with</i>. <span class=\"citation\">Num. R. s. 9</span> <span dir=\"rtl\">בזמן שהאשה מי׳ עם וכ׳</span> when a wife is locked up with her husband.</div><div class=\"sense\"><b>Hithpa. הִתְיַיחֵד</b> <div class=\"sense\">, <i>Nithpa</i>. <span dir=\"rtl\">נִתְיַיחֵד</span> </div><div class=\"sense\"><b>1)</b> <i>to be conferred</i> (with <span dir=\"rtl\">על</span>); <i>to be especially addressed</i> (with <span dir=\"rtl\">אל</span>). <span class=\"citation\">Ex. R. s. 7</span> <span dir=\"rtl\">היה ראוי … להִתְיַיחֵד עליו וכ׳</span> the divine communication was to bear his name alone. <span class=\"citation\">Lev. R. s. 12</span> <span dir=\"rtl\">נתי׳ אליו הדבור</span> the divine communication was addressed to him especially; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to be alone with, to be closeted with</i>. <span class=\"citation\">Kidd. IV, 12</span> <span dir=\"rtl\">לא יִתְיַיחֵד אדם וכ׳</span> a man must not be alone (even) with two women, but one woman <span dir=\"rtl\">מִתְיַיחֶדֶת וכ׳</span> may be alone with two men. <span class=\"citation\">Ab. Zar. II, 1</span>. <span class=\"citation\">Tosef. Gitt. VII</span> (<span class=\"citation\">V), 4</span>; a. fr.—V. <a href=\"#\" data-headword=\"יִחוּד\">יִחוּד</a>.</div></div>","alt":[]},"14373":{"h":"יְחַד","r":"J00269","html":"<div class=\"sense\">, <i>Pa</i>. <a href=\"#\" data-headword=\"יָחַד\">יַחֵד</a> ch. same, </div><div class=\"sense\"><b>1)</b> <i>to concentrate</i>. <span class=\"citation\">Targ. Ps. LXXXVI, 11</span>.—<i>Part. pass</i>. <span dir=\"rtl\">מְיַחַד</span> <i>united, harmonious</i>. <span class=\"citation\">Targ. Y. Ex. XIX, 2</span> (cmp. <a href=\"#\" data-headword=\"הוֹמוֹנְיָא\">הוֹמוֹנְיָא</a>).</div><div class=\"sense\"><b>—2)</b> <i>to specify, single out, designate</i>. <span class=\"citation\">Macc. 18ᵃ</span> ליַחוּדֵי לאוי וכ׳ Ms. M. (ed. <span dir=\"rtl\">לי׳ להו</span>) to forbid each of these acts singly (as if each were prohibited by a special prohibitory law, v. <a href=\"#\" data-headword=\"לַאו\">לַאו</a>).—<i>Part. pass</i>. <span dir=\"rtl\">מְיָחַד</span> = h. <span dir=\"rtl\">מְיוּחָד</span> (v. <a href=\"#\" data-headword=\"יָחַד\">preced.</a>). <span class=\"citation\">Targ. O. Gen. XXVI, 10</span> <span dir=\"rtl\">דמְיָ׳ בעמא</span> ed. Berl. (oth. ed. <span dir=\"rtl\">מְיָחֵיד</span>; Y. <span dir=\"rtl\">מלכא דמֵיחַד</span>) a distinguished person of the people. <span class=\"citation\">Targ. Y. Lev. XV, 20</span>; <span class=\"citation\">22</span> <span dir=\"rtl\">מְיַיחֵד</span> designated; a. e.</div><div class=\"sense\"><b>Ithpa. אִתְיַיחֵד</b> <div class=\"sense\">, contr. <a href=\"#\" data-headword=\"יְעַד\">אִיַּיחֵד</a> <i>to be joined; to be locked up</i>. <span class=\"citation\">Targ. Y. I Gen. XLIX, 6</span>. <span class=\"citation\">Targ. Job. III, 6</span>.—<span class=\"citation\">Targ. Y. II, Num. XXXI, 50</span>.—<span class=\"citation\">Snh. 37ᵃ</span> <span dir=\"rtl\">שרי לִיַּיחוּדֵי וכ׳</span> is permitted to be closeted up with her husband.</div></div>","alt":[]},"14374":{"h":"יִחוּד","r":"J00270","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יְחַד\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b> <i>private meeting</i>, esp. <i>privacy between man and woman</i>. <span class=\"citation\">Y. Keth. XI, beg. 34ᵃ</span> <span dir=\"rtl\">דברים של יי׳</span> private attendance, e.g. assistance at washing and ointing. <span class=\"citation\">Y. Sot. I, 16ᶜ</span> top <span dir=\"rtl\">אין זה י׳</span> this is no ascertained private meeting (with her former husband, on account of which a second letter of divorce would be required). <span class=\"citation\">Snh. 21ᵃ</span>, sq. <span dir=\"rtl\">גזרו על הי׳ ועל וכ׳</span> they forbade privacy (with a married woman) and with a single woman. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">י׳ דאורייתא הוא</span> is not privacy with a married woman biblically interdicted?—<span class=\"citation\">Kidd. 81ᵃ</span> <span dir=\"rtl\">מלקין על הי׳ … משום הי׳</span> we punish private meetings between a man and a woman, but we do not prohibit the wife to her husband on account of her private meeting with a man. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בעלה בעיר אין חוששין משום י׳</span> if her husband is in town, we do not consider her private meeting with a man a suspicious act; a. fr.—<span dir=\"rtl\">בְּיִ׳</span> a) <i>privately</i>. <span class=\"citation\">Bets. 22ᵇ</span>; <span class=\"citation\">Pes. 37ᵃ</span> שאילית את רבי בי׳ I asked my teacher privately.—b) <i>particularly, exactly; by a special sign.</i> <span class=\"citation\">Shek. VI, 2</span>; <span class=\"citation\">Yoma 54ᵃ</span></div><div class=\"sense\"><b>—2)</b>  (later Hebr.) <span dir=\"rtl\">י׳ השם</span> <i>declaration of the unity of God</i>. Pesik. Zutr., Nitsabim, end.—[<span class=\"citation\">Gen. R. s. 99</span>, end <span dir=\"rtl\">כיחודו של עולם</span>, read: <span dir=\"rtl\">כיחידוֹ</span>, v. <a href=\"#\" data-headword=\"יָחִיד\">יָחִיד</a>.]</div>","alt":["יִיחוּד"]},"14375":{"h":"יִחוּד ²","r":"J00271","html":"<div class=\"sense\">, esp. <i>profession of the unity of God, Jewish religion</i>. <span class=\"citation\">Targ. Lam. III, 28</span>. <span class=\"citation\">Targ. Cant. VIII, 9</span> <span dir=\"rtl\">למקני י׳ וכ׳</span> to buy the permission to profess the Jewish religion.</div>","alt":["יִחוּדָא","יִי׳"]},"14376":{"h":"יִחוּל","r":"J00272","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָחַל\">יָחַל</a>) <i>hope</i>. <span class=\"citation\">Ber. 16ᵇ</span>; Y. ib. IV, 7ᵈ bot. <span dir=\"rtl\">ונמצא י׳ לבבינו</span> that we may obtain what our heart longs for.</div>","alt":["יִי׳"]},"14377":{"h":"יִחוּס","r":"J00273","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָחַס\">יָחַס</a>) <i>genealogy, pedigree</i> (v. <a href=\"#\" data-headword=\"יוֹחָס\">יוֹחָס</a>). <span class=\"citation\">Num. R. s. 13</span> <span dir=\"rtl\">לכן הוא מונה שם יִחוּסָם</span> therefore the Scripture records there (<span class=\"citation\">Ex. VI, 14</span> sq.) their genealogy; a. e.—[<span class=\"citation\">Y. Gitt. VIII, 49ᶜ</span> bot. <span dir=\"rtl\">יי׳ כהונה</span>, v. <a href=\"#\" data-headword=\"זִיהוּם\">זִיהוּם</a>.—<span class=\"citation\">Y. Yeb. II, 4ᵃ</span> top, v. <a href=\"#\" data-headword=\"יַחַס\">יַחַס</a>.]—Pl. <span dir=\"rtl\">יִחוּסִים</span>, <span dir=\"rtl\">יִחוּסִין</span>, <a href=\"#\" data-headword=\"יִחוּד ²\">יִי׳</a>. Num. R. l. c. <span dir=\"rtl\">שמרו יִחוּסֵיהֶם</span> they preserved their genealogical records; <span class=\"citation\">Cant. R. to IV, 7</span>. <span class=\"citation\">Gen. R. s. 37</span> <span dir=\"rtl\">הראשונים … יִיחוּסֵיהֶם וכ׳</span> as regards former generations whose genealogies were known, their names were published in connection with historical events; <span dir=\"rtl\">אנו יִיחוּסֵינוּ וכ׳ …</span> but with us who do not know our records, our names are defined by those of our fathers; (<span class=\"citation\">Yalk. Gen. 62</span> <span dir=\"rtl\">יִחוּסֵהֶן</span>, <span dir=\"rtl\">יִחוּסֵנוּ</span> sing.); Yalk. Chr. 1074.</div>","alt":["יִי׳"]},"14378":{"h":"יֵחוּס","r":"J00274","html":"<div class=\"sense\">; also <i>family</i> (<i>gens</i>). <span class=\"citation\">Targ. Y. Gen. V, 1</span>. <span class=\"citation\">Ib. XXIV, 38</span>; <span class=\"citation\">40</span>, sq. <span class=\"citation\">Ib. XLIII, 7</span>; a. e.—<span class=\"citation\">Kidd. 71ᵇ</span> <span dir=\"rtl\">שתיקותיה דבבל היינו יי׳</span> (v. marginal vers.) silence of a Babylonian (in case of an offered insult) is a sign of good descent; v. <a href=\"#\" data-headword=\"יַחֲסוּתָא\">יַחֲסוּתָא</a>.—Pl. <span dir=\"rtl\">יֵחוּסִין</span>, <span dir=\"rtl\">יֵחוּסַיָּא</span>, <a href=\"#\" data-headword=\"יֵחוּס\">יֵי׳</a>. <span class=\"citation\">Targ. Y. Gen. VI, 9</span>. <span class=\"citation\">Targ. Y. Ex. VI, 14</span>. <span class=\"citation\">Targ. Job. XXXI, 34</span> Ms. Var. (ed. <a href=\"#\" data-headword=\"גְּנִיסְתָּא\">גְּנִיסָתָא</a>).</div>","alt":["יֵחוּסָא","יֵי׳"]},"14379":{"h":"יְחוּסָא","r":"J00275","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יֵחוּס\">preced.</a>) <i>noble</i>.—Pl. constr. <span dir=\"rtl\">יְחוּסֵי</span>. <span class=\"citation\">Targ. Ps. XCVI, 7</span> (some ed. <span dir=\"rtl\">יֵחוּ׳</span>, v. <a href=\"#\" data-headword=\"יֵחוּס\">preced.</a>)</div>","alt":[]},"14380":{"h":"יִחוּף","r":"J00276","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָחֵף I\">יָחַף</a>) <i>bare-footedness, homelessness</i>. <span class=\"citation\">Yoma 77ᵃ</span> (ref. to <span class=\"citation\">Jer. II, 25</span>) <span dir=\"rtl\">מנעי … לידי י׳</span> keep off from sin, in order that thy foot may not be reduced to bareness (exile); <span class=\"citation\">Yalk. Jer. 266</span> <span dir=\"rtl\">לידי יַחַף</span>.</div>","alt":["יִי׳"]},"14381":{"h":"יָחוֹפָה","r":"J00277","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יִחוּף\">preced.</a>) <i>bare-footed, homeless</i>. <span class=\"citation\">Lam. R. to I, 7</span> <span dir=\"rtl\">כד י׳ ברא וכ׳</span> (some ed. <a href=\"#\" data-headword=\"יְחֵיפָה\">יְחֵיפָה</a>) when the son is homeless (foot-sore), he remembers the comforts of his paternal home.</div>","alt":[]},"14382":{"h":"יִחוּר","r":"J00278","html":"<div class=\"sense\"> (<span dir=\"rtl\">יחר</span>, cmp. <span dir=\"rtl\">אחר</span>, a. <a href=\"#\" data-headword=\"חֲלִיפִים\">חֲלִיפִין</a>) <i>a young shoot</i>, esp. of a fig-tree. <span class=\"citation\">Kil. I, 8</span>. <span class=\"citation\">Ukts. III, 8</span>; <span class=\"citation\">Ḥull. 128ᵇ</span>. <span class=\"citation\">Y. Maasr. II, 49ᵈ</span> top <span dir=\"rtl\">כיי׳ שהוא נוטה וכ׳</span> like a shoot (of a fig-tree) hanging over into a court (ref. to Mish. <span class=\"citation\">Maasr. III, 10</span>); a. e.—Pl. <span dir=\"rtl\">יִחוּרִים</span>, <a href=\"#\" data-headword=\"יִחוּד ²\">יִי׳</a>. <span class=\"citation\">Gen. R. s. 31</span>, end … <span dir=\"rtl\">הכניס עמו י׳ לתאנים</span> he (Noah) took with him … shoots for the preservation of fig-trees; ib. s. 36 <span dir=\"rtl\">י׳ של תאנה</span>. <span class=\"citation\">Y. B. Kam. VI, 5ᵇ</span> bot. <span dir=\"rtl\">יִיחוּרֵי תאנים</span>; Bab. <span class=\"citation\">B. Kam. 59ᵃ</span> <span dir=\"rtl\">יִח׳</span>.</div>","alt":["יִיחוּר"]},"14383":{"h":"יְחֶזְקֵאל","r":"J00279","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Ezekiel</i>, </div><div class=\"sense\"><b>1)</b>  the prophet. <span class=\"citation\">Snh. 39ᵃ</span>, v. <a href=\"#\" data-headword=\"יָסַר\">יָסַר</a>. <span class=\"citation\">Ḥag. 13ᵇ</span> <span dir=\"rtl\">למה י׳ דומה לבן וכ׳</span> to whom is Ez. to be compared? To a villager that saw the king; a. fr.—<span dir=\"rtl\">ספר י׳</span> the Book of Ezekiel. Ib.ᵃ; <span class=\"citation\">Sabb. 13ᵇ</span>, v. <a href=\"#\" data-headword=\"גָּנַז\">גָּנַז</a>; <span class=\"citation\">Men. 45ᵃ</span>; a. e.</div><div class=\"sense\"><b>—2)</b>  Ez., the father of R. Judah, v. <a href=\"#\" data-headword=\"יְהוּדָה\">יְהוּדָה</a>. <span class=\"citation\">Kidd. 70ᵃ</span></div>","alt":[]},"14384":{"h":"יָחַט","r":"J00280","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"חִטָּא I\">חטא</a>); <i>Hif.</i> הוֹחִיט <i>to fail, miscarry</i>. Y’lamd. to B’resh., (quot. in Ar. s. v. <span dir=\"rtl\">מחט</span>) <span dir=\"rtl\">לא היתה … מוֹחֶטֶת</span> none of them miscarried.</div>","alt":[]},"14385":{"h":"יְחַט","r":"J00281","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָחַט\">preced.</a>) <i>abortion</i>. <span class=\"citation\">Targ. Is. XIV, 19</span> <span dir=\"rtl\">כיחט</span> ed. Lag. (oth. ed. <span dir=\"rtl\">כי חט</span>, corr. acc.; Var. <span dir=\"rtl\">כיהט</span>).—Pl. <span dir=\"rtl\">יַחְטַיָּיה</span>. <span class=\"citation\">Y. Nidd. III, 51ᵃ</span> <span dir=\"rtl\">אילין להטייה וכ׳</span> (corr. acc.) the abortions come out first.</div>","alt":[]},"14386":{"h":"יַחֲטָא","r":"J00282","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יְחַט\">preced.</a> wds.) <i>searcher of sin, accuser</i>. <span class=\"citation\">Targ. Zech. III, 1</span>; <span class=\"citation\">ib. 2</span> (ed. Lag. <a href=\"#\" data-headword=\"חִטָּא I\">חטא</a>, v. ib. p. XLII<sup>3</sup>), v. <a href=\"#\" data-headword=\"חֲטָאָה\">חֲטָאָה</a>.</div>","alt":["יַחָטָא"]},"14387":{"h":"יְחִי","r":"J00283","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"חיי\">חיי</a>), <i>Af.</i> אוֹחִי <i>to hurry, press on</i>. <span class=\"citation\">Targ. Ex. X, 16</span>. <span class=\"citation\">Targ. Esth. VI, 10</span>. <span class=\"citation\">Targ. O. Gen. XVIII, 6</span> <span dir=\"rtl\">אוֹחָאִי</span> ed. Berl. (ed. <span dir=\"rtl\">אוֹחִי</span>, Y. <span dir=\"rtl\">אוֹחָא</span>). <span class=\"citation\">Targ. Ex. XII, 33</span>. <span dir=\"rtl\">לאוֹחָאָה</span>; a. fr.—Part. <span dir=\"rtl\">מוֹחִי</span>, <a href=\"#\" data-headword=\"מַוְוחֵי\">מַוְוחֵי</a>; f. <span dir=\"rtl\">מוֹחֲיָיא</span>. <span class=\"citation\">Targ. Prov. XXII, 29</span> (ed. Wil. <a href=\"#\" data-headword=\"מַוְהֵי\">מַוְהֵי</a>). <span class=\"citation\">Targ. Zeph. III, 1</span>; a. fr.</div>","alt":[]},"14388":{"h":"יָחִיד","r":"J00284","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>only, single, individual</i>. <span class=\"citation\">Gen. R. s. 99</span>, end (ref. to <span dir=\"rtl\">כאחד</span>, <span class=\"citation\">Gen. XLIX, 16</span>) <span dir=\"rtl\">כִּיחִידוֹ של וכ׳</span> (not <span dir=\"rtl\">כיחודו</span>) like the Only One of the world, as He needs no help &amp;c.; ib. s. 21 (ref. to <span dir=\"rtl\">כאחד</span>, ib. III, 22). Ib. s. 55 <span dir=\"rtl\">זה י׳ לאמו וכ׳</span> this one (Ishmael) is the only son of his mother, and the other (Isaac) is &amp;c.—<span class=\"citation\">Taan. 9ᵃ</span> <span dir=\"rtl\">בשביל י׳</span> for an individual’s sake, opp. <span dir=\"rtl\">רבים</span>. <span class=\"citation\">Ber. 9ᵃ</span>, a. fr. <span dir=\"rtl\">י׳ ורבים הלכה וכ׳</span> where a single opinion is opposed to the opinion of more than one, the law follows the latter. <span class=\"citation\">Bets. V, 5</span> <span dir=\"rtl\">בור של י׳</span> a well belonging to an individual. <span class=\"citation\">Erub. 46ᵃ</span> <span dir=\"rtl\">י׳ במקום י׳</span> an individual opinion opposed to an individual opinion; a. v. fr.—<span class=\"citation\">Y. Keth. VII, 31ᵇ</span> bot. <span dir=\"rtl\">בְּיָ׳</span> (= <span dir=\"rtl\">בְּיִחוּד</span>) <i>privately</i>.—Pl. <a href=\"#\" data-headword=\"יְחִידִי\">יְחִידִים</a>, <a href=\"#\" data-headword=\"יְחִידִי\">יְחִידִין</a>. <span class=\"citation\">R. Hash. 17ᵇ</span> <span dir=\"rtl\">כי׳ דמי</span> are to be considered as individuals (in prayer); a. fr.—<i>Fem.</i> <span dir=\"rtl\">יְחִידָה</span>. <span class=\"citation\">Num. R. s. 12</span> <span dir=\"rtl\">בת י׳</span> an only daughter; a. fr.—<span class=\"citation\">Deut. R. s. 2</span>, end <span dir=\"rtl\">מה הקב&quot;ה … כך הנפש י׳ בגוף</span> as the Lord is matchless in his world, so is the soul in the body; <span class=\"citation\">Midr. Till. to Ps. CIII</span>; <span class=\"citation\">Gen. R. s. 14</span>, end <span dir=\"rtl\">שכל האברים … והיא י׳ בגוף</span> all limbs are paired, but she (the soul) is unmatched in the body.—As a noun (b. h.) <span dir=\"rtl\">יְחִידָה</span> <i>soul</i>. Ib. Deut. R. l. c.; a. e.</div><div class=\"sense\"><b>—2)</b> <i>select</i>, esp. <i>one devoted to a particularly scrupulous life</i>. <span class=\"citation\">Taan. 10ᵇ</span> <span dir=\"rtl\">איזהו י׳</span> who is called a <i>yaḥid</i>? Ans. <span dir=\"rtl\">י׳ כל שראוי וכ׳</span> whoever is worthy to be appointed manager of a community. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אל יאמר אדם … להיות י׳</span> one must not say, I am only a student, I am not fit to lead the life of a <i>yaḥid</i> (it would be an assumption, v. <a href=\"#\" data-headword=\"יוֹהֲרָא\">יוֹהֲרָא</a>); <span class=\"citation\">Tosef. ib. I, 7</span> (v. Var. in ed. Zuck. a. Rabb. D. S. to Taan. l. c.); <span class=\"citation\">Y. Ber. II, end, 5ᵈ</span> <span dir=\"rtl\">כל דבר של צער … י׳ עושה</span> in all matters of self-abnegation, whoever desires to make himself a <i>yaḥid</i>, may do so.—Pl. as ab. <span class=\"citation\">Taan. I, 4</span>; a. fr. V. <a href=\"#\" data-headword=\"יְחִידִי\">יְחִידִי</a></div>","alt":[]},"14389":{"h":"יָחִיד ²","r":"J00285","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Gen. XXII, 2</span>. <span class=\"citation\">Targ. Prov. IV, 3</span>; a. e.—<i>Fem.</i> <a href=\"#\" data-headword=\"יְחִידָאָה\">יְחִידָאָה</a>, <a href=\"#\" data-headword=\"יְחִידְתָּא\">יְחִידְתָּא</a>. <span class=\"citation\">Targ. Jud. XI, 34</span> (ed. Lag. <a href=\"#\" data-headword=\"יָחִיד ²\">יְחִידָא</a>, some ed. <span dir=\"rtl\">יְחִידָה</span>).—<span class=\"citation\">Ned. 51ᵃ</span> <span dir=\"rtl\">תספרתא י׳</span> a particular kind of hair-dressing.</div>","alt":["יָחִידָא","י׳"]},"14390":{"h":"יְחִידָאָה","r":"J00286","html":"<div class=\"sense\"> f., v. preced.—<a href=\"#\" data-headword=\"י׳\">י׳</a> m., v. <a href=\"#\" data-headword=\"יְחִידִי\">יְחִידִי</a> ch.</div>","alt":[]},"14391":{"h":"יְחִידִי","r":"J00287","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"יְחִידָאָה\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b> <i>singular, single, lonely</i>. <span class=\"citation\">Macc. 23ᵇ</span> <span dir=\"rtl\">בלשון י׳</span> in the singular number, opp. <span dir=\"rtl\">ל׳ רבים</span>.—<span class=\"citation\">Kidd. 20ᵃ</span> (expl. <span dir=\"rtl\">בגפו</span>, <span class=\"citation\">Ex. XXI, 3</span>) <span dir=\"rtl\">י׳ נכנס וכ׳</span> single (unmarried) he entered &amp;c. <span class=\"citation\">Ab. III, 4</span> <span dir=\"rtl\">המהלך בדרך י׳</span> who travels alone. <span class=\"citation\">Ib. IV, 8</span> <span dir=\"rtl\">אל תהי דן י׳ וכ׳</span> do not hold court as a single judge, for there is only One who judges singly; a. fr.—<i>Fem.</i> <a href=\"#\" data-headword=\"יְחִידִי\">יְחִידִית</a>. <span class=\"citation\">Y. Kil. II, 28ᵃ</span> bot. <span dir=\"rtl\">גפן י׳</span> a single (isolated) vine tree. <span class=\"citation\">Y. Ab. Zar. IV, 44ᵃ</span> top <span dir=\"rtl\">מצבה כל שהיא י׳</span> it is called <i>matsebah</i> when consisting of one piece (v. <a href=\"#\" data-headword=\"בִּימוּס\">בִּימוּס</a>); a. e.—Pl. <span dir=\"rtl\">יְחִידִיּוֹת</span>. <span class=\"citation\">Y. Kil. V, beg. 29ᵈ</span> <a href=\"#\" data-headword=\"בִּרְיְתָא\">בי׳</a> in the case of isolated vine trees. <span class=\"citation\">Y. Sot. IX, 23ᶜ</span> top <a href=\"#\" data-headword=\"י׳\">י׳</a> isolated tombstones.</div><div class=\"sense\"><b>—2)</b> <i>believer in One God</i>. <span class=\"citation\">Esth. R. to II, 5</span>, v. <a href=\"#\" data-headword=\"יְהוּדִי\">יְהוּדִי</a>.</div>","alt":[]},"14392":{"h":"יְחִידִי ²","r":"J00288","html":"<div class=\"sense\"><b>1)</b> <i>lonely; only one</i>. <span class=\"citation\">Targ. Ps. XXV, 16</span> (ed. Lag. <span dir=\"rtl\">יְחִידָאִי</span>).—<span class=\"citation\">Targ. Y. Deut. XXXII, 50</span> (ed. Amst. <span dir=\"rtl\">דָאֵי …</span> incorr.). <span class=\"citation\">Targ. Job XIV, 4</span> Ms. (ed. <a href=\"#\" data-headword=\"חַד I\">חד</a>).</div><div class=\"sense\"><b>—2)</b> <i>single authority, opinion of one</i>. <span class=\"citation\">Pes. 103ᵇ</span> <span dir=\"rtl\">לא יחידאה אנא</span> (v. Rabb. D. S. a. l.) I do not report the opinion of one man. <span class=\"citation\">Y. Ter. VI, beg. 44ᵃ</span> <span dir=\"rtl\">אתיא די׳ דהכא כסתמא דתמן וכ׳</span> the opinion of the single authority here agrees with the anonymous (editorially adopted) one there &amp;c.; Y. Ned. VII, beg. 40ᵇ. <span class=\"citation\">Y. Sabb. III, 6ᵃ</span> bot. <span dir=\"rtl\">לית אנן … לי׳</span> we need not consider the opinion of a single authority; a. fr.—Pl. <span dir=\"rtl\">יְחִידָאִין</span>, <span dir=\"rtl\">יְחִידָאֵי</span>, <span dir=\"rtl\">יְחִידָיִין</span>. <span class=\"citation\">Targ. Y. Gen. XXII, 10</span> (v. <a href=\"#\" data-headword=\"יָחִיד\">יָחִיד</a> 2).—<span class=\"citation\">B. Kam. 81ᵇ</span> bot. <span dir=\"rtl\">בי׳ לא אמרינן</span> we do not speak of single authorities. <span class=\"citation\">Y. Ḥag. II, 77ᵇ</span> top <a href=\"#\" data-headword=\"י׳\">י׳</a> single-handed, each for himself, v. <a href=\"#\" data-headword=\"טָעַן II\"><span dir=\"rtl\">טְעַן</span> II</a>.</div>","alt":["(… דַי)","יְחִידָאָה","דָאִי","יְחִידָיָיא"]},"14393":{"h":"יְחִידְתָּא","r":"J00289","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יָחִיד\">יָחִיד</a> ch.</div>","alt":[]},"14394":{"h":"יחֵיף","r":"J00290","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יְחֵף\">יְחֵף</a>, <a href=\"#\" data-headword=\"יָחֵף\"><a href=\"#\" data-headword=\"יָחֵף\">יָחֵף</a>.</a></div>","alt":["יְחֵיפ׳"]},"14395":{"h":"יְחֵיפָה","r":"J00291","html":"<div class=\"sense\"> m. ch., v. <a href=\"#\" data-headword=\"יָחוֹפָה\">יָחוֹפָה</a></div>","alt":[]},"14396":{"h":"*יַחְכִּים","r":"J00292","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"חֲכַם\">חַכִּים</a>. <span class=\"citation\">Targ. I Chr. IV, 9</span> ed. Beck, Var. ed. Rahmer <span dir=\"rtl\">ויח׳</span> (ed. <span dir=\"rtl\">וח׳</span>).</div>","alt":[]},"14397":{"h":"יָחַל","r":"J00293","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"חוּל\">חוּל</a>) <i>to hover around, rest on</i>.</div><div class=\"sense\"><b>Pi. יִחֵל  יִי׳</b> <div class=\"sense\"><b>1)</b>  (with (with <span dir=\"rtl\">על</span>) <i>to cause to rest upon</i>. <span class=\"citation\">Pesik. R. s. 47</span></div><div class=\"sense\"><b>—2)</b> (b. h.; <i>to wait for the turn, to wait, trust; to inspire trust</i>; v. <a href=\"#\" data-headword=\"יִחוּל\">יִחוּל</a>.</div></div><div class=\"sense\"><b>Hof. הוּחָל</b> <div class=\"sense\"><i>to be made to rest</i>. <span class=\"citation\">Sifré Deut. 31</span>, v. <a href=\"#\" data-headword=\"יוֹתֵר\">יוֹתֵר</a>.</div></div>","alt":[]},"14398":{"h":"*יָחַם","r":"J00294","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"חוּם\">חוּם</a>) <i>to be warm, hot</i>; <i>Pi</i>. <a href=\"#\" data-headword=\"יְחַם\">יִחֵם</a> <i>to heat</i>. <span class=\"citation\">Tosef. Sabb. III</span> (<span class=\"citation\">IV), 7</span> <span dir=\"rtl\">מְיַיחֵם</span>, v. <a href=\"#\" data-headword=\"חָמַם\">חָמַם</a>.—Pesik. Zutr. (ed. Bub.), Vayetsé 39 <span dir=\"rtl\">ליַחְמֶנָּה</span> to heat it (the flock). Ib. 41 <span dir=\"rtl\">לְיַחֵם</span>.</div>","alt":[]},"14399":{"h":"יְחַם","r":"J00295","html":"<div class=\"sense\"><span class=\"citation\">Targ. O. Gen. XVIII, 1</span>; <span class=\"citation\">Targ. II Sam. IV, 5</span> <a href=\"#\" data-headword=\"מֵיחַם\">מֵיחַם</a> (perh. fr. <a href=\"#\" data-headword=\"חֲמַם\">חֲמַם</a>).</div><div class=\"sense\"><b>Pa. יַחֵם</b> <div class=\"sense\"><i>to heat</i>. <span class=\"citation\">Targ. O. Gen. XXX, 41</span> <span dir=\"rtl\">ליָחָמוּתְהֵין</span> ed. Berl. (ed. <span dir=\"rtl\">ליַתֱמוֹתְהֶן</span>; Y. <span dir=\"rtl\">ליַחְמוּתְ׳</span>).</div></div><div class=\"sense\"><b>Ithpa. אִתְיַחַם</b> <div class=\"sense\"><i>to be heated, to conceive</i>. Ib. 38, sq.</div></div>","alt":[]}};
